pub(crate) fn bounding_pass(walk: &mut BoundsWalk, args: &[FnArg], body: &Block, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    walk.written.clear();
    walk.poisoned.clear();
    walk.written_ends.clear();
    walk.return_below = None;
    walk.return_names.clear();
    walk.return_seen.clear();
    walk.return_lost = false;
    walk.return_range = None;
    walk.return_unranged = false;
    walk.return_at_least = None;
    walk.return_within = None;
    walk.return_under = None;
    walk.return_lengths = None;
    walk.return_reaches = None;
    walk.return_alike = None;
    walk.return_measured.clear();
    let mut facts = BoundsFacts { ints: collections::BTreeSet::new(), facts: vec![], evicted: 0 };
    for arg in args.iter() {
        let name = nikaia_std::block::Text::from(words.resolve(arg.name).to_string());
        let ty = nikaia_std::block::Text::from(words.resolve(arg.ty.name).to_string());
        if arg.ty.generics.is_empty() && is_whole_number(&ty) {
            facts.ints.insert(nikaia_std::block::Text::from(name.to_string()));
            if ty.starts_with('u') { bounding_at_least_zero(walk, &mut facts, &name); }
        }
        if ty == "Vec" || ty == "List" || ty == "Array" || ty == "Bytes" { bounding_at_least_zero(walk, &mut facts, &length_of(&name)); }
    }
    for (name, range) in context.given.iter() {
        let range = *range;
        if !walk.shape.bound.contains(name) {
            facts.ints.insert(nikaia_std::block::Text::from(name.to_string()));
            bounding_bounded(walk, &mut facts, name, &range);
        }
    }
    for (name, range) in context.text_lengths.iter() {
        let range = *range;
        if !walk.shape.bound.contains(name) { bounding_bounded(walk, &mut facts, &length_of(name), &range); }
    }
    bounding_derived_entry(walk, &mut facts, args, body, context);
    for name in walk.return_assumed.copy_owned() { bounding_at_least_zero(walk, &mut facts, &name); }
    rules_given(walk, &mut facts, args, words);
    let mut bound: Vec<String> = vec![];
    let leaves = bounding_stmts(walk, body, 0, &mut facts, &mut bound, context, program, words, &mut *ask);
    if !leaves { rules_exit(walk, &facts, (rules_tail(body)).as_ref(), false, context, program, words, &mut *ask); }
    for row in walk.turn_rows.copy_owned() { bounding_trace_row(walk, row); }
}

pub(crate) fn bounding_return_range(walk: &mut BoundsWalk, facts: &BoundsFacts, returned: Option<&Expr>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if !walk.return_ranging || walk.return_unranged { return; }
    let value = match returned { Some(__nikaia_value) => __nikaia_value, None => {
        walk.return_unranged = true;
        return;
    } };
    let range = nikaia_std::index::or(bounding_range(walk, value, facts, context, program, words, &mut *ask), || Range::open());
    if !range.is_bounded() {
        walk.return_unranged = true;
        return;
    }
    walk.return_range = Some(match walk.return_range {
        None => range,
        Some(ref mut before) => before.join(&range),
    });
}

pub(crate) fn bounding_return_relations(walk: &mut BoundsWalk, facts: &BoundsFacts, returned: Option<&Expr>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if walk.return_scalars.is_empty() && walk.return_lens.is_empty() { return; }
    let mut at_least: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let mut within: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let mut under: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let term = match returned {
        None => None,
        Some(value) => bounding_lin(walk, value, facts, context, program, words),
    };
    if term.is_some() {
        let v = nikaia_std::index::or(term, || 0);
        for k in 0..walk.return_scalars.len() as i64 {
            let param = nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&walk.return_scalars, (k) as usize) }).to_string());
            if param.is_empty() { continue; }
            let p = walk.arena.var(&param);
            let goal = walk.arena.ge(v, p);
            if bounding_proves(&walk, facts, goal, &mut *ask) { at_least.insert(k); }
        }
        for k in 0..walk.return_lens.len() as i64 {
            let param = nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&walk.return_lens, (k) as usize) }).to_string());
            if param.is_empty() { continue; }
            let len = walk.arena.var(&length_of(&param));
            let goal = walk.arena.le(v, len);
            if bounding_proves(&walk, facts, goal, &mut *ask) {
                within.insert(k);
                let strict = walk.arena.lt(v, len);
                if bounding_proves(&walk, facts, strict, &mut *ask) { under.insert(k); }
            }
        }
    }
    if term.is_none() && returned.is_some() {
        let mut relations: Vec<(bool, i64)> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        match returned {
            None => { },
            Some(value) => { relations = bounding_relations_of(walk, facts, "result#", value, context, program, words, &mut *ask); },
        }
        for (least, bound) in relations.iter() {
            let least = nikaia_std::num::value(least);let bound = nikaia_std::num::value(bound);
            let names = if least { walk.return_scalars.copy_owned() } else { walk.return_lens.copy_owned() };
            for k in 0..names.len() as i64 {
                if (*unsafe { nikaia_std::proven::read(&names, (k) as usize) }).is_empty() { continue; }
                let goal = if least {
                    let p = walk.arena.var(unsafe { nikaia_std::proven::read(&names, (k) as usize) });
                    walk.arena.ge(bound, p)
                } else {
                    let len = walk.arena.var(&length_of(unsafe { nikaia_std::proven::read(&names, (k) as usize) }));
                    walk.arena.le(bound, len)
                };
                if bounding_proves(&walk, facts, goal, &mut *ask) {
                    if least { at_least.insert(k); } else {
                        within.insert(k);
                        let len = walk.arena.var(&length_of(unsafe { nikaia_std::proven::read(&names, (k) as usize) }));
                        let strict = walk.arena.lt(bound, len);
                        if bounding_proves(&walk, facts, strict, &mut *ask) { under.insert(k); }
                    }
                }
            }
        }
    }
    if walk.return_at_least.is_some() { at_least = bounding_kept(&nikaia_std::index::or(std::mem::take(&mut walk.return_at_least), || collections::BTreeSet::new().into()), &at_least); }
    if walk.return_within.is_some() { within = bounding_kept(&nikaia_std::index::or(std::mem::take(&mut walk.return_within), || collections::BTreeSet::new().into()), &within); }
    if walk.return_under.is_some() { under = bounding_kept(&nikaia_std::index::or(std::mem::take(&mut walk.return_under), || collections::BTreeSet::new().into()), &under); }
    walk.return_at_least = Some(at_least);
    walk.return_within = Some(within);
    walk.return_under = Some(under);
}

pub(crate) fn bounding_kept(before: &collections::BTreeSet<i64>, now: &collections::BTreeSet<i64>) -> collections::BTreeSet<i64> {
    let mut kept: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for k in before.iter() {
        let k = nikaia_std::num::value(k);
        if now.contains(&k) { kept.insert(k); }
    }
    kept
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_relations_of(walk: &mut BoundsWalk, facts: &BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Vec<(bool, i64)> {
    let mut out: Vec<(bool, i64)> = vec![];
    if bounding_found_options(value) { return out; }
    let callee = match bounding_found_key(&walk, value, context, words) { Some(__nikaia_value) => __nikaia_value, None => return out };
    walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
    let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return out };
    if found.each || found.pending { return out; }
    out.reserve(found.at_least.iter().size_hint().0); for k in found.at_least.iter() {
        let k = nikaia_std::num::value(k);
        let term = match bounding_found_term(walk, value, k, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !walk.arena.mentions(term, name) {
            out.push((true, term));
            continue;
        }
        let least = match bounding_term(walk, term, facts, &mut *ask).lo { Some(__nikaia_value) => __nikaia_value, None => continue };
        out.push((true, walk.arena.int(least)));
    }
    for k in found.within.iter() {
        let k = nikaia_std::num::value(k);
        let path = match bounding_found_path(value, found, k, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if walk.pinned.contains(&path_root(&path)) || path_within(&path, name) || path_within(name, &path) { continue; }
        let len = bounding_length_named(walk, &path, false);
        if found.under.contains(&k) {
            let one = walk.arena.int(1);
            out.push((false, walk.arena.sub(len, one)));
        } else { out.push((false, len)); }
    }
    out
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_relation_grows(walk: &mut BoundsWalk, facts: &BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    if bounding_found_options(value) { return false; }
    let callee = match bounding_found_key(&walk, value, context, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
    walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
    let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if found.each || found.pending { return false; }
    let now = walk.arena.var(name);
    for k in found.at_least.iter() {
        let k = nikaia_std::num::value(k);
        let term = match bounding_found_term(walk, value, k, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let goal = walk.arena.ge(term, now);
        if bounding_proves(&walk, facts, goal, &mut *ask) { return true; }
    }
    false
}

pub(crate) fn bounding_relations_push(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, relations: &[(bool, i64)]) {
    if relations.is_empty() { return; }
    let n = walk.arena.var(name);
    for (least, term) in relations.iter() {
        let least = nikaia_std::num::value(least);let term = nikaia_std::num::value(term);
        let fact = if least { walk.arena.ge(n, term) } else { walk.arena.le(n, term) };
        bounding_push(&walk, facts, fact);
    }
}

pub(crate) fn bounds_action_range(body: &Block, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<Range> {
    let none: Vec<FnArg> = vec![];
    let mut walk = bounding_new(&none, body, bp_names(&nonnegative_locals(body), words), context, program, words);
    walk.return_ranging = true;
    bounds_rounds(&mut walk, &none, body, context, program, words, &mut *ask);
    if walk.return_unranged || walk.return_lost { return None; }
    if seek_block(body, &Seek::Unvisited(walk.return_seen.copy_owned()), words) { return None; }
    match walk.return_range.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

pub(crate) fn bounding_found(walk: &BoundsWalk) -> collections::BTreeMap<String, Range> {
    let mut out: collections::BTreeMap<String, Range> = collections::BTreeMap::new();
    for (key, bound) in walk.written.iter() {
        let bound = *bound;
        if bound.is_bounded() && !bounding_poisoned(walk, key) && !key.starts_with('.') { out.insert(nikaia_std::block::Text::from(key.to_string()), bound.clone()); }
    }
    out
}

pub(crate) fn bounding_found_ends(walk: &BoundsWalk) -> collections::BTreeMap<String, collections::BTreeSet<String>> {
    let mut out: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for (key, lists) in walk.written_ends.iter() { if !lists.is_empty() { out.insert(nikaia_std::block::Text::from(key.to_string()), lists.copy_owned()); } }
    out
}

pub(crate) fn bounding_poisoned(walk: &BoundsWalk, key: &str) -> bool {
    let mut at = key_root(key);
    let parts: Vec<&str> = key.split('[').collect::<Vec<_>>();
    for _part in 0..parts.len() as i64 {
        if walk.poisoned.contains(&at) { return true; }
        at.push_str("[]");
    }
    false
}

pub(crate) fn bounding_assumed(walk: &mut BoundsWalk, key: &str) -> Option<Range> {
    if key.starts_with('.') { walk.assumed_read.insert(nikaia_std::block::Text::from(key.to_string())); }
    let bound = match walk.assumed.get(key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(bound.clone())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_write(walk: &mut BoundsWalk, key: &str, value: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if !tracks(&walk.shape, key) { return; }
    let inner = format!("{}[]", key);
    match value {
        Expr::ListLit { items, .. } => {
            for item in items.iter() { bounding_write(walk, &inner, item, facts, context, program, words, &mut &mut *ask); }
            return;
        },
        Expr::ListRepeat { value: item, .. } => {
            let item = nikaia_std::boxed::open(item);
            bounding_write(walk, &inner, item, facts, context, program, words, &mut &mut *ask);
            return;
        },
        _ => { },
    }
    bounding_end_write(walk, key, value, facts, context, program, words, &mut &mut *ask);
    let range = bounding_range(walk, value, facts, context, program, words, &mut &mut *ask);
    if range.is_some() {
        bounding_join(walk, key, nikaia_std::index::or(range, || Range::open()));
        return;
    }
    let elements = elements_key(&walk.shape, value, words);
    if elements.is_some() {
        let bound = bounding_assumed(walk, nikaia_std::index::or(elements.as_deref(), || ""));
        if bound.is_some() { bounding_join(walk, &inner, nikaia_std::index::or(bound, || Range::open())); } else { walk.poisoned.insert(inner); }
        return;
    }
    walk.poisoned.insert(nikaia_std::block::Text::from(key.to_string()));
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_end_write(walk: &mut BoundsWalk, key: &str, value: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if key.contains('[') || key.starts_with('.') || walk.unread.contains(key) { return; }
    let mut below: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut only = match walk.written_ends.get(key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if only.is_none() && !walk.collecting {
        only = Some(nikaia_std::index::or(match walk.assumed_ends.get(key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || collections::BTreeSet::new().into()));
    }
    let term = bounding_lin(walk, value, facts, context, program, words);
    if term.is_some() {
        let v = nikaia_std::index::or(term, || 0);
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        for fact in facts.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            walk.arena.variables(fact, &mut read);
        }
        let zero = walk.arena.int(0);
        for name in read.iter() {
            let list = match name.strip_suffix(".len()") { Some(__nikaia_value) => __nikaia_value, None => continue };
            if only.is_some() && !nikaia_std::index::or(match only.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.contains(list)),
                None => None,
            }, || false) { continue; }
            if !bounding_end_list(&walk, list, key) { continue; }
            let low = walk.arena.ge(v, zero);
            let len = walk.arena.var(name);
            let high = walk.arena.lt(v, len);
            let goal = walk.arena.and(vec![low, high]);
            if bounding_proves(&walk, facts, goal, &mut *ask) { below.insert(nikaia_std::block::Text::from(list.to_string())); }
        }
    } else {
        match value {
            Expr::Index { base, .. } => {
                let base = nikaia_std::boxed::open(base);
                let from = nikaia_std::index::or(elements_key(&walk.shape, base, words), || "".into());
                below = nikaia_std::index::or(match walk.assumed_ends.get(&from) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || collections::BTreeSet::new().into());
            },
            _ => { },
        }
    }
    let was = match walk.written_ends.get(key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if was.is_some() {
        let mut kept: collections::BTreeSet<String> = collections::BTreeSet::new();
        for list in nikaia_std::index::or(was, || collections::BTreeSet::new().into()) { if below.contains(&list) { kept.insert(nikaia_std::block::Text::from(list.to_string())); } }
        below = kept;
    }
    walk.written_ends.insert(nikaia_std::block::Text::from(key.to_string()), below);
}

pub(crate) fn bounding_end_list(walk: &BoundsWalk, list: &str, key: &str) -> bool {
    let root = path_root(list);
    if root == key_root(key) || !walk.end_roots.contains(&root) || walk.pinned.contains(&root) { return false; }
    if walk.steady.falls.contains(list) { return false; }
    for name in walk.steady.values.iter() { if list == name || ::core::convert::identity(match (AsRef::<str>::as_ref(&(list)), AsRef::<str>::as_ref(&(name)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix(".")).is_some() }) { return false; } }
    for name in walk.steady.parts.iter() { if ::core::convert::identity(match (AsRef::<str>::as_ref(&(list)), AsRef::<str>::as_ref(&(name)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix(".")).is_some() }) { return false; } }
    true
}

pub(crate) fn bounding_end_facts(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, key: &str) {
    let ends = match walk.assumed_ends.get(key) { Some(__nikaia_value) => __nikaia_value, None => return };
    if ends.is_empty() { return; }
    let lists = ends.copy_owned();
    let n = walk.arena.var(name);
    let zero = walk.arena.int(0);
    facts.ints.insert(nikaia_std::block::Text::from(name.to_string()));
    let low = walk.arena.ge(n, zero);
    bounding_push(&walk, facts, low);
    for list in lists.iter() {
        let len = walk.arena.var(&length_of(list));
        let high = walk.arena.lt(n, len);
        bounding_push(&walk, facts, high);
    }
}

pub(crate) fn bounding_end_inside(walk: &mut BoundsWalk, len: i64, index: &Expr, facts: &BoundsFacts, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let base = match index {
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); base },
        _ => return false,
    };
    let key = match elements_key(&walk.shape, base, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !walk.assumed_ends.contains_key(&key) { return false; }
    let mut known = BoundsFacts { ints: facts.ints.copy_owned(), facts: facts.facts.copy_owned(), evicted: facts.evicted };
    let each = format!("{}.end()", key);
    bounding_end_facts(walk, &mut known, &each, &key);
    let n = walk.arena.var(&each);
    let zero = walk.arena.int(0);
    let low = walk.arena.ge(n, zero);
    let high = walk.arena.lt(n, len);
    let goal = walk.arena.and(vec![low, high]);
    bounding_proves_goal(walk, &known, goal, &mut *ask)
}

pub(crate) fn bounding_field_inits(walk: &mut BoundsWalk, fields: &[FieldInit], facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    for field in fields.iter() {
        let name = words.resolve(field.name);
        let key = format!(".{}", name);
        if !walk.shape.fields.contains(&key) { continue; }
        if field.value.is_some() {
            bounding_field_list(walk, &key, match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue }, facts, context, program, words, &mut *ask);
            continue;
        }
        let mut elements: Option<String> = None;
        if walk.shape.roots.contains(name) { elements = Some(nikaia_std::block::Text::from(name.to_string())); } else {
            elements = match walk.shape.aliases.get(name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
        }
        let bound = bounding_assumed(walk, nikaia_std::index::or(elements.as_deref(), || ""));
        if elements.is_some() && bound.is_some() { bounding_join(walk, &key, nikaia_std::index::or(bound, || Range::open())); } else { walk.poisoned.insert(key); }
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_field_list(walk: &mut BoundsWalk, key: &str, value: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    match value {
        Expr::ListLit { items, .. } => {
            for item in items.iter() { bounding_write(walk, key, item, facts, context, program, words, &mut *ask); }
            return;
        },
        Expr::ListRepeat { value: item, .. } => {
            let item = nikaia_std::boxed::open(item);
            bounding_write(walk, key, item, facts, context, program, words, &mut *ask);
            return;
        },
        _ => { },
    }
    if is_empty_map(value, words) { return; }
    let elements = elements_key(&walk.shape, value, words);
    if elements.is_some() {
        let bound = bounding_assumed(walk, nikaia_std::index::or(elements.as_deref(), || ""));
        if bound.is_some() {
            bounding_join(walk, key, nikaia_std::index::or(bound, || Range::open()));
            return;
        }
    }
    walk.poisoned.insert(nikaia_std::block::Text::from(key.to_string()));
}

pub(crate) fn bounding_join(walk: &mut BoundsWalk, key: &str, range: Range) {
    if !range.is_bounded() {
        walk.poisoned.insert(nikaia_std::block::Text::from(key.to_string()));
        return;
    }
    let mut joined = range;
    let was = walk.written.get(key);
    if was.is_some() { joined = nikaia_std::index::or(was, || Range::open()).join(&range); }
    walk.written.insert(nikaia_std::block::Text::from(key.to_string()), joined);
}

pub(crate) fn bounding_proves_goal(walk: &mut BoundsWalk, facts: &BoundsFacts, goal: i64, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    if bounding_proves(&walk, facts, goal, &mut *ask) {
        bounding_traced(walk, facts, goal, true);
        return true;
    }
    bounding_traced(walk, facts, goal, false);
    bounding_missed(walk, facts, goal);
    false
}

pub(crate) fn bounding_tracing(walk: &BoundsWalk) -> bool { walk.trace.len() == 2 && !walk.collecting && walk.at >= *unsafe { nikaia_std::proven::read(&walk.trace, (0) as usize) } && walk.at < *unsafe { nikaia_std::proven::read(&walk.trace, (1) as usize) } }

pub(crate) fn bounding_traced(walk: &mut BoundsWalk, facts: &BoundsFacts, goal: i64, proved: bool) {
    if !bounding_tracing(&walk) { return; }
    let verdict = if proved { "proved" } else { "open" };
    let mut known: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for fact in bounding_known(&walk, facts, goal) { known.push(walk.arena.text(fact)); }
    let mut rules: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    rules.reserve(walk.rules.iter().size_hint().0); for rule in walk.rules.iter() { rules.push(if rule.times == 1 { format!("{}: {} {} {}", rule.owner, rule.kind, rule.a, rule.b) } else { format!("{}: {} {} {}*{}", rule.owner, rule.kind, rule.a, rule.times, rule.b) }); }
    let held = if known.is_empty() { String::from("none") } else { nikaia_std::block::Text::from(known.join(", ")) };
    let found = if rules.is_empty() { String::from("none") } else { nikaia_std::block::Text::from(rules.join(", ")) };
    let connected = bounding_nearest(&walk, facts, goal, facts.facts.len() as i64).iter().copied().filter(|&taken| { taken }).count() as i64;
    ({ let __nikaia_arg1 = format!("  goal {}: {}\n    facts ({} asked; {} connected of {} held, {} evicted by the cap of {}): {}\n    rules: {}", walk.arena.text(goal), verdict, known.len() as i64, connected, facts.facts.len() as i64, facts.evicted, most_held(), held, found); bounding_trace_row(walk, __nikaia_arg1) });
}

pub(crate) fn bounding_turn_row(walk: &mut BoundsWalk, at: i64, row: String) { if walk.trace.len() == 2 && at >= *unsafe { nikaia_std::proven::read(&walk.trace, (0) as usize) } && at < *unsafe { nikaia_std::proven::read(&walk.trace, (1) as usize) } && !nikaia_std::list::contains(&walk.turn_rows, &row) { walk.turn_rows.push(row); } }

pub(crate) fn bounding_texts(walk: &BoundsWalk, terms: &[i64]) -> String {
    let mut out: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    out.reserve(terms.iter().size_hint().0); for term in terms.iter() {
        let term = nikaia_std::num::value(term);
        out.push(walk.arena.text(term));
    }
    if out.is_empty() { String::from("none") } else { nikaia_std::block::Text::from(out.join(", ")) }
}

pub(crate) fn bounding_trace_row(walk: &mut BoundsWalk, row: String) { if !nikaia_std::list::contains(&walk.proven.trace, &row) { walk.proven.trace.push(row); } }

pub(crate) fn bounding_missed(walk: &mut BoundsWalk, facts: &BoundsFacts, goal: i64) {
    if walk.through_loops {
        walk.open += 1;
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(goal, &mut read);
        #[allow(unused_mut)] let mut tied: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        let mut from: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block); #[allow(unused_mut, clippy::redundant_locals)] let mut tied = tied;
        from.reserve(read.iter().size_hint().0); for name in read.iter() { from.push(nikaia_std::block::Text::from(name.to_string())); }
        while !from.is_empty() {
            let mut next: Vec<String> = vec![];
            for fact in facts.facts.iter() {
                let fact = nikaia_std::num::value(fact);
                let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
                walk.arena.variables(fact, &mut names);
                if names.len() != 2 { continue; }
                let mut touches = false;
                for name in names.iter() { if nikaia_std::list::contains(&from, &name) { touches = true; } }
                let equal = matches!(walk.arena.at(fact), logic::SolverTerm::Eq(_, _));
                if touches {
                    for name in names.iter() {
                        if !read.contains(name) && !nikaia_std::list::contains(&tied, &name) {
                            tied.push(nikaia_std::block::Text::from(name.to_string()));
                            if equal || name.contains('#') || name.contains('@') { next.push(nikaia_std::block::Text::from(name.to_string())); }
                        }
                    }
                }
            }
            from = next;
        }
        for name in read.iter() { walk.missed.insert(nikaia_std::block::Text::from(name.to_string()), walk.open); }
        for name in tied.iter() { walk.missed.insert(nikaia_std::block::Text::from(name.to_string()), walk.open); }
        walk.missed_goals.push(BoundsMissed { stamp: walk.open, goal, facts: facts.facts.copy_owned() });
        if walk.missed_goals.len() > 64 { walk.missed_goals.remove(0); }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct BoundsMissed {
    pub(crate) stamp: i64,
    pub(crate) goal: i64,
    pub(crate) facts: Vec<i64>,
}

pub(crate) fn bounding_proves(walk: &BoundsWalk, facts: &BoundsFacts, goal: i64, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool { ask(&walk.arena, &bounding_known(walk, facts, goal), goal) }

pub(crate) fn bounding_nearest(walk: &BoundsWalk, facts: &BoundsFacts, asked: i64, most: i64) -> Vec<bool> {
    let mut names: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut starts: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    starts.reserve(facts.facts.iter().size_hint().0); for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        starts.push(names.len() as i64);
        for v in walk.arena.variable_ids(fact) {
            let v = nikaia_std::num::value(v);
            names.push(v);
        }
    }
    let held = starts.len() as i64;
    for (_, axiom) in walk.axioms.iter() {
        let mut own: Vec<i64> = vec![];
        for fact in axiom.iter() {
            let fact = nikaia_std::num::value(fact);
            own = bounding_merged_ids(&own, walk.arena.variable_ids(fact));
        }
        if own.len() > 1 {
            starts.push(names.len() as i64);
            names.reserve(own.iter().size_hint().0); for v in own.iter() {
                let v = nikaia_std::num::value(v);
                names.push(v);
            }
        }
    }
    let mut count_names = walk.arena.variable_count();
    let mut unread: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (each, fact) in walk.rule_facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let read = walk.arena.variable_ids(fact);
        let mut id = nikaia_std::index::or(walk.arena.variable_id(each), || -1);
        if id < 0 {
            id = nikaia_std::index::or(unread.get(each), || count_names);
            if id == count_names {
                unread.insert(nikaia_std::block::Text::from(each.to_string()), id);
                count_names += 1;
            }
        }
        let mut size = read.len() as i64;
        if !read.contains(&id) { size = unsafe { nikaia_std::proven::add::<i64>(size, 1) }; }
        if size > 1 {
            starts.push(names.len() as i64);
            names.push(id);
            for v in read.iter() {
                let v = nikaia_std::num::value(v);
                if v != id { names.push(v); }
            }
        }
    }
    let ways = starts.len() as i64;
    starts.push(names.len() as i64);
    let mut readers: Vec<Vec<i64>> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut reached: Vec<bool> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for _ in 0..count_names {
        readers.push(vec![]);
        reached.push(false);
    }
    for k in 0..ways { for j in *unsafe { nikaia_std::proven::read(&starts, (k) as usize) }..*unsafe { nikaia_std::proven::read(&starts, (nikaia_std::proven::add::<i64>(k, 1)) as usize) } { readers[nikaia_std::index::at(names[nikaia_std::index::at(j)])].push(k); } }
    let mut near: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut taken: Vec<bool> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut open: Vec<i64> = vec![];
    for k in 0..ways {
        if *unsafe { nikaia_std::proven::read(&starts, (k) as usize) } == *unsafe { nikaia_std::proven::read(&starts, (nikaia_std::proven::add::<i64>(k, 1)) as usize) } {
            near.push(0);
            bounding_open_push(&mut open, bounding_open_key(0, k));
        } else { near.push(-1); }
        taken.push(false);
    }
    for v in walk.arena.variable_ids(asked) {
        let v = nikaia_std::num::value(v);
        if v >= count_names || *nikaia_std::index::get(&reached, nikaia_std::index::at(v)) { continue; }
        { let __nikaia_stored = true; nikaia_std::index::set(&mut reached, nikaia_std::index::at(v), __nikaia_stored); }
        let through = (*nikaia_std::index::get(&readers, nikaia_std::index::at(v))).len() as i64;
        for k in (*unsafe { nikaia_std::proven::read(&readers, (v) as usize) }).iter() {
            let k = nikaia_std::num::value(k);
            if *nikaia_std::index::get(&near, nikaia_std::index::at(k)) < 0 || through < *unsafe { nikaia_std::proven::read(&near, (k) as usize) } {
                { let __nikaia_stored = through; unsafe { nikaia_std::proven::write(&mut near, (k) as usize, __nikaia_stored) }; }
                bounding_open_push(&mut open, bounding_open_key(through, k));
            }
        }
    }
    let mut count: i64 = 0;
    while count < most && !open.is_empty() {
        let key = bounding_open_pop(&mut open);
        let best = unsafe { nikaia_std::proven::sub::<i64>(2147483647, key % 4294967296i64) };
        if *nikaia_std::index::get(&taken, nikaia_std::index::at(best)) || *unsafe { nikaia_std::proven::read(&near, (best) as usize) } != key / 4294967296i64 { continue; }
        { let __nikaia_stored = true; unsafe { nikaia_std::proven::write(&mut taken, (best) as usize, __nikaia_stored) }; }
        if best < held { count = unsafe { nikaia_std::proven::add::<i64>(count, 1) }; }
        for j in *unsafe { nikaia_std::proven::read(&starts, (best) as usize) }..*unsafe { nikaia_std::proven::read(&starts, (nikaia_std::proven::add::<i64>(best, 1)) as usize) } {
            let v = *nikaia_std::index::get(&names, nikaia_std::index::at(j));
            if *nikaia_std::index::get(&reached, nikaia_std::index::at(v)) { continue; }
            { let __nikaia_stored = true; unsafe { nikaia_std::proven::write(&mut reached, (v) as usize, __nikaia_stored) }; }
            let through = *unsafe { nikaia_std::proven::read(&near, (best) as usize) } + (*unsafe { nikaia_std::proven::read(&readers, (v) as usize) }).len() as i64;
            for k in (*unsafe { nikaia_std::proven::read(&readers, (v) as usize) }).iter() {
                let k = nikaia_std::num::value(k);
                if *nikaia_std::index::get(&taken, nikaia_std::index::at(k)) { continue; }
                if *unsafe { nikaia_std::proven::read(&near, (k) as usize) } < 0 || through < *unsafe { nikaia_std::proven::read(&near, (k) as usize) } {
                    { let __nikaia_stored = through; unsafe { nikaia_std::proven::write(&mut near, (k) as usize, __nikaia_stored) }; }
                    bounding_open_push(&mut open, bounding_open_key(through, k));
                }
            }
        }
    }
    let mut out: Vec<bool> = vec![];
    for k in 0..held { out.push(*unsafe { nikaia_std::proven::read(&taken, (k) as usize) }); }
    out
}

pub(crate) fn bounding_open_key(near: i64, k: i64) -> i64 { near * 4294967296i64 + (2147483647 - k) }

pub(crate) fn bounding_open_push(open: &mut Vec<i64>, key: i64) {
    let mut i = open.len() as i64;
    open.push(key);
    while i > 0 {
        let parent = (unsafe { nikaia_std::proven::sub::<i64>(i, 1) }) / 2;
        if *unsafe { nikaia_std::proven::read(&open, (parent) as usize) } <= key { break; }
        { let __nikaia_stored = *unsafe { nikaia_std::proven::read(&open, (parent) as usize) }; unsafe { nikaia_std::proven::write(&mut *open, (i) as usize, __nikaia_stored) }; }
        i = parent;
    }
    { let __nikaia_stored = key; nikaia_std::index::set(&mut *open, nikaia_std::index::at(i), __nikaia_stored); }
}

pub(crate) fn bounding_open_pop(open: &mut Vec<i64>) -> i64 {
    let top = *unsafe { nikaia_std::proven::read(&open, (0) as usize) };
    let last = unsafe { nikaia_std::proven::sub::<i64>(open.len() as i64, 1) };
    let key = *unsafe { nikaia_std::proven::read(&open, (last) as usize) };
    open.truncate(nikaia_std::count::of(last));
    let n = last;
    if n > 0 {
        let mut i: i64 = 0;
        loop {
            let left: i64 = 2 * i + 1;
            if left >= n { break; }
            let right: i64 = unsafe { nikaia_std::proven::add::<i64>(left, 1) };
            let child: i64 = if right < n && *unsafe { nikaia_std::proven::read(&open, (right) as usize) } < *unsafe { nikaia_std::proven::read(&open, (left) as usize) } { right } else { left };
            if key <= *unsafe { nikaia_std::proven::read(&open, (child) as usize) } { break; }
            { let __nikaia_stored = *unsafe { nikaia_std::proven::read(&open, (child) as usize) }; unsafe { nikaia_std::proven::write(&mut *open, (i) as usize, __nikaia_stored) }; }
            i = child;
        }
        { let __nikaia_stored = key; nikaia_std::index::set(&mut *open, nikaia_std::index::at(i), __nikaia_stored); }
    }
    top
}

pub(crate) fn bounding_merged_ids(a: &[i64], b: &[i64]) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    let mut i: i64 = 0;
    let mut j: i64 = 0;
    while ((i) as usize) < a.len() && ((j) as usize) < b.len() {
        if *unsafe { nikaia_std::proven::read(&a, (i) as usize) } < *unsafe { nikaia_std::proven::read(&b, (j) as usize) } {
            out.push(*unsafe { nikaia_std::proven::read(&a, (i) as usize) });
            i = unsafe { nikaia_std::proven::add::<i64>(i, 1) };
        } else if *unsafe { nikaia_std::proven::read(&b, (j) as usize) } < *unsafe { nikaia_std::proven::read(&a, (i) as usize) } {
            out.push(*unsafe { nikaia_std::proven::read(&b, (j) as usize) });
            j = unsafe { nikaia_std::proven::add::<i64>(j, 1) };
        } else {
            out.push(*unsafe { nikaia_std::proven::read(&a, (i) as usize) });
            i = unsafe { nikaia_std::proven::add::<i64>(i, 1) };
            j = unsafe { nikaia_std::proven::add::<i64>(j, 1) };
        }
    }
    while ((i) as usize) < a.len() {
        out.push(*unsafe { nikaia_std::proven::read(&a, (i) as usize) });
        i = unsafe { nikaia_std::proven::add::<i64>(i, 1) };
    }
    while ((j) as usize) < b.len() {
        out.push(*unsafe { nikaia_std::proven::read(&b, (j) as usize) });
        j = unsafe { nikaia_std::proven::add::<i64>(j, 1) };
    }
    out
}

pub(crate) fn bounding_known(walk: &BoundsWalk, facts: &BoundsFacts, asked: i64) -> Vec<i64> {
    let mut all: Vec<i64> = vec![];
    if (facts.facts.len() as i64) <= most_facts() { all = facts.facts.copy_owned(); } else {
        let asking = bounding_nearest(walk, facts, asked, most_facts());
        for k in 0..facts.facts.len() as i64 { if *nikaia_std::index::get(&asking, (k) as usize) { all.push(*unsafe { nikaia_std::proven::read(&facts.facts, (k) as usize) }); } }
    }
    if !walk.rule_facts.is_empty() {
        let mut read: Vec<bool> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        for _ in 0..walk.arena.variable_count() { read.push(false); }
        for v in walk.arena.variable_ids(asked) {
            let v = nikaia_std::num::value(v);
            { let __nikaia_stored = true; nikaia_std::index::set(&mut read, nikaia_std::index::at(v), __nikaia_stored); }
        }
        for fact in all.iter() {
            let fact = nikaia_std::num::value(fact);
            for v in walk.arena.variable_ids(fact) {
                let v = nikaia_std::num::value(v);
                { let __nikaia_stored = true; nikaia_std::index::set(&mut read, nikaia_std::index::at(v), __nikaia_stored); }
            }
        }
        for (each, fact) in walk.rule_facts.iter() {
            let fact = nikaia_std::num::value(fact);
            let id = nikaia_std::index::or(walk.arena.variable_id(each), || -1);
            if id >= 0 && *nikaia_std::index::get(&read, nikaia_std::index::at(id)) && rules_standing(walk, facts, fact) { all.push(fact); }
        }
    }
    for (name, axiom) in walk.axioms.iter() {
        if !walk.unsized_names.contains(name) {
            all.reserve(axiom.iter().size_hint().0); for fact in axiom.iter() {
                let fact = nikaia_std::num::value(fact);
                all.push(fact);
            }
        }
    }
    for (_, defined) in walk.defining.iter() {
        all.reserve(defined.iter().size_hint().0); for fact in defined.iter() {
            let fact = nikaia_std::num::value(fact);
            all.push(fact);
        }
    }
    for (name, floor) in walk.floors.iter() {
        let floor = nikaia_std::num::value(floor);
        if walk.unsized_names.contains(name) { all.push(floor); }
    }
    all
}

pub(crate) fn bounding_term(walk: &mut BoundsWalk, term: i64, facts: &BoundsFacts, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Range {
    let known = walk.arena.constant(term);
    if known.is_some() { return Range::exactly(nikaia_std::index::or(known, || 0)); }
    let guess = candidate(term, &bounding_known(&walk, facts, term), &mut |at| { walk.arena.at(at) });
    let mut confirmed = Range::open();
    if guess.hi.is_some() {
        let hi = nikaia_std::index::or(guess.hi, || 0);
        let k = walk.arena.int(hi);
        let goal = walk.arena.le(term, k);
        if bounding_proves(&walk, facts, goal, &mut *ask) { confirmed.hi = Some(hi); }
    }
    if guess.lo.is_some() {
        let lo = nikaia_std::index::or(guess.lo, || 0);
        let k = walk.arena.int(lo);
        let goal = walk.arena.ge(term, k);
        if bounding_proves(&walk, facts, goal, &mut *ask) { confirmed.lo = Some(lo); }
    }
    confirmed
}

pub(crate) fn bounding_type_of(walk: &BoundsWalk, expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(name, _) => {
            let name = *name;
            let ty = match walk.typed.get(words.resolve(name)) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(nikaia_std::block::Text::from(ty.to_string()));
        },
        Expr::Field { .. } => { },
        Expr::Index { .. } => { },
        _ => { return None; },
    }
    let ty = match context.whole_types.get(&node_key(expr)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(nikaia_std::block::Text::from(ty.to_string()))
}

pub(crate) fn bounding_range(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<Range> {
    let term = bounding_lin(walk, expr, facts, context, program, words);
    if term.is_some() {
        let found = bounding_term(walk, nikaia_std::index::or(term, || 0), facts, &mut &mut *ask);
        if !bounding_reads_own(&walk, nikaia_std::index::or(term, || 0)) { return Some(found); }
        let shaped = match bounding_range_shaped(walk, expr, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return Some(found) };
        let solved = found;
        return Some(solved.meet(&shaped));
    }
    bounding_range_shaped(walk, expr, facts, context, program, words, &mut &mut *ask)
}

pub(crate) fn bounding_range_shaped(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<Range> {
    match expr {
        Expr::Binary { op, lhs, rhs, span, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); return bounding_range_of(walk, op, lhs, rhs, span.start as i64, facts, context, program, words, &mut &mut *ask); },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Neg => {
                    let inner = match bounding_range(walk, expr, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(inner.neg());
                },
                _ => { },
            }
        },
        Expr::Cast { expr, ty, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if ty.generics.is_empty() {
                let into = match Range::held_by_type(words.resolve(ty.name)) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let got = match bounding_range(walk, expr, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return Some(into) };
                return Some(got.meet(&into));
            }
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if args.is_empty() {
                let name = words.resolve(method);
                if name == "len" { return Some(Range { lo: Some(0), hi: None }); }
                if name.starts_with("bits_as_") || name.starts_with("truncating_") {
                    let mut dropped: i64 = 11;
                    if name.starts_with("bits_as_") { dropped = 8; }
                    let into = match Range::held_by_type(&bounding_dropped(name, dropped)) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    let got = match bounding_range(walk, receiver, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return Some(into) };
                    if into.holds(&got) { return Some(got); }
                    return Some(into);
                }
            }
            if args.len() == 1 && words.resolve(method) == "get" {
                let key = match elements_key(&walk.shape, receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return bounding_assumed(walk, &key);
            }
            if !bounding_found_options(expr) {
                let callee = match bounding_found_key(&walk, expr, context, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
                let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
                if found.each || found.pending { return None; }
                return match found.range.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                };
            }
        },
        Expr::Index { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            let key = match elements_key(&walk.shape, base, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return bounding_assumed(walk, &key);
        },
        Expr::Call { func, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            if !config.is_empty() { return None; }
            let callee = match bounding_found_key(&walk, expr, context, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
            let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if found.each || found.pending { return None; }
            return match found.range.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
        },
        Expr::If { cond, then_branch, else_branch, .. } => { let cond = nikaia_std::boxed::open(cond); return bounding_if_range(walk, cond, then_branch, (else_branch).as_ref(), facts, context, program, words, &mut &mut *ask); },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            let held = match bounding_range(walk, value, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if bounding_leaves(fallback) { return Some(held); }
            let otherwise = match bounding_range(walk, fallback, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let joined = held.join(&otherwise);
            if joined.is_bounded() { return Some(joined); }
        },
        _ => { },
    }
    None
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_if_range(walk: &mut BoundsWalk, cond: &Expr, then_branch: &Block, else_branch: Option<&Block>, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<Range> {
    let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return None };
    let decided = bounding_decided(&walk, cond, context, words);
    let mut then_range: Option<Range> = None;
    if nikaia_std::index::or(decided, || true) {
        let mut then_facts = facts.clone();
        bounding_assume(walk, &mut then_facts, cond, context, program, words);
        then_range = bounding_arm_range(walk, then_branch, &then_facts, context, program, words, &mut &mut *ask);
        if decided.is_some() { return then_range; }
    }
    let mut else_facts = facts.clone();
    bounding_assume_not(walk, &mut else_facts, cond, context, program, words);
    let else_range = match bounding_arm_range(walk, otherwise, &else_facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if decided.is_some() { return Some(else_range); }
    let first = match then_range { Some(__nikaia_value) => __nikaia_value, None => return None };
    let joined = first.join(&else_range);
    if joined.is_bounded() { return Some(joined); }
    None
}

pub(crate) fn bounding_arm_range(walk: &mut BoundsWalk, arm: &Block, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<Range> {
    if arm.stmts.len() != 1 { return None; }
    match &unsafe { nikaia_std::proven::read(&arm.stmts, (0) as usize) }.node {
        Stmt::Expr(value) => bounding_range(walk, value, facts, context, program, words, &mut &mut *ask),
        _ => None,
    }
}

pub(crate) fn bounding_decided(walk: &BoundsWalk, cond: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Option<bool> {
    match cond {
        Expr::Variable(name, _) => {
            let name = *name;
            let text = words.resolve(name);
            if walk.shape.bound.contains(text) { return None; }
            return (*nikaia_std::index::get(&context.decided, text)).copied();
        },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Not => {
                    let inner = match bounding_decided(walk, expr, context, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(!inner);
                },
                _ => { },
            }
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_dropped(text: &str, count: i64) -> String {
    let c: Vec<scalar> = nikaia_std::list::scalars(text.chars());
    let mut out: String = String::from("");
    for k in count..c.len() as i64 { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_range_of(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, at: i64, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<Range> {
    match op {
        BinaryOp::Add => {
            let a = match bounding_range(walk, lhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_range(walk, rhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(a.add(&b));
        },
        BinaryOp::Sub => {
            let a = match bounding_range(walk, lhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_range(walk, rhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(a.add(&b.neg()));
        },
        BinaryOp::Mul => {
            let a = match bounding_range(walk, lhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_range(walk, rhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(a.mul(&b));
        },
        BinaryOp::Div => {
            let d = match bounding_range(walk, rhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let d1 = match d.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
            let d2 = match d.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
            if d1 < 1 { return None; }
            let mut x = nikaia_std::index::or(bounding_range(walk, lhs, facts, context, program, words, &mut &mut *ask), || Range::open());
            let ty = bounding_type_of(&walk, lhs, context, words);
            if ty.is_some() {
                let held = Range::held_by_type(nikaia_std::index::or(ty.as_deref(), || ""));
                if held.is_some() { x = x.meet(&nikaia_std::index::or(held, || Range::open())); }
            }
            let mut out = Range::open();
            if x.lo.is_some() {
                let a = nikaia_std::index::or(x.lo, || 0);
                out.lo = Some(if a >= 0 { a / d2 } else { a / d1 });
            }
            if x.hi.is_some() {
                let b = nikaia_std::index::or(x.hi, || 0);
                out.hi = Some(if b >= 0 { b / d1 } else { b / d2 });
            }
            return Some(out);
        },
        BinaryOp::Rem => {
            let n = match bounding_range(walk, rhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let low = match n.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
            let high = match n.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
            if low < 1 { return None; }
            let x = bounding_range(walk, lhs, facts, context, program, words, &mut &mut *ask);
            return Some(bounding_remainder((x).as_ref(), high));
        },
        BinaryOp::Shr => {
            let by = match bounding_range(walk, rhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let k = match by.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
            let same = match by.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
            if k != same || k < 0 || k >= 64 { return None; }
            let mut widest: Option<Range> = None;
            let ty = nikaia_std::index::or(*nikaia_std::index::get(&context.shifts, &at), || "");
            let width = nikaia_std::index::or(bounding_bits(ty), || 0);
            if ty.starts_with('u') && width > 0 && k >= 1 && k < width {
                let most = (1 << (unsafe { nikaia_std::proven::sub::<i64>(width, k) }).min(62)) - 1;
                widest = Some(Range { lo: Some(0), hi: Some(most) });
            }
            if ty.starts_with('i') && width > 0 && k >= 1 && k < width {
                let by = unsafe { nikaia_std::proven::sub::<i64>(nikaia_std::proven::sub::<i64>(width, 1), k) };
                let half: i64 = 1 << by;
                let below = half - 1;
                widest = Some(Range { lo: Some(-half), hi: Some(below) });
            }
            let known = bounding_range(walk, lhs, facts, context, program, words, &mut &mut *ask);
            let x = match known { Some(__nikaia_value) => __nikaia_value, None => return widest };
            let lo = match x.lo { Some(__nikaia_value) => __nikaia_value, None => return widest };
            if lo < 0 { return widest; }
            let mut shifted = Range { lo: Some(unsafe { nikaia_std::proven::shr::<i64>(lo, (k) as u32) }), hi: nikaia_std::index::or(widest, || Range { lo: Some(0), hi: None }).hi };
            if x.hi.is_some() { shifted.hi = Some(unsafe { nikaia_std::proven::shr::<i64>(nikaia_std::index::or(x.hi, || 0), (k) as u32) }); }
            return Some(shifted);
        },
        BinaryOp::BitXor => {
            let a = match bounding_range(walk, lhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_range(walk, rhs, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let m = match bounding_sign_bits(&a) { Some(__nikaia_value) => __nikaia_value, None => return None }.max(match bounding_sign_bits(&b) { Some(__nikaia_value) => __nikaia_value, None => return None });
            let half = 1 << m;
            return Some(Range { lo: Some(-half), hi: Some(half - 1) });
        },
        BinaryOp::BitAnd => {
            let mut mask: Option<i64> = None;
            let first = bounding_mask(walk, lhs, facts, context, program, words);
            if first.is_some() { mask = std::convert::identity(first); }
            let second = bounding_mask(walk, rhs, facts, context, program, words);
            if second.is_some() { mask = std::convert::identity(second); }
            let most = match mask { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(Range { lo: Some(0), hi: Some(most) });
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_sign_bits(range: &Range) -> Option<i64> {
    let lo = match range.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
    let hi = match range.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
    for m in 0..63 {
        let half: i64 = 1 << m;
        if lo >= -half && hi < half { return Some(m); }
    }
    None
}

pub(crate) fn bounding_remainder(x: Option<&Range>, high: i64) -> Range {
    let either = Range { lo: Some(1 - high), hi: Some(high - 1) };
    let known = match x { Some(__nikaia_value) => __nikaia_value, None => return either };
    let lo = match known.lo { Some(__nikaia_value) => __nikaia_value, None => return either };
    if lo < 0 { return either; }
    let hi = match known.hi { Some(__nikaia_value) => __nikaia_value, None => return Range { lo: Some(0), hi: Some(high - 1) } };
    Range { lo: Some(0), hi: Some(hi.min(high - 1)) }
}

pub(crate) fn bounding_not_negative(walk: &mut BoundsWalk, side: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let term = match bounding_lin(walk, side, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let zero = walk.arena.int(0);
    let goal = walk.arena.ge(term, zero);
    bounding_proves(&walk, facts, goal, &mut *ask)
}

pub(crate) fn bounding_mask(walk: &mut BoundsWalk, side: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    let term = match bounding_lin(walk, side, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let c = match walk.arena.constant(term) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if c >= 0 { return Some(c); }
    None
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_fits(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, ty: &str, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let bounds = match Range::of_type(ty) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let widest_lo = match bounds.lo { Some(__nikaia_value) => __nikaia_value, None => return false };
    let widest_hi = match bounds.hi { Some(__nikaia_value) => __nikaia_value, None => return false };
    let lo = widest_lo.max(unsafe { nikaia_std::proven::sub::<i64>(0, solvable()) });
    let hi = widest_hi.min(solvable());
    let term = bounding_lin_of(walk, op, lhs, rhs, facts, context, program, words);
    let subtracting = matches!(op, BinaryOp::Sub);
    if term.is_some() {
        let t = nikaia_std::index::or(term, || 0);
        let low = walk.arena.int(lo);
        let high = walk.arena.int(hi);
        let above = walk.arena.ge(t, low);
        let below = walk.arena.le(t, high);
        let side = bounding_one_way(op, lhs, rhs);
        let mut goal = walk.arena.and(vec![above, below]);
        if side > 0 { goal = below; } else if side < 0 { goal = above; }
        if bounding_proves(&walk, facts, goal, &mut *ask) { return true; }
        let typed = bounding_typed_goal(walk, t, goal);
        if typed.is_some() && bounding_proves(&walk, facts, nikaia_std::index::or(typed, || 0), &mut *ask) { return true; }
        if subtracting && widest_lo <= 0 - widest_hi && bounding_not_negative(walk, lhs, facts, context, program, words, &mut *ask) && bounding_not_negative(walk, rhs, facts, context, program, words, &mut *ask) { return true; }
        let mut relatives: Vec<i64> = vec![];
        if side != 0 { relatives = bounding_relatives(walk, t, side, &bounds, facts); }
        for relative in relatives.iter() {
            let relative = nikaia_std::num::value(relative);
            if bounding_proves(&walk, facts, relative, &mut *ask) { return true; }
        }
        if !relatives.is_empty() {
            relatives.insert(0, goal);
            goal = walk.arena.or(relatives);
        }
        if !bounding_reads_own(&walk, t) {
            bounding_missed(walk, facts, goal);
            return false;
        }
    }
    let adds = matches!(op, BinaryOp::Add);
    let subtracts = matches!(op, BinaryOp::Sub);
    if (adds || subtracts) && bounding_mixed_fits(walk, lhs, rhs, subtracts, lo, hi, facts, context, program, words, &mut *ask) { return true; }
    if adds && bounding_mixed_fits(walk, rhs, lhs, false, lo, hi, facts, context, program, words, &mut *ask) { return true; }
    let range = match bounding_range_of(walk, op, lhs, rhs, -1, facts, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
    bounds.holds(&range)
}

pub(crate) fn most_relatives() -> i64 { 8 }

pub(crate) fn bounding_relatives(walk: &mut BoundsWalk, t: i64, side: i64, bounds: &Range, facts: &BoundsFacts) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    if walk.typed.is_empty() { return out; }
    let mut own: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(t, &mut own);
    let mut tried: collections::BTreeSet<String> = collections::BTreeSet::new();
    for near in [true, false] {
        let mut at = facts.facts.len() as i64;
        while at > 0 && (tried.len() as i64) < most_relatives() {
            at = unsafe { nikaia_std::proven::sub::<i64>(at, 1) };
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            walk.arena.variables(*unsafe { nikaia_std::proven::read(&facts.facts, (at) as usize) }, &mut read);
            let shares = read.iter().any(|name| { own.contains(nikaia_std::index::as_text(&name)) });
            if shares != near { continue; }
            for y in read.iter() {
                if own.contains(y) || tried.contains(y) || (tried.len() as i64) >= most_relatives() { continue; }
                let ty = match walk.typed.get(y) { Some(__nikaia_value) => __nikaia_value, None => continue };
                let held = match Range::held_by_type(&ty) { Some(__nikaia_value) => __nikaia_value, None => continue };
                if !bounds.holds(&held) { continue; }
                tried.insert(nikaia_std::block::Text::from(y.to_string()));
                let v = walk.arena.var(y);
                if side < 0 { out.push(walk.arena.ge(t, v)); } else { out.push(walk.arena.le(t, v)); }
            }
        }
    }
    out
}

pub(crate) fn bounding_typed_goal(walk: &mut BoundsWalk, t: i64, goal: i64) -> Option<i64> {
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(t, &mut read);
    let mut parts: Vec<i64> = vec![];
    for y in read.iter() {
        let ty = match walk.typed.get(y) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let held = match Range::held_by_type(&ty) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let lo = match held.lo { Some(__nikaia_value) => __nikaia_value, None => continue };
        let hi = match held.hi { Some(__nikaia_value) => __nikaia_value, None => continue };
        if lo < unsafe { nikaia_std::proven::sub::<i64>(0, solvable()) } || hi > solvable() { continue; }
        let v = walk.arena.var(y);
        let low = walk.arena.int(lo);
        let high = walk.arena.int(hi);
        parts.push(walk.arena.lt(v, low));
        parts.push(walk.arena.gt(v, high));
    }
    if parts.is_empty() { return None; }
    parts.push(goal);
    Some(walk.arena.or(parts))
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_mixed_fits(walk: &mut BoundsWalk, linear: &Expr, ranged: &Expr, subtracts: bool, lo: i64, hi: i64, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let l = match bounding_lin(walk, linear, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let r = match bounding_range(walk, ranged, facts, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let a = match r.lo { Some(__nikaia_value) => __nikaia_value, None => return false };
    let b = match r.hi { Some(__nikaia_value) => __nikaia_value, None => return false };
    let mut least = a;
    let mut most = b;
    if subtracts {
        least = match b.checked_neg() { Some(__nikaia_value) => __nikaia_value, None => return false };
        most = match a.checked_neg() { Some(__nikaia_value) => __nikaia_value, None => return false };
    }
    let least_term = walk.arena.int(least);
    let most_term = walk.arena.int(most);
    let low = walk.arena.add(l, least_term);
    let high = walk.arena.add(l, most_term);
    let floor = walk.arena.int(lo);
    let ceiling = walk.arena.int(hi);
    let above = walk.arena.ge(low, floor);
    let below = walk.arena.le(high, ceiling);
    let goal = walk.arena.and(vec![above, below]);
    bounding_proves_goal(walk, facts, goal, &mut *ask)
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_count_fits(walk: &mut BoundsWalk, count: &Expr, ty: &str, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let width = match bounding_bits(ty) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let term = bounding_lin(walk, count, facts, context, program, words);
    if term.is_some() {
        let k = nikaia_std::index::or(term, || 0);
        let zero = walk.arena.int(0);
        let most = walk.arena.int(width - 1);
        let above = walk.arena.ge(k, zero);
        let below = walk.arena.le(k, most);
        let goal = walk.arena.and(vec![above, below]);
        return bounding_proves_goal(walk, facts, goal, &mut *ask);
    }
    let range = match bounding_range(walk, count, facts, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let lo = match range.lo { Some(__nikaia_value) => __nikaia_value, None => return false };
    let hi = match range.hi { Some(__nikaia_value) => __nikaia_value, None => return false };
    lo >= 0 && hi < width
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_divides(walk: &mut BoundsWalk, lhs: &Expr, rhs: &Expr, ty: &str, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let typed = nikaia_std::index::or(Range::of_type(ty), || Range { lo: Some(-1), hi: None });
    let least = nikaia_std::index::or(typed.lo, || -1);
    let term = bounding_lin(walk, rhs, facts, context, program, words);
    if term.is_none() {
        let range = match bounding_range(walk, rhs, facts, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
        let under: i64 = if least < 0 { -1 } else { 0 };
        let above = range.lo.is_some() && nikaia_std::index::or(range.lo, || 0) > 0;
        let below = range.hi.is_some() && nikaia_std::index::or(range.hi, || 0) < under;
        return above || below;
    }
    let d = nikaia_std::index::or(term, || 0);
    let zero = walk.arena.int(0);
    let mut goal = walk.arena.unequal(d, zero);
    if least < 0 {
        let minus_one = walk.arena.int(-1);
        let mut apart = walk.arena.unequal(d, minus_one);
        let dividend = bounding_lin(walk, lhs, facts, context, program, words);
        if dividend.is_some() {
            let low = walk.arena.int(least.max(unsafe { nikaia_std::proven::sub::<i64>(0, solvable()) }));
            let higher = walk.arena.gt(nikaia_std::index::or(dividend, || 0), low);
            apart = { let __nikaia_value = walk.arena.or(vec![apart, higher]); __nikaia_value };
        }
        goal = { let __nikaia_value = walk.arena.and(vec![goal, apart]); __nikaia_value };
    }
    bounding_proves(&walk, facts, goal, &mut *ask)
}

pub(crate) fn bounding_literal(expr: &Expr) -> bool { matches!(expr, Expr::LitInt { .. }) }

pub(crate) fn bounding_bits(ty: &str) -> Option<i64> {
    match ty {
        "i8" => Some(8),
        "u8" => Some(8),
        "i16" => Some(16),
        "u16" => Some(16),
        "i32" => Some(32),
        "u32" => Some(32),
        "i64" => Some(64),
        "u64" => Some(64),
        "int" => Some(64),
        "isize" => Some(64),
        "usize" => Some(64),
        "i128" => Some(128),
        "u128" => Some(128),
        _ => None,
    }
}

pub(crate) fn bounding_one_way(op: &BinaryOp, lhs: &Expr, rhs: &Expr) -> i64 {
    match op {
        BinaryOp::Add => { if bounding_a_count(rhs) || bounding_a_count(lhs) { return 1; } },
        BinaryOp::Sub => { if bounding_a_count(rhs) { return -1; } },
        _ => { },
    }
    0
}

pub(crate) fn bounding_a_count(expr: &Expr) -> bool {
    match expr {
        Expr::LitInt { negative, .. } => { let negative = *negative; !negative },
        _ => false,
    }
}

pub(crate) fn bounding_bounded(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, range: &Range) {
    let n = walk.arena.var(name);
    if range.lo.is_some() && nikaia_std::index::or(range.lo, || 0) >= unsafe { nikaia_std::proven::sub::<i64>(0, solvable()) } {
        let lo = walk.arena.int(nikaia_std::index::or(range.lo, || 0));
        let fact = walk.arena.ge(n, lo);
        bounding_push(&walk, facts, fact);
    }
    if range.hi.is_some() && nikaia_std::index::or(range.hi, || 0) <= solvable() {
        let hi = walk.arena.int(nikaia_std::index::or(range.hi, || 0));
        let fact = walk.arena.le(n, hi);
        bounding_push(&walk, facts, fact);
    }
}

pub(crate) fn bounding_push(walk: &BoundsWalk, facts: &mut BoundsFacts, fact: i64) {
    match nikaia_std::index::get(&walk.arena.nodes, nikaia_std::index::at(fact)) {
        logic::SolverTerm::And(parts) => {
            for part in parts.iter() {
                let part = nikaia_std::num::value(part);
                bounding_push(walk, facts, part);
            }
            return;
        },
        _ => { },
    }
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(fact, &mut read);
    for name in read.iter() { if walk.pinned.contains(&path_root(name)) { return; } }
    #[allow(unused_mut)] let mut pending: Vec<String> = read.iter().cloned().collect::<Vec<_>>();
    let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut pending = pending;
    while !pending.is_empty() {
        let name = match pending.pop() { Some(__nikaia_value) => __nikaia_value, None => break };
        if !seen.insert(nikaia_std::block::Text::from(name.to_string())) { continue; }
        let defined = match walk.defining.get(&name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        for part in defined.iter() {
            let part = nikaia_std::num::value(part);
            if part != fact && !facts.facts.contains(&part) {
                bounding_hold(facts, part);
                let mut more: collections::BTreeSet<String> = collections::BTreeSet::new();
                walk.arena.variables(part, &mut more);
                pending.reserve(more.iter().size_hint().0); for other in more.iter() { pending.push(nikaia_std::block::Text::from(other.to_string())); }
            }
        }
    }
    bounding_hold(facts, fact);
}

pub(crate) fn bounding_hold(facts: &mut BoundsFacts, fact: i64) {
    facts.facts.push(fact);
    if (facts.facts.len() as i64) > most_held() {
        facts.facts.remove(0);
        facts.evicted += 1;
    }
}

pub(crate) fn bounding_settle(walk: &mut BoundsWalk, facts: &mut BoundsFacts) {
    let mut parts: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for (_, defined) in walk.defining.iter() {
        parts.reserve(defined.iter().size_hint().0); for part in defined.iter() {
            let part = nikaia_std::num::value(part);
            parts.push(part);
        }
    }
    walk.defining.clear();
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        if !facts.facts.contains(&part) { bounding_push(&walk, facts, part); }
    }
}

pub(crate) fn bounding_at_least_zero(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let n = walk.arena.var(name);
    let zero = walk.arena.int(0);
    let fact = walk.arena.ge(n, zero);
    bounding_push(&walk, facts, fact);
    let most = match walk.shape.narrow.get(name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return };
    let top = walk.arena.int(most);
    let below = walk.arena.le(n, top);
    bounding_push(&walk, facts, below);
}

pub(crate) fn bounding_forget(walk: &BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let mut kept: Vec<i64> = vec![];
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if !bounding_touches(walk, fact, name) { kept.push(fact); }
    }
    facts.facts = kept;
}

pub(crate) fn bounding_touches(walk: &BoundsWalk, term: i64, name: &str) -> bool {
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(term, &mut read);
    for v in read.iter() { if path_within(v, name) || bounding_in_elements(v, name) { return true; } }
    false
}

pub(crate) fn bounding_in_elements(path: &str, name: &str) -> bool { ::core::convert::identity(match (AsRef::<str>::as_ref(&(path)), AsRef::<str>::as_ref(&(name)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix("[")).is_some() }) || ::core::convert::identity(match (AsRef::<str>::as_ref(&(path)), AsRef::<str>::as_ref(&(name)), ) { (__nikaia_t, __nikaia_f1, ) => { let mut __nikaia_rest: &str = __nikaia_t; loop { match __nikaia_rest.find("[") { Some(__nikaia_i) => { if __nikaia_rest[__nikaia_i + "[".len()..].strip_prefix(__nikaia_f1).and_then(|__nikaia_r| __nikaia_r.strip_prefix("]")).is_some() { break true; } match __nikaia_rest[__nikaia_i..].chars().next() { Some(__nikaia_c) => __nikaia_rest = &__nikaia_rest[__nikaia_i + __nikaia_c.len_utf8()..], None => break false, } }, None => break false, } } } }) }

pub(crate) fn bounding_forget_parts(walk: &BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let length = length_of(name);
    let under = format!("{}.", name);
    let mut kept: Vec<i64> = vec![];
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let mut touched = false;
        for n in walk.arena.variable_ids(fact) {
            let n = nikaia_std::num::value(n);
            let v = walk.arena.variable_name(n);
            if (v.starts_with(&*under) || ::core::convert::identity(match (AsRef::<str>::as_ref(&(v)), AsRef::<str>::as_ref(&(name)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix("[")).is_some() })) && v != length && !v.contains('@') { touched = true; }
        }
        if !touched { kept.push(fact); }
    }
    facts.facts = kept;
}

pub(crate) fn bounding_forget_length(walk: &BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let length = length_of(name);
    let mut kept: Vec<i64> = vec![];
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if !walk.arena.mentions(fact, &length) { kept.push(fact); }
    }
    facts.facts = kept;
}

pub(crate) fn bounding_place_path(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(name, _) => { let name = *name; Some(nikaia_std::block::Text::from(words.resolve(name).to_string())) },
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            let inner = match bounding_place_path(base, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(format!("{}.{}", inner, words.resolve(name)))
        },
        Expr::Index { .. } => element_name(expr, words),
        _ => None,
    }
}

pub(crate) fn bounding_element_written(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<(String, String, String)> {
    match expr {
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            let (list, at, rest) = match bounding_element_written(base, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if at.is_empty() && rest.is_empty() { return Some((list, at, rest)); }
            return Some((list, at, format!("{}.{}", rest, words.resolve(name))));
        },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let list = path_of(base, words);
            if list.is_none() {
                match base {
                    Expr::Index { base: outer, .. } => {
                        let outer = nikaia_std::boxed::open(outer);
                        let of = path_of(outer, words);
                        if of.is_some() { return Some((nikaia_std::block::Text::from(nikaia_std::index::or(of.as_deref(), || "").to_string()), String::from(""), String::from(""))); }
                    },
                    _ => { },
                }
                let root = match bounding_root_of(base, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return Some((root, String::from(""), String::from("")));
            }
            let at = nikaia_std::index::or(element_index(index, words), || "".into());
            return Some((nikaia_std::block::Text::from(nikaia_std::index::or(list.as_deref(), || "").to_string()), nikaia_std::block::Text::from(at.to_string()), String::from("")));
        },
        _ => return None,
    }
}

pub(crate) fn bounding_root_of(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(name, _) => { let name = *name; Some(nikaia_std::block::Text::from(words.resolve(name).to_string())) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_root_of(base, words) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_root_of(base, words) },
        _ => None,
    }
}

pub(crate) fn bounding_forget_aliases(walk: &BoundsWalk, facts: &mut BoundsFacts, target: &Expr, words: &winnow_grammar::InternerContext) {
    let (list, at, rest) = match bounding_element_written(target, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_forget_element(walk, facts, &format!("{}|{}|{}", list, at, rest), true);
}

pub(crate) fn bounding_element_changed(target: &Expr, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    let (list, at, rest) = match bounding_element_written(target, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    out.elements.insert(format!("{}|{}|{}", list, at, rest));
}

pub(crate) fn bounding_forget_element(walk: &BoundsWalk, facts: &mut BoundsFacts, place: &str, keep_own: bool) {
    let mut kept: Vec<i64> = vec![];
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(fact, &mut read);
        let mut touched = false;
        for v in read.iter() { if bounding_element_hit(v, place, keep_own) { touched = true; } }
        if !touched { kept.push(fact); }
    }
    facts.facts = kept;
}

pub(crate) fn bounding_element_hit(v: &str, place: &str, keep_own: bool) -> bool {
    let parts: Vec<&str> = place.split('|').collect::<Vec<_>>();
    let list = *unsafe { nikaia_std::proven::read(&parts, (0) as usize) };
    let at = *nikaia_std::index::get(&parts, 1);
    let rest = *nikaia_std::index::get(&parts, 2); ::core::mem::drop(parts);
    if keep_own && ::core::convert::identity(match (AsRef::<str>::as_ref(&(v)), AsRef::<str>::as_ref(&(list)), AsRef::<str>::as_ref(&(at)), AsRef::<str>::as_ref(&(rest)), ) { (__nikaia_t, __nikaia_f0, __nikaia_f2, __nikaia_f4, ) => __nikaia_t.len() == __nikaia_f0.len() + "[".len() + __nikaia_f2.len() + "]".len() + __nikaia_f4.len() && __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix("[")).and_then(|__nikaia_r| __nikaia_r.strip_prefix(__nikaia_f2)).and_then(|__nikaia_r| __nikaia_r.strip_prefix("]")).and_then(|__nikaia_r| __nikaia_r.strip_prefix(__nikaia_f4)).is_some() }) { return false; }
    if at == "*" { return ::core::convert::identity(match (AsRef::<str>::as_ref(&(v)), AsRef::<str>::as_ref(&(list)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix("[")).is_some() }); }
    if v == bounding_element_of(list) || ::core::convert::identity(match (AsRef::<str>::as_ref(&(v)), AsRef::<str>::as_ref(&(bounding_element_of(list))), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix(".")).is_some() }) { return true; }
    if ::core::convert::identity(match (AsRef::<str>::as_ref(&(v)), AsRef::<str>::as_ref(&(list)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix("[")).is_some() }) {
        let after: String = nikaia_std::block::Text::from(nikaia_std::index::or(v.split(']').last(), || "").to_string());
        return at.is_empty() || rest.is_empty() || after.is_empty() || after == rest || ::core::convert::identity(match (AsRef::<str>::as_ref(&(after)), AsRef::<str>::as_ref(&(rest)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix(".")).is_some() }) || ::core::convert::identity(match (AsRef::<str>::as_ref(&(rest)), AsRef::<str>::as_ref(&(after)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix(".")).is_some() });
    }
    at.is_empty() && ::core::convert::identity(match (AsRef::<str>::as_ref(&(v)), AsRef::<str>::as_ref(&(list)), ) { (__nikaia_t, __nikaia_f0, ) => __nikaia_t.strip_prefix(__nikaia_f0).and_then(|__nikaia_r| __nikaia_r.strip_prefix(".")).is_some() }) && v.contains('[')
}

pub(crate) fn bounding_forget_elements_at(walk: &BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let mut kept: Vec<i64> = vec![];
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(fact, &mut read);
        let mut touched = false;
        for v in read.iter() { if ::core::convert::identity(match (AsRef::<str>::as_ref(&(v)), AsRef::<str>::as_ref(&(name)), ) { (__nikaia_t, __nikaia_f1, ) => { let mut __nikaia_rest: &str = __nikaia_t; loop { match __nikaia_rest.find("[") { Some(__nikaia_i) => { if __nikaia_rest[__nikaia_i + "[".len()..].strip_prefix(__nikaia_f1).and_then(|__nikaia_r| __nikaia_r.strip_prefix("]")).is_some() { break true; } match __nikaia_rest[__nikaia_i..].chars().next() { Some(__nikaia_c) => __nikaia_rest = &__nikaia_rest[__nikaia_i + __nikaia_c.len_utf8()..], None => break false, } }, None => break false, } } } }) { touched = true; } }
        if !touched { kept.push(fact); }
    }
    facts.facts = kept;
}

pub(crate) fn bounding_shift(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, by: i64) {
    let now = walk.arena.var(name);
    let old = walk.arena.sub(now, by);
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    given.insert(nikaia_std::block::Text::from(name.to_string()), old);
    for fact in facts.facts.iter_mut() { if walk.arena.mentions(*fact, name) { *fact = walk.arena.substitute(*fact, &given); } }
}

pub(crate) fn bounding_after_change(walk: &mut BoundsWalk, facts: &mut BoundsFacts, changed: &BoundsChanged) {
    for name in changed.values.iter() {
        bounding_forget(&walk, facts, name);
        if (walk.nonnegative.contains(name) || walk.shape.unsigned.contains(name)) && facts.ints.contains(name) { bounding_at_least_zero(walk, facts, name); }
    }
    for name in changed.lengths.iter() {
        let grown = rules_capped_grown(walk, &facts, name, changed);
        bounding_forget_length(&walk, facts, name);
        for fact in grown.iter() {
            let fact = nikaia_std::num::value(fact);
            bounding_push(&walk, facts, fact);
        }
    }
    for name in changed.parts.iter() { bounding_forget_parts(&walk, facts, name); }
    for place in changed.elements.iter() { bounding_forget_element(&walk, facts, place, false); }
}

pub(crate) fn bounding_halves(walk: &mut BoundsWalk, names: &[winnow_grammar::Symbol], value: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match bounding_unwrapped(value) {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let picked = words.resolve(method);
            if picked == "narrowing_div_rem" && args.len() == 2 { return bounding_division_halves(walk, names, bounding_unwrapped(value), receiver, args, facts, context, program, words); }
            if args.len() != 1 { return None; }
            let ty = match *nikaia_std::index::get(&context.std_receivers, &(node_key(value))) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if !is_whole_number(ty) { return None; }
            let a = match bounding_lin(walk, receiver, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let first = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&names, (0) as usize) }).to_string());
            let second = nikaia_std::block::Text::from(words.resolve(*nikaia_std::index::get(&names, 1)).to_string());
            for side in [a, b] { if walk.arena.mentions(side, &first) || walk.arena.mentions(side, &second) { return None; } }
            let product = picked == "overflowing_mul" || picked == "widening_mul";
            if product && walk.arena.constant(a).is_none() && walk.arena.constant(b).is_none() { return None; }
            let exact = match picked {
                "overflowing_add" => walk.arena.add(a, b),
                "overflowing_sub" => walk.arena.sub(a, b),
                "overflowing_mul" => walk.arena.mul(a, b),
                "widening_mul" => walk.arena.mul(a, b),
                _ => return None,
            };
            let result = walk.arena.var(&first);
            let same = walk.arena.equal(result, exact);
            let other = walk.arena.var(&second);
            if picked == "widening_mul" {
                let top = match match Range::of_type(ty) { Some(__nikaia_value) => __nikaia_value, None => return None }.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
                let zero = walk.arena.int(0);
                let high = walk.arena.unequal(other, zero);
                let most = walk.arena.int(top);
                let past = walk.arena.gt(result, most);
                return Some(walk.arena.or(vec![high, past, same]));
            }
            let one = walk.arena.int(1);
            let up = walk.arena.ge(other, one);
            return Some(walk.arena.or(vec![up, same]));
        },
        _ => { },
    }
    None
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_division_halves(walk: &mut BoundsWalk, names: &[winnow_grammar::Symbol], call: &Expr, receiver: &Expr, args: &[Expr], facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    let ty = nikaia_std::index::or(*nikaia_std::index::get(&context.std_receivers, &(node_key(call))), || "");
    if !is_whole_number(ty) { return None; }
    let high = match bounding_lin(walk, receiver, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let low = match bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let by = match bounding_lin(walk, nikaia_std::index::get(&args, 1), facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let first = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&names, (0) as usize) }).to_string());
    let second = nikaia_std::block::Text::from(words.resolve(*nikaia_std::index::get(&names, 1)).to_string());
    for side in [high, low, by] { if walk.arena.mentions(side, &first) || walk.arena.mentions(side, &second) { return None; } }
    let quotient = walk.arena.var(&first);
    let rest = walk.arena.var(&second);
    let zero = walk.arena.int(0);
    let below = walk.arena.neg(by);
    let not_up = walk.arena.le(by, zero);
    let over = walk.arena.lt(below, rest);
    let under = walk.arena.lt(rest, by);
    let inside = walk.arena.and(vec![over, under]);
    let up_side = walk.arena.or(vec![not_up, inside]);
    let not_down = walk.arena.ge(by, zero);
    let over_down = walk.arena.lt(by, rest);
    let under_down = walk.arena.lt(rest, below);
    let inside_down = walk.arena.and(vec![over_down, under_down]);
    let down_side = walk.arena.or(vec![not_down, inside_down]);
    let mut parts = vec![up_side, down_side];
    let bits = match ty {
        "u8" => 8,
        "u32" => 32,
        "i32" => 32,
        _ => 0,
    };
    if bits != 0 && walk.arena.constant(by).is_some() {
        let shift = walk.arena.int(1 << bits);
        let top = walk.arena.mul(high, shift);
        let whole = walk.arena.add(top, low);
        let times = walk.arena.mul(by, quotient);
        let back = walk.arena.add(times, rest);
        parts.push(walk.arena.equal(back, whole));
    }
    Some(walk.arena.and(parts))
}

pub(crate) fn bounding_wide(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<i64> {
    match expr {
        Expr::Coalesce { value: inner, fallback, .. } => {
            let inner = nikaia_std::boxed::open(inner); let fallback = nikaia_std::boxed::open(fallback);
            if bounding_leaves(fallback) { return bounding_wide_some(walk, inner, facts, context, program, words, &mut &mut *ask); }
        },
        Expr::Variable(name, _) => {
            let name = *name;
            let text = words.resolve(name);
            if facts.ints.contains(text) { return Some(walk.arena.var(text)); }
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let recorded = match *nikaia_std::index::get(&context.wide_calls, &(node_key(func))) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if recorded.starts_with("of ") && args.len() == 1 { return bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words); }
            if recorded.starts_with("product ") && args.len() == 2 {
                let a = bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words);
                let b = bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (1) as usize) }, facts, context, program, words);
                if a.is_some() && b.is_some() {
                    let exact = bounding_product(walk, nikaia_std::index::or(a, || 0), nikaia_std::index::or(b, || 0));
                    if exact.is_some() { return std::convert::identity(exact); }
                }
                let left = match bounding_range(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let right = match bounding_range(walk, unsafe { nikaia_std::proven::read(&args, (1) as usize) }, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let both = left.mul(&right);
                let lo = match both.lo { Some(__nikaia_value) => __nikaia_value, None => return None };
                let hi = match both.hi { Some(__nikaia_value) => __nikaia_value, None => return None };
                if lo < unsafe { nikaia_std::proven::sub::<i64>(0, solvable()) } || hi > solvable() { return None; }
                let name = format!("product#{}", walk.codes);
                walk.codes += 1;
                let v = walk.arena.var(&name);
                let least = walk.arena.int(lo);
                let most = walk.arena.int(hi);
                let low = walk.arena.ge(v, least);
                let high = walk.arena.le(v, most);
                walk.axioms.insert(name, vec![low, high]);
                return Some(v);
            }
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_wide_some(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<i64> {
    match expr {
        Expr::MethodCall { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            let recorded = match *nikaia_std::index::get(&context.wide_calls, &(node_key(expr))) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let (entry, _) = match recorded.split_once(" ") { Some(__nikaia_value) => __nikaia_value, None => return None };
            let on = match bounding_wide(walk, receiver, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if AsRef::<str>::as_ref(&(entry)) == AsRef::<str>::as_ref(&("neg")) && args.is_empty() { return Some(walk.arena.neg(on)); }
            if args.len() != 1 { return None; }
            if AsRef::<str>::as_ref(&(entry)) == AsRef::<str>::as_ref(&("mul")) {
                let k = match bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return bounding_product(walk, on, k);
            }
            let other = match bounding_wide(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words, &mut &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return match entry {
                "add" => Some(walk.arena.add(on, other)),
                "sub" => Some(walk.arena.sub(on, other)),
                _ => None,
            };
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_narrowed(walk: &mut BoundsWalk, value: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<i64> {
    match value {
        Expr::Coalesce { value: inner, fallback, .. } => {
            let inner = nikaia_std::boxed::open(inner); let fallback = nikaia_std::boxed::open(fallback);
            if !bounding_leaves(fallback) { return None; }
            match inner {
                Expr::MethodCall { receiver, args, .. } => {
                    let receiver = nikaia_std::boxed::open(receiver);
                    let recorded = match *nikaia_std::index::get(&context.wide_calls, &(node_key(inner))) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    if recorded.starts_with("narrow ") && args.is_empty() { return bounding_wide(walk, receiver, facts, context, program, words, &mut *ask); }
                },
                _ => { },
            }
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_lin(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    if !walk.call_names.is_empty() {
        let named = match walk.call_names.get(&node_key(expr)) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        if named.is_some() { return Some(walk.arena.var(nikaia_std::index::or(named.as_deref(), || ""))); }
    }
    match expr {
        Expr::LitInt { value, negative, .. } => {
            let negative = *negative; let value = *value;
            let n = match integer_as_count(&integer(value, negative)) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(walk.arena.int(n));
        },
        Expr::Variable(name, _) => {
            let name = *name;
            let text = words.resolve(name);
            if walk.shape.constants.contains_key(text) {
                let n = nikaia_std::index::or(*nikaia_std::index::get(&walk.shape.constants, text), || 0);
                return Some(walk.arena.int(n));
            }
            if facts.ints.contains(text) { return Some(walk.arena.var(text)); }
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if args.is_empty() && words.resolve(method) == "len" {
                let path = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let counted = bounding_length(walk, receiver, &path, context);
                if counted.is_some() { return std::convert::identity(counted); }
            }
            let picked = words.resolve(method);
            if args.len() == 1 && (picked == "min" || picked == "max") {
                let whole = match *nikaia_std::index::get(&context.std_receivers, &(node_key(expr))) { Some(__nikaia_value) => __nikaia_value, None => return None };
                if !is_whole_number(whole) { return None; }
                let a = match bounding_lin(walk, receiver, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let b = match bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let name = format!("result#{}", walk.codes);
                walk.codes += 1;
                let result = walk.arena.var(&name);
                let mut held: Vec<i64> = vec![];
                if picked == "min" {
                    held.push(walk.arena.le(result, a));
                    held.push(walk.arena.le(result, b));
                } else {
                    held.push(walk.arena.ge(result, a));
                    held.push(walk.arena.ge(result, b));
                }
                let is_a = walk.arena.equal(result, a);
                let is_b = walk.arena.equal(result, b);
                held.push(walk.arena.or(vec![is_a, is_b]));
                walk.axioms.insert(name, held);
                return Some(result);
            }
            if bounding_on_self(receiver, words) {
                let called = words.resolve(method);
                let asked = format!("{}::{}", context.owner, called);
                let found = !context.owner.is_empty() && context.ensured.contains_key(&asked);
                walk.self_read.insert(nikaia_std::block::Text::from(called.to_string()), if found { nikaia_std::block::Text::from(asked.to_string()) } else { String::from("") });
                if found {
                    let summed = *nikaia_std::index::get(&context.ensured, &asked);
                    if summed.is_some() { return bounding_ensured(walk, match summed { Some(__nikaia_value) => __nikaia_value, None => return None }, args, facts, context, program, words); }
                }
            }
            let ty = match *nikaia_std::index::get(&context.std_receivers, &(node_key(expr))) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let ensured = match *nikaia_std::index::get(&context.ensured, &(format!("{}::{}", ty, words.resolve(method)))) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return bounding_ensured(walk, ensured, args, facts, context, program, words);
        },
        Expr::Field { .. } => {
            if context.whole_fields.contains(&node_key(expr)) {
                let path = match bounding_place_path(expr, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let ty = *nikaia_std::index::get(&context.whole_types, &(node_key(expr)));
                if ty.is_some() && !walk.shape.twice.contains(&path) { walk.typed.insert(nikaia_std::block::Text::from(path.to_string()), nikaia_std::block::Text::from(nikaia_std::index::or(ty, || "").to_string())); }
                return Some(walk.arena.var(&path));
            }
        },
        Expr::Index { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            if context.whole_fields.contains(&node_key(expr)) {
                let path = match bounding_place_path(expr, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return Some(bounding_element_var(walk, &path, base, words));
            }
        },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Neg => {
                    let a = match bounding_lin(walk, expr, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.neg(a));
                },
                _ => { },
            }
        },
        Expr::Cast { expr, ty, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if ty.generics.is_empty() && is_whole_number(words.resolve(ty.name)) {
                if context.char_codes.contains(&node_key(expr)) { return Some(bounding_code_of(walk, expr, context, words)); }
                return bounding_lin(walk, expr, facts, context, program, words);
            }
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            if config.is_empty() {
                let callee = match bounding_callee(func, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let mut given: Vec<i64> = vec![];
                let mut every = true;
                for arg in args.iter() {
                    let term = bounding_lin(walk, arg, facts, context, program, words);
                    if term.is_none() { every = false; } else { given.push(nikaia_std::index::or(term, || 0)); }
                }
                if every {
                    let inlined = bounding_called(walk, &callee, &given, 0, program, words);
                    if inlined.is_some() { return std::convert::identity(inlined); }
                }
                let ensured = match *nikaia_std::index::get(&context.ensured, &callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return bounding_ensured(walk, ensured, args, facts, context, program, words);
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); return bounding_lin_of(walk, op, lhs, rhs, facts, context, program, words); },
        Expr::Block(block, _) => {
            let last = unsafe { nikaia_std::proven::sub::<i64>(block.stmts.len() as i64, 1) };
            if last < 0 { return None; }
            for k in 0..last { if !bounding_an_assert(&unsafe { nikaia_std::proven::read(&block.stmts, (k) as usize) }.node, words) { return None; } }
            return match &unsafe { nikaia_std::proven::read(&block.stmts, (last) as usize) }.node {
                Stmt::Expr(inner) => bounding_lin(walk, inner, facts, context, program, words),
                _ => None,
            };
        },
        Expr::AsyncGroup(block, _, _, _, _) => {
            let last = unsafe { nikaia_std::proven::sub::<i64>(block.stmts.len() as i64, 1) };
            if last < 0 { return None; }
            for k in 0..last { if !bounding_an_assert(&unsafe { nikaia_std::proven::read(&block.stmts, (k) as usize) }.node, words) { return None; } }
            return match &unsafe { nikaia_std::proven::read(&block.stmts, (last) as usize) }.node {
                Stmt::Expr(inner) => bounding_lin(walk, inner, facts, context, program, words),
                _ => None,
            };
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_an_assert(stmt: &Stmt, words: &winnow_grammar::InternerContext) -> bool {
    match stmt {
        Stmt::Expr(inner) => match inner {
            Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); args.len() == 1 && nikaia_std::index::or(bounding_variable(func, words), || "".into()) == "assert" },
            _ => false,
        },
        _ => false,
    }
}

pub(crate) fn bounding_code(walk: &mut BoundsWalk) -> i64 {
    let name = format!("code#{}", walk.codes);
    walk.codes += 1;
    let v = walk.arena.var(&name);
    let zero = walk.arena.int(0);
    let most = walk.arena.int(1114111);
    let low = walk.arena.ge(v, zero);
    let high = walk.arena.le(v, most);
    walk.axioms.insert(name, vec![low, high]);
    v
}

pub(crate) fn bounding_code_of(walk: &mut BoundsWalk, expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> i64 {
    let v = bounding_code(walk);
    let name = match bounding_variable(expr, words) { Some(__nikaia_value) => __nikaia_value, None => return v };
    let class = match bounding_class_of(&walk, &name, context) { Some(__nikaia_value) => __nikaia_value, None => return v };
    let key = format!("code#{}", walk.codes - 1);
    let mut held: Vec<i64> = vec![];
    if class.lo.is_some() {
        let lo = walk.arena.int(nikaia_std::index::or(class.lo, || 0));
        held.push(walk.arena.ge(v, lo));
    }
    if class.hi.is_some() {
        let hi = walk.arena.int(nikaia_std::index::or(class.hi, || 0));
        held.push(walk.arena.le(v, hi));
    }
    walk.axioms.insert(key, held);
    v
}

pub(crate) fn bounding_negation(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if walk.collecting || context.negations.is_empty() { return; }
    let node = node_key(expr);
    let ty = match *nikaia_std::index::get(&context.negations, &node) { Some(__nikaia_value) => __nikaia_value, None => return };
    let operand = match expr {
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); match op {
            UnaryOp::Neg => expr,
            _ => return,
        } },
        _ => return,
    };
    let least = match Range::of_type(ty) { Some(__nikaia_value) => __nikaia_value, None => return };
    let lo = match least.lo { Some(__nikaia_value) => __nikaia_value, None => return };
    let above = (lo + 1).max(unsafe { nikaia_std::proven::sub::<i64>(0, solvable()) });
    let term = match bounding_lin(walk, operand, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    let k = walk.arena.int(above);
    let goal = walk.arena.ge(term, k);
    if bounding_proves_goal(walk, facts, goal, &mut *ask) { walk.proven.negations.insert(node); } else { walk.open += 1; }
}

pub(crate) fn bounding_class_of(walk: &BoundsWalk, name: &str, context: &BoundsContext) -> Option<Range> {
    if walk.loop_classes.contains_key(name) && !walk.shape.twice.contains(name) { return (*nikaia_std::index::get(&walk.loop_classes, name)).copied(); }
    if walk.shape.bound.contains(name) { return None; }
    (*nikaia_std::index::get(&context.classes, name)).copied()
}

pub(crate) fn bounding_chars_of(iter: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Option<String> {
    match iter {
        Expr::Field { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            if !context.text_scalars.contains(&node_key(iter)) { return None; }
            bounding_variable(base, words)
        },
        _ => None,
    }
}

pub(crate) fn bounding_callee(func: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name, _) => { let name = *name; Some(nikaia_std::block::Text::from(words.resolve(name).to_string())) },
        Expr::Path(parts, _) => {
            let mut out: String = String::from("");
            for part in parts.iter() {
                let part = *part;
                if !out.is_empty() { out.push_str("::"); }
                out.push_str(words.resolve(part));
            }
            Some(out)
        },
        _ => None,
    }
}

pub(crate) fn bounding_ensured(walk: &mut BoundsWalk, ensured: &Ensured, args: &[Expr], facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    if (args.len() as i64) != ensured.params.len() as i64 || ensured.conditions.is_empty() { return None; }
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for k in 0..args.len() as i64 {
        if *nikaia_std::index::get(&ensured.chars, (k) as usize) { given.insert(nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&ensured.params, (k) as usize) }).to_string()), bounding_code_of(walk, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, context, words)); } else {
            let term = nikaia_std::index::or(bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, facts, context, program, words), || bounding_fresh(walk).into());
            given.insert(nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&ensured.params, (k) as usize) }).to_string()), term);
        }
    }
    let name = format!("result#{}", walk.codes);
    walk.codes += 1;
    let result = walk.arena.var(&name);
    given.insert(String::from("result"), result);
    let mut read: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    read.reserve(ensured.conditions.iter().size_hint().0); for nodes in ensured.conditions.iter() {
        let condition = walk.arena.adopt(nodes);
        walk.arena.variables(condition, &mut names);
        read.push(condition);
    }
    for name in names.iter() {
        if given.contains_key(name) { continue; }
        let mut length: Option<i64> = None;
        for k in 0..args.len() as i64 {
            if length_of(unsafe { nikaia_std::proven::read(&ensured.params, (k) as usize) }) == *name {
                let path = path_of(unsafe { nikaia_std::proven::read(&args, (k) as usize) }, words);
                if path.is_some() && !walk.pinned.contains(&path_root(nikaia_std::index::or(path.as_deref(), || ""))) { length = Some(bounding_length_named(walk, nikaia_std::index::or(path.as_deref(), || ""), true)); }
            }
        }
        given.insert(nikaia_std::block::Text::from(name.to_string()), nikaia_std::index::or(length, || bounding_fresh(walk).into()));
    }
    let mut holds: Vec<i64> = vec![];
    holds.reserve(read.iter().size_hint().0); for condition in read.iter() {
        let condition = nikaia_std::num::value(condition);
        holds.push(walk.arena.substitute(condition, &given));
    }
    walk.axioms.insert(name, holds);
    Some(result)
}

pub(crate) fn bounding_on_self(receiver: &Expr, words: &winnow_grammar::InternerContext) -> bool { nikaia_std::index::or(path_of(receiver, words), || "".into()) == "self" }

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_required(walk: &mut BoundsWalk, expr: &Expr, receiver: &Expr, method: &str, args: &[Expr], facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if walk.collecting { return; }
    let ty = match *nikaia_std::index::get(&context.std_receivers, &(node_key(expr))) { Some(__nikaia_value) => __nikaia_value, None => return };
    let key = format!("{}::{}", ty, method);
    let required = match *nikaia_std::index::get(&context.required, &key) { Some(__nikaia_value) => __nikaia_value, None => return };
    if (args.len() as i64) != required.params.len() as i64 || required.conditions.is_empty() { return; }
    let on = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    if walk.pinned.contains(&path_root(&on)) { return; }
    let mut conditions: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    conditions.reserve(required.conditions.iter().size_hint().0); for nodes in required.conditions.iter() {
        let condition = walk.arena.adopt(nodes);
        walk.arena.variables(condition, &mut read);
        conditions.push(condition);
    }
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for k in 0..args.len() as i64 {
        let param = nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&required.params, (k) as usize) }).to_string());
        if *nikaia_std::index::get(&required.chars, (k) as usize) && read.contains(&param) { return; }
        let term = bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, facts, context, program, words);
        let path = path_of(unsafe { nikaia_std::proven::read(&args, (k) as usize) }, words);
        if term.is_none() && path.is_none() { return; }
        given.insert(nikaia_std::block::Text::from(param.to_string()), nikaia_std::index::or(term, || bounding_fresh(walk).into()));
        let length = length_of(&param);
        if read.contains(&length) {
            if path.is_none() || walk.pinned.contains(&path_root(nikaia_std::index::or(path.as_deref(), || ""))) { return; }
            given.insert(length, bounding_length_named(walk, nikaia_std::index::or(path.as_deref(), || ""), true));
        }
    }
    let mut goals: Vec<i64> = vec![];
    goals.reserve(conditions.iter().size_hint().0); for condition in conditions.iter() {
        let condition = nikaia_std::num::value(condition);
        goals.push(walk.arena.substitute(condition, &given));
    }
    let goal = walk.arena.and(goals);
    if bounding_proves_goal(walk, facts, goal, &mut *ask) { walk.proven.calls.insert(node_key(receiver), key); } else { walk.open += 1; }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_derived_call(walk: &mut BoundsWalk, expr: &Expr, name: &str, on: Option<&str>, args: &[Expr], facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if walk.collecting { return; }
    let callee = match *nikaia_std::index::get(&context.around.derived.functions, name) { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut proved: collections::BTreeSet<i64> = collections::BTreeSet::new();
    if (args.len() as i64) == callee.params.len() as i64 {
        for k in 0..callee.claims.len() as i64 {
            let claim = (*unsafe { nikaia_std::proven::read(&callee.claims, (k) as usize) }).clone();
            let mut given: Vec<i64> = vec![];
            let mut left_reads: collections::BTreeSet<String> = collections::BTreeSet::new();
            let mut right_reads: collections::BTreeSet<String> = collections::BTreeSet::new();
            let left = match bounding_derived_side(walk, &callee.params, &claim.left, false, claim.each, args, on, facts, &mut given, &mut left_reads, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
            let right = if claim.fixed.is_some() { walk.arena.int(nikaia_std::index::or(claim.fixed, || 0)) } else { match bounding_derived_side(walk, &callee.params, &claim.right, claim.length, claim.each, args, on, facts, &mut given, &mut right_reads, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue } };
            let right = if claim.length { bounding_scaled(walk, &claim, right) } else { right };
            if left_reads.iter().any(|name| { right_reads.contains(nikaia_std::index::as_text(&name)) }) { continue; }
            let side = if claim.apart { walk.arena.unequal(left, right) } else if claim.strict { walk.arena.lt(left, right) } else { walk.arena.le(left, right) };
            let goal = bounding_each_guarded(walk, side);
            if given.is_empty() { if bounding_proves(&walk, facts, goal, &mut *ask) { proved.insert(k); } } else {
                let mut known = facts.clone();
                for fact in given.iter() {
                    let fact = nikaia_std::num::value(fact);
                    bounding_push(&walk, &mut known, fact);
                }
                if bounding_proves(&walk, &known, goal, &mut *ask) { proved.insert(k); }
            }
        }
    }
    let node = node_key(expr);
    if walk.proven.derived.contains_key(&node) {
        let was = nikaia_std::index::or(match walk.proven.derived.get(&node) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || collections::BTreeSet::new().into());
        let mut kept: collections::BTreeSet<i64> = collections::BTreeSet::new();
        for claim in was.iter() {
            let claim = nikaia_std::num::value(claim);
            if proved.contains(&claim) { kept.insert(claim); }
        }
        walk.proven.derived.insert(node, kept);
    } else { walk.proven.derived.insert(node, proved); }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_derived_side(walk: &mut BoundsWalk, params: &[String], param: &str, length: bool, each: bool, args: &[Expr], on: Option<&str>, facts: &BoundsFacts, given: &mut Vec<i64>, reads: &mut collections::BTreeSet<String>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    if param == "" { return Some(walk.arena.int(0)); }
    if each && !length { return bounding_derived_each(walk, params, param, args, given, words); }
    let field = param.strip_prefix("self.");
    if field.is_some() {
        if !length { return None; }
        let path = format!("{}.{}", match on { Some(__nikaia_value) => __nikaia_value, None => return None }, nikaia_std::index::or(field, || ""));
        if walk.pinned.contains(&path_root(&path)) { return None; }
        return Some(bounding_length_named(walk, &path, true));
    }
    let root = path_root(param);
    if root != param {
        for k in 0..params.len() as i64 {
            if *unsafe { nikaia_std::proven::read(&params, (k) as usize) } != root { continue; }
            let handed = match path_of(nikaia_std::index::get(&args, (k) as usize), words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if walk.pinned.contains(&path_root(&handed)) { return None; }
            let path = format!("{}{}", handed, nikaia_std::index::or(param.strip_prefix(&*root), || ""));
            if length { return Some(bounding_length_named(walk, &path, true)); }
            return Some(walk.arena.var(&path));
        }
        return None;
    }
    for k in 0..params.len() as i64 {
        if *unsafe { nikaia_std::proven::read(&params, (k) as usize) } != param { continue; }
        if !length {
            let element = rules_element_read(walk, nikaia_std::index::get(&args, (k) as usize), facts, words);
            if element.is_some() {
                walk.arena.variables(nikaia_std::index::or(element, || 0), reads);
                return std::convert::identity(element);
            }
            return bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, facts, context, program, words);
        }
        let path = match path_of(nikaia_std::index::get(&args, (k) as usize), words) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if walk.pinned.contains(&path_root(&path)) { return None; }
        return Some(bounding_length_named(walk, &path, true));
    }
    None
}

pub(crate) fn bounding_derived_each(walk: &mut BoundsWalk, params: &[String], param: &str, args: &[Expr], given: &mut Vec<i64>, words: &winnow_grammar::InternerContext) -> Option<i64> {
    let root = path_root(param);
    for k in 0..params.len() as i64 {
        if *unsafe { nikaia_std::proven::read(&params, (k) as usize) } != root { continue; }
        let handed = match path_of(nikaia_std::index::get(&args, (k) as usize), words) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if walk.pinned.contains(&path_root(&handed)) { return None; }
        let rest = nikaia_std::index::or(param.strip_prefix(&*root), || "");
        let path = format!("{}{}", handed, rest);
        let element = walk.arena.var(&bounding_element_of(&path));
        let mut key = elements_key(&walk.shape, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, words);
        if !rest.is_empty() {
            key = None;
            let parts: Vec<&str> = rest.split('.').collect::<Vec<_>>();
            let field = format!(".{}", *unsafe { nikaia_std::proven::read(&parts, (nikaia_std::proven::sub::<i64>(parts.len() as i64, 1)) as usize) });
            if walk.shape.fields.contains(&field) { key = Some(field); }
        }
        if key.is_some() {
            let bound = match bounding_assumed(walk, nikaia_std::index::or(key.as_deref(), || "")) { Some(__nikaia_value) => __nikaia_value, None => return Some(element) };
            if bound.lo.is_some() {
                let lo = walk.arena.int(nikaia_std::index::or(bound.lo, || 0));
                let low = walk.arena.ge(element, lo);
                given.push(bounding_each_guarded(walk, low));
            }
            if bound.hi.is_some() {
                let hi = walk.arena.int(nikaia_std::index::or(bound.hi, || 0));
                let high = walk.arena.le(element, hi);
                given.push(bounding_each_guarded(walk, high));
            }
        }
        return Some(element);
    }
    None
}

pub(crate) fn bounding_scaled(walk: &mut BoundsWalk, claim: &DerivedClaim, length: i64) -> i64 {
    let mut term = length;
    if claim.scale != 1 {
        let times = walk.arena.int(claim.scale);
        term = walk.arena.mul(times, term);
    }
    if claim.offset != 0 {
        let by = walk.arena.int(claim.offset);
        term = walk.arena.add(term, by);
    }
    term
}

pub(crate) fn bounding_derived_entry(walk: &mut BoundsWalk, facts: &mut BoundsFacts, args: &[FnArg], body: &Block, context: &BoundsContext) {
    let key = match derived_key(args, body) { Some(__nikaia_value) => __nikaia_value, None => return };
    let held = match *nikaia_std::index::get(&context.around.derived.entry, &key) { Some(__nikaia_value) => __nikaia_value, None => return };
    for claim in held.iter() {
        let left = if claim.left == "" { walk.arena.int(0) } else if claim.each { walk.arena.var(&bounding_element_of(&claim.left)) } else { walk.arena.var(&claim.left) };
        let right = if claim.fixed.is_some() { walk.arena.int(nikaia_std::index::or(claim.fixed, || 0)) } else if claim.length {
            walk.typed.insert(length_of(&claim.right), String::from("i64"));
            let length = walk.arena.var(&length_of(&claim.right));
            bounding_scaled(walk, claim, length)
        } else if claim.each { walk.arena.var(&bounding_element_of(&claim.right)) } else { walk.arena.var(&claim.right) };
        let side = if claim.apart { walk.arena.unequal(left, right) } else if claim.strict { walk.arena.lt(left, right) } else { walk.arena.le(left, right) };
        let fact = bounding_each_guarded(walk, side);
        bounding_push(&walk, facts, fact);
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_each(walk: &mut BoundsWalk, iter: &Expr, item: i64, turn: Option<i64>, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    match iter {
        Expr::MethodCall { receiver, method, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let ty = match *nikaia_std::index::get(&context.std_receivers, &(node_key(iter))) { Some(__nikaia_value) => __nikaia_value, None => return out };
            let each = match *nikaia_std::index::get(&context.each, &(format!("{}::{}", ty, words.resolve(method)))) { Some(__nikaia_value) => __nikaia_value, None => return out };
            let path = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return out };
            if (args.len() as i64) != each.params.len() as i64 { return out; }
            let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            for k in 0..args.len() as i64 { given.insert(nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&each.params, (k) as usize) }).to_string()), bounding_given(walk, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, facts, context, program, words)); }
            for (name, default) in each.options.iter() {
                let mut term: Option<i64> = None;
                for option in config.iter() { if words.resolve(option.name) == name { term = Some(bounding_given(walk, &option.value, facts, context, program, words)); } }
                if term.is_none() {
                    let written = text::parse_i64(default);
                    if written.is_some() { term = Some(walk.arena.int(nikaia_std::index::or(written, || 0))); } else { term = Some(bounding_fresh(walk)); }
                }
                given.insert(nikaia_std::block::Text::from(name.to_string()), nikaia_std::index::or(term, || 0));
            }
            given.insert(String::from("item"), item);
            let before = nikaia_std::index::or(turn, || bounding_fresh(walk).into());
            given.insert(String::from("turn"), before);
            given.insert(length_of("self"), bounding_length_named(walk, &path, true));
            out.reserve(each.conditions.iter().size_hint().0); for nodes in each.conditions.iter() {
                let read = walk.arena.adopt(nodes);
                out.push(walk.arena.substitute(read, &given));
            }
        },
        Expr::Call { .. } => {
            let zero = walk.arena.int(0);
            for (list, sized) in bounding_returned_below(walk, iter, true, context, words) {
                out.push(walk.arena.ge(item, zero));
                let len = bounding_length_named(walk, &list, sized);
                out.push(walk.arena.lt(item, len));
            }
            let range = match bounding_returned_values(walk, iter, context, words) { Some(__nikaia_value) => __nikaia_value, None => return out };
            if range.lo.is_some() && nikaia_std::index::or(range.lo, || 0) >= unsafe { nikaia_std::proven::sub::<i64>(0, solvable()) } {
                let lo = walk.arena.int(nikaia_std::index::or(range.lo, || 0));
                out.push(walk.arena.ge(item, lo));
            }
            if range.hi.is_some() && nikaia_std::index::or(range.hi, || 0) <= solvable() {
                let hi = walk.arena.int(nikaia_std::index::or(range.hi, || 0));
                out.push(walk.arena.le(item, hi));
            }
        },
        _ => { },
    }
    out
}

pub(crate) fn bounding_given(walk: &mut BoundsWalk, arg: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> i64 {
    let term = bounding_lin(walk, arg, facts, context, program, words);
    if term.is_some() { return nikaia_std::index::or(term, || 0); }
    bounding_fresh(walk)
}

pub(crate) fn bounding_fresh(walk: &mut BoundsWalk) -> i64 {
    let name = format!("given#{}", walk.codes);
    walk.codes += 1;
    walk.arena.var(&name)
}

pub(crate) fn bounding_element_var(walk: &mut BoundsWalk, path: &str, base: &Expr, words: &winnow_grammar::InternerContext) -> i64 {
    let v = walk.arena.var(path);
    walk.axioms.remove(path);
    let key = match elements_key(&walk.shape, base, words) { Some(__nikaia_value) => __nikaia_value, None => return v };
    let bound = match bounding_assumed(walk, &key) { Some(__nikaia_value) => __nikaia_value, None => return v };
    let mut held: Vec<i64> = vec![];
    if bound.lo.is_some() {
        let lo = walk.arena.int(nikaia_std::index::or(bound.lo, || 0));
        held.push(walk.arena.ge(v, lo));
    }
    if bound.hi.is_some() {
        let hi = walk.arena.int(nikaia_std::index::or(bound.hi, || 0));
        held.push(walk.arena.le(v, hi));
    }
    walk.axioms.insert(nikaia_std::block::Text::from(path.to_string()), held);
    v
}

pub(crate) fn bounding_element_of(name: &str) -> String { format!("{}.each()", name) }

pub(crate) fn bounding_each_guarded(walk: &mut BoundsWalk, fact: i64) -> i64 {
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(fact, &mut read);
    let zero = walk.arena.int(0);
    let mut parts: Vec<i64> = vec![];
    parts.reserve(read.iter().size_hint().0); for name in read.iter() {
        let pieces: Vec<&str> = name.split(".each()").collect::<Vec<_>>();
        if pieces.len() < 2 { continue; }
        let len = walk.arena.var(&length_of(*unsafe { nikaia_std::proven::read(&pieces, (0) as usize) }));
        parts.push(walk.arena.le(len, zero));
    }
    if parts.is_empty() { return fact; }
    parts.push(fact);
    walk.arena.or(parts)
}

pub(crate) fn bounding_each_present(walk: &mut BoundsWalk, list: &str) -> i64 {
    let len = walk.arena.var(&length_of(list));
    let one = walk.arena.int(1);
    walk.arena.ge(len, one)
}

pub(crate) fn bounding_each_unguarded(walk: &mut BoundsWalk, list: &str, fact: i64) -> i64 {
    let parts = match walk.arena.at(fact) {
        logic::SolverTerm::Or(parts) => parts,
        _ => return fact,
    };
    let length = length_of(list);
    let mut kept: Vec<i64> = vec![];
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        let guard = match walk.arena.at(part) {
            logic::SolverTerm::Le(a, b) => walk.arena.is_the_variable(a, &length) && nikaia_std::index::or(walk.arena.constant(b), || 1) == 0,
            _ => false,
        };
        if !guard { kept.push(part); }
    }
    if (kept.len() as i64) == parts.len() as i64 || kept.is_empty() { return fact; }
    if kept.len() == 1 { return *unsafe { nikaia_std::proven::read(&kept, (0) as usize) }; }
    walk.arena.or(kept)
}

pub(crate) fn bounding_variable(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match expr {
        Expr::Variable(name, _) => { let name = *name; Some(nikaia_std::block::Text::from(words.resolve(name).to_string())) },
        _ => None,
    }
}

pub(crate) fn bounding_length(walk: &mut BoundsWalk, receiver: &Expr, name: &str, context: &BoundsContext) -> Option<i64> {
    let fixed = context.array_lengths.get(&node_key(receiver));
    if fixed.is_some() { return Some(walk.arena.int(nikaia_std::index::or(fixed, || 0))); }
    if !context.lengths.contains(&node_key(receiver)) { return None; }
    let counted = bounding_counted_list(name, node_key(receiver), context);
    Some(bounding_length_named(walk, &counted, context.sized.contains(&node_key(receiver))))
}

pub(crate) fn bounding_counted_list(list: &str, node: i64, context: &BoundsContext) -> String {
    if context.text_bytes.contains(&node) {
        return nikaia_std::index::or(match list.strip_suffix(".bytes") {
            Some(__nikaia_it) => Some(nikaia_std::block::Text::from(__nikaia_it.to_string())),
            None => None,
        }, || nikaia_std::block::Text::from(list.to_string()).into());
    }
    nikaia_std::block::Text::from(list.to_string())
}

pub(crate) fn bounding_length_named(walk: &mut BoundsWalk, name: &str, sized: bool) -> i64 {
    let length = length_of(name);
    let n = walk.arena.var(&length);
    walk.typed.insert(nikaia_std::block::Text::from(length.to_string()), String::from("i64"));
    if sized {
        if !walk.axioms.contains_key(&length) {
            let zero = walk.arena.int(0);
            let most = walk.arena.int(length_below());
            let low = walk.arena.ge(n, zero);
            let high = walk.arena.le(n, most);
            walk.axioms.insert(length, vec![low, high]);
        }
    } else {
        walk.unsized_names.insert(nikaia_std::block::Text::from(length.to_string()));
        if !walk.floors.contains_key(&length) {
            let zero = walk.arena.int(0);
            let low = walk.arena.ge(n, zero);
            walk.floors.insert(length, low);
        }
    }
    n
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_lin_of(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    let l = match bounding_lin(walk, lhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let r = match bounding_lin(walk, rhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    bounding_combined(walk, op, l, r)
}

pub(crate) fn bounding_combined(walk: &mut BoundsWalk, op: &BinaryOp, l: i64, r: i64) -> Option<i64> {
    match op {
        BinaryOp::Add => { return Some(walk.arena.add(l, r)); },
        BinaryOp::Sub => { return Some(walk.arena.sub(l, r)); },
        BinaryOp::Mul => { return bounding_product(walk, l, r); },
        BinaryOp::Div => { return bounding_quotient(walk, l, r); },
        BinaryOp::Shr => { return bounding_halved(walk, l, r); },
        BinaryOp::BitXor => {
            if nikaia_std::index::or(walk.arena.constant(l), || 0) == 1 { return Some(bounding_flipped(walk, r)); }
            if nikaia_std::index::or(walk.arena.constant(r), || 0) == 1 { return Some(bounding_flipped(walk, l)); }
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_reads_own(walk: &BoundsWalk, term: i64) -> bool {
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(term, &mut read);
    for name in read.iter() { if name.starts_with("quotient#") || name.starts_with("shifted#") || name.starts_with("half#") { return true; } }
    false
}

pub(crate) fn bounding_defined(walk: &mut BoundsWalk, what: &str) -> (String, i64) {
    let name = format!("{}#{}", what, walk.codes);
    walk.codes += 1;
    let v = walk.arena.var(&name);
    (name, v)
}

pub(crate) fn bounding_quotient(walk: &mut BoundsWalk, l: i64, r: i64) -> Option<i64> {
    let c = match walk.arena.constant(r) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if c < 1 { return None; }
    if c == 1 { return Some(l); }
    let (name, q) = bounding_defined(walk, "quotient");
    let k = walk.arena.int(c);
    let cq = walk.arena.mul(k, q);
    let slack = walk.arena.int(unsafe { nikaia_std::proven::sub::<i64>(c, 1) });
    let zero = walk.arena.int(0);
    let up = walk.arena.add(cq, slack);
    let down = walk.arena.sub(cq, slack);
    let at_least = walk.arena.ge(l, zero);
    let from_below = walk.arena.le(cq, l);
    let to_above = walk.arena.le(l, up);
    let not_negative = walk.arena.and(vec![at_least, from_below, to_above]);
    let below = walk.arena.lt(l, zero);
    let from_down = walk.arena.le(down, l);
    let to_cq = walk.arena.le(l, cq);
    let negative = walk.arena.and(vec![below, from_down, to_cq]);
    let either = walk.arena.or(vec![not_negative, negative]);
    walk.defining.insert(name, vec![either]);
    Some(q)
}

pub(crate) fn bounding_halved(walk: &mut BoundsWalk, l: i64, r: i64) -> Option<i64> {
    let k = match walk.arena.constant(r) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if k < 0 || k > 62 { return None; }
    if k == 0 { return Some(l); }
    let (name, q) = bounding_defined(walk, "shifted");
    let power = walk.arena.int(1 << k);
    let pq = walk.arena.mul(power, q);
    let slack = walk.arena.int((1 << k) - 1);
    let up = walk.arena.add(pq, slack);
    let from_below = walk.arena.le(pq, l);
    let to_above = walk.arena.le(l, up);
    walk.defining.insert(name, vec![from_below, to_above]);
    Some(q)
}

pub(crate) fn bounding_flipped(walk: &mut BoundsWalk, l: i64) -> i64 {
    let (name, h) = bounding_defined(walk, "half");
    let two = walk.arena.int(2);
    let four = walk.arena.int(4);
    let one = walk.arena.int(1);
    let th = walk.arena.mul(two, h);
    let up = walk.arena.add(th, one);
    let from_below = walk.arena.le(th, l);
    let to_above = walk.arena.le(l, up);
    walk.defining.insert(name, vec![from_below, to_above]);
    let fh = walk.arena.mul(four, h);
    let raised = walk.arena.add(fh, one);
    walk.arena.sub(raised, l)
}

pub(crate) fn bounding_product(walk: &mut BoundsWalk, l: i64, r: i64) -> Option<i64> {
    if walk.arena.constant(l).is_none() && walk.arena.constant(r).is_none() { return None; }
    Some(walk.arena.mul(l, r))
}

pub(crate) fn bounding_called(walk: &mut BoundsWalk, wanted: &str, given: &[i64], depth: i64, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    if depth >= call_depth() { return None; }
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, receiver, args, config, ret_type, body, .. } => {
                let name = *name;
                if receiver.is_some() || !config.is_empty() { continue; }
                let declared = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                if words.resolve(declared) != wanted { continue; }
                let ret = match ret_type { Some(__nikaia_value) => __nikaia_value, None => continue };
                if !ret.generics.is_empty() || !is_whole_number(words.resolve(ret.name)) || body.stmts.len() != 1 { continue; }
                for only in body.stmts.iter() {
                    match &only.node {
                        Stmt::Return(returned) => {
                            let value = match returned { Some(__nikaia_value) => __nikaia_value, None => continue };
                            if (args.len() as i64) != given.len() as i64 { return None; }
                            let mut env: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
                            for k in 0..args.len() as i64 { env.insert(nikaia_std::block::Text::from(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.name).to_string()), *unsafe { nikaia_std::proven::read(&given, (k) as usize) }); }
                            return bounding_inline(walk, value, &env, depth, program, words);
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    None
}

pub(crate) fn bounding_inline(walk: &mut BoundsWalk, expr: &Expr, env: &collections::BTreeMap<String, i64>, depth: i64, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative, .. } => {
            let negative = *negative; let value = *value;
            let n = match integer_as_count(&integer(value, negative)) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return Some(walk.arena.int(n));
        },
        Expr::Variable(name, _) => {
            let name = *name;
            let term = match *nikaia_std::index::get(&env, words.resolve(name)) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
            return Some(term);
        },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Neg => {
                    let a = match bounding_inline(walk, expr, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.neg(a));
                },
                _ => { },
            }
        },
        Expr::Cast { expr, ty, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if ty.generics.is_empty() && is_whole_number(words.resolve(ty.name)) { return bounding_inline(walk, expr, env, depth, program, words); }
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            if config.is_empty() {
                let callee = match bounding_variable(func, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let mut given: Vec<i64> = vec![];
                given.reserve(args.iter().size_hint().0); for arg in args.iter() {
                    let term = match bounding_inline(walk, arg, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    given.push(term);
                }
                return bounding_called(walk, &callee, &given, depth + 1, program, words);
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let l = match bounding_inline(walk, lhs, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let r = match bounding_inline(walk, rhs, env, depth, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            return bounding_combined(walk, op, l, r);
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_claim(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match expr {
        Expr::LitBool(b, _) => { let b = *b; return Some(walk.arena.boolean(b)); },
        Expr::Variable(name, _) => { let name = *name; return bounding_flag_term(walk, facts, words.resolve(name), true); },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Not => { return bounding_denial(walk, expr, facts, context, program, words); },
                _ => { },
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            match op {
                BinaryOp::And => {
                    let l = bounding_claim(walk, lhs, facts, context, program, words);
                    let r = bounding_claim(walk, rhs, facts, context, program, words);
                    if l.is_some() && r.is_some() { return Some(walk.arena.and(vec![nikaia_std::index::or(l, || 0), nikaia_std::index::or(r, || 0)])); }
                    if l.is_some() { return std::convert::identity(l); }
                    return r;
                },
                BinaryOp::Or => {
                    let l = match bounding_claim(walk, lhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    let r = match bounding_claim(walk, rhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.or(vec![l, r]));
                },
                _ => { },
            }
        },
        _ => { },
    }
    let empty = bounding_emptiness(walk, expr, context, words, true);
    if empty.is_some() { return std::convert::identity(empty); }
    bounding_comparison(walk, expr, facts, context, program, words)
}

pub(crate) fn bounding_emptiness(walk: &mut BoundsWalk, expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext, empty: bool) -> Option<i64> {
    match expr {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() || words.resolve(method) != "is_empty" { return None; }
            let path = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let length = match bounding_length(walk, receiver, &path, context) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let zero = walk.arena.int(0);
            if empty { return Some(walk.arena.le(length, zero)); }
            return Some(walk.arena.gt(length, zero));
        },
        _ => return None,
    }
}

pub(crate) fn bounding_denial(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match expr {
        Expr::LitBool(b, _) => { let b = *b; return Some(walk.arena.boolean(!b)); },
        Expr::Variable(name, _) => { let name = *name; return bounding_flag_term(walk, facts, words.resolve(name), false); },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            match op {
                UnaryOp::Not => { return bounding_claim(walk, expr, facts, context, program, words); },
                _ => { },
            }
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            match op {
                BinaryOp::Or => {
                    let l = bounding_denial(walk, lhs, facts, context, program, words);
                    let r = bounding_denial(walk, rhs, facts, context, program, words);
                    if l.is_some() && r.is_some() { return Some(walk.arena.and(vec![nikaia_std::index::or(l, || 0), nikaia_std::index::or(r, || 0)])); }
                    if l.is_some() { return std::convert::identity(l); }
                    return r;
                },
                BinaryOp::And => {
                    let l = match bounding_denial(walk, lhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    let r = match bounding_denial(walk, rhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    return Some(walk.arena.or(vec![l, r]));
                },
                _ => { },
            }
            let compares = matches!(op, BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge | BinaryOp::Eq | BinaryOp::Ne);
            if compares {
                let a = match bounding_lin(walk, lhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let b = match bounding_lin(walk, rhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                match op {
                    BinaryOp::Lt => { return Some(walk.arena.ge(a, b)); },
                    BinaryOp::Le => { return Some(walk.arena.gt(a, b)); },
                    BinaryOp::Gt => { return Some(walk.arena.le(a, b)); },
                    BinaryOp::Ge => { return Some(walk.arena.lt(a, b)); },
                    BinaryOp::Eq => { return Some(walk.arena.unequal(a, b)); },
                    _ => { return Some(walk.arena.equal(a, b)); },
                }
            }
        },
        _ => { },
    }
    bounding_emptiness(walk, expr, context, words, false)
}

pub(crate) fn bounding_flag_term(walk: &mut BoundsWalk, facts: &BoundsFacts, name: &str, up: bool) -> Option<i64> {
    if facts.ints.contains(name) || walk.shape.constants.contains_key(name) { return None; }
    let n = walk.arena.var(name);
    if up {
        let one = walk.arena.int(1);
        return Some(walk.arena.ge(n, one));
    }
    let zero = walk.arena.int(0);
    Some(walk.arena.le(n, zero))
}

pub(crate) fn bounding_flag_set(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, up: bool) {
    let n = walk.arena.var(name);
    let value = walk.arena.int(if up { 1 } else { 0 });
    if up {
        let mut held = nikaia_std::index::or(match walk.flagged.get(name) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        for fact in facts.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            if !bounding_touches(&walk, fact, name) && !held.contains(&fact) { held.push(fact); }
        }
        while (held.len() as i64) > most_flagged() { held.remove(0); }
        walk.flagged.insert(nikaia_std::block::Text::from(name.to_string()), held);
    }
    let fact = walk.arena.equal(n, value);
    bounding_push(&walk, facts, fact);
}

pub(crate) fn most_flagged() -> i64 { 24 }

pub(crate) fn bounding_comparison(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match expr {
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let compares = matches!(op, BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge | BinaryOp::Eq | BinaryOp::Ne);
            if !compares { return None; }
            let a = match bounding_lin(walk, lhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let b = match bounding_lin(walk, rhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            match op {
                BinaryOp::Lt => { return Some(walk.arena.lt(a, b)); },
                BinaryOp::Le => { return Some(walk.arena.le(a, b)); },
                BinaryOp::Gt => { return Some(walk.arena.gt(a, b)); },
                BinaryOp::Ge => { return Some(walk.arena.ge(a, b)); },
                BinaryOp::Eq => { return Some(walk.arena.equal(a, b)); },
                _ => { return Some(walk.arena.unequal(a, b)); },
            }
        },
        _ => { },
    }
    None
}

pub(crate) fn bounding_assume(walk: &mut BoundsWalk, facts: &mut BoundsFacts, cond: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) {
    bounding_name_calls(walk, facts, cond, context, program, words);
    let holds = bounding_claim(walk, cond, &facts, context, program, words);
    walk.call_names = collections::BTreeMap::new();
    if holds.is_some() { bounding_push(&walk, facts, nikaia_std::index::or(holds, || 0)); }
}

pub(crate) fn bounding_assume_not(walk: &mut BoundsWalk, facts: &mut BoundsFacts, cond: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) {
    bounding_name_calls(walk, facts, cond, context, program, words);
    let holds = bounding_denial(walk, cond, &facts, context, program, words);
    walk.call_names = collections::BTreeMap::new();
    if holds.is_some() { bounding_push(&walk, facts, nikaia_std::index::or(holds, || 0)); }
}

pub(crate) fn bounding_name_calls(walk: &mut BoundsWalk, facts: &mut BoundsFacts, cond: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) {
    match cond {
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); match op {
            UnaryOp::Not => { bounding_name_calls(walk, facts, expr, context, program, words); },
            _ => { },
        }; },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if *op == BinaryOp::And || *op == BinaryOp::Or {
                bounding_name_calls(walk, facts, lhs, context, program, words);
                bounding_name_calls(walk, facts, rhs, context, program, words);
            } else if *op == BinaryOp::Lt || *op == BinaryOp::Le || *op == BinaryOp::Gt || *op == BinaryOp::Ge || *op == BinaryOp::Eq || *op == BinaryOp::Ne {
                bounding_name_call(walk, facts, lhs, context, program, words);
                bounding_name_call(walk, facts, rhs, context, program, words);
            }
        },
        _ => { },
    }
}

pub(crate) fn bounding_name_call(walk: &mut BoundsWalk, facts: &mut BoundsFacts, side: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) {
    let call = matches!(side, Expr::Call { .. } | Expr::MethodCall { .. });
    if !call || bounding_found_options(side) || bounding_lin(walk, side, &facts, context, program, words).is_some() { return; }
    let callee = match bounding_found_key(&walk, side, context, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
    let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return };
    if found.each || found.pending { return; }
    let name = format!("call#{}", walk.codes);
    walk.codes += 1;
    let n = walk.arena.var(&name);
    let mut held: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    held.reserve(found.at_least.iter().size_hint().0); for k in found.at_least.iter() {
        let k = nikaia_std::num::value(k);
        let term = match bounding_found_term(walk, side, k, &facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        held.push(walk.arena.ge(n, term));
    }
    held.reserve(found.within.iter().size_hint().0); for k in found.within.iter() {
        let k = nikaia_std::num::value(k);
        let path = match bounding_found_path(side, found, k, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if walk.pinned.contains(&path_root(&path)) { continue; }
        let len = bounding_length_named(walk, &path, false);
        held.push(if found.under.contains(&k) { walk.arena.lt(n, len) } else { walk.arena.le(n, len) });
    }
    if held.is_empty() { return; }
    facts.ints.insert(nikaia_std::block::Text::from(name.to_string()));
    for fact in held.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    walk.call_names.insert(node_key(side), name);
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_inside(walk: &mut BoundsWalk, list: &str, node: i64, index: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    if walk.collecting || walk.pinned.contains(&path_root(list)) { return false; }
    let len = bounding_list_length(walk, list, node, context);
    match index {
        Expr::Range { start, end, inclusive, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); let inclusive = *inclusive;
            let from = match bounding_lin(walk, start, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
            let to = match bounding_lin(walk, end, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
            let zero = walk.arena.int(0);
            let low = walk.arena.ge(from, zero);
            let ordered = walk.arena.le(from, to);
            let mut high = walk.arena.le(to, len);
            if inclusive { high = walk.arena.lt(to, len); }
            let goal = walk.arena.and(vec![low, ordered, high]);
            return bounding_proves_goal(walk, facts, goal, &mut *ask);
        },
        _ => { },
    }
    let at = bounding_lin(walk, index, facts, context, program, words);
    if at.is_some() {
        let position = nikaia_std::index::or(at, || 0);
        let zero = walk.arena.int(0);
        let low = walk.arena.ge(position, zero);
        let high = walk.arena.lt(position, len);
        let goal = walk.arena.and(vec![low, high]);
        if bounding_proves_goal(walk, facts, goal, &mut *ask) { return true; }
        match index {
            Expr::Index { .. } => { },
            _ => { return false; },
        }
    }
    if rules_element_inside(walk, len, index, facts, words, &mut *ask) { return true; }
    if bounding_end_inside(walk, len, index, facts, words, &mut *ask) { return true; }
    let range = match bounding_range(walk, index, facts, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let lo = match range.lo { Some(__nikaia_value) => __nikaia_value, None => return false };
    let hi = match range.hi { Some(__nikaia_value) => __nikaia_value, None => return false };
    if lo < 0 { return false; }
    let most = walk.arena.int(hi);
    let goal = walk.arena.lt(most, len);
    bounding_proves_goal(walk, facts, goal, &mut *ask)
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_word_inside(walk: &mut BoundsWalk, list: &str, node: i64, at: &Expr, width: i64, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    if walk.collecting || walk.pinned.contains(&path_root(list)) { return false; }
    let len = bounding_list_length(walk, list, node, context);
    let from = match bounding_lin(walk, at, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let zero = walk.arena.int(0);
    let n = walk.arena.int(width);
    let to = walk.arena.add(from, n);
    let low = walk.arena.ge(from, zero);
    let high = walk.arena.le(to, len);
    let goal = walk.arena.and(vec![low, high]);
    bounding_proves_goal(walk, facts, goal, &mut *ask)
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_index(walk: &mut BoundsWalk, base: &Expr, index: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let list = match path_of(base, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    if bounding_inside(walk, &list, node_key(base), index, facts, context, program, words, &mut *ask) {
        walk.proven.indices.insert(node_key(base));
        if bounding_tracing(&walk) { bounding_trace_row(walk, format!("  read {}[…]: proved", list)); }
    } else {
        walk.open += 1;
        if bounding_tracing(&walk) { bounding_trace_row(walk, format!("  read {}[…]: checked", list)); }
    }
}

pub(crate) fn bounding_list_length(walk: &mut BoundsWalk, list: &str, node: i64, context: &BoundsContext) -> i64 {
    let fixed = context.array_lengths.get(&node);
    if fixed.is_some() { return walk.arena.int(nikaia_std::index::or(fixed, || 0)); }
    walk.arena.var(&length_of(&bounding_counted_list(list, node, context)))
}

pub(crate) fn bounding_block(walk: &mut BoundsWalk, block: &Block, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let before = facts.ints.copy_owned();
    let mut bound: Vec<String> = vec![];
    let leaves = bounding_stmts(walk, block, 0, facts, &mut bound, context, program, words, &mut &mut *ask);
    for name in bound.iter() {
        bounding_leave(walk, facts, name);
        facts.ints.remove(name);
        if before.contains(name) { facts.ints.insert(nikaia_std::block::Text::from(name.to_string())); }
    }
    leaves
}

pub(crate) fn bounding_leave(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str) {
    let mut value: Option<i64> = None;
    let mut by: i64 = -1;
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        match walk.arena.at(fact) {
            logic::SolverTerm::Eq(a, b) => { if walk.arena.is_the_variable(a, name) && !walk.arena.mentions(b, name) { value = Some(b); } else if walk.arena.is_the_variable(b, name) && !walk.arena.mentions(a, name) { value = Some(a); } },
            _ => { },
        }
        if value.is_some() {
            by = fact;
            break;
        }
    }
    if value.is_some() {
        let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        given.insert(nikaia_std::block::Text::from(name.to_string()), nikaia_std::index::or(value, || 0));
        let mut kept: Vec<i64> = vec![];
        for fact in facts.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            if fact == by { continue; }
            if walk.arena.mentions(fact, name) { kept.push(walk.arena.substitute(fact, &given)); } else { kept.push(fact); }
        }
        facts.facts = kept;
    }
    bounding_forget(&walk, facts, name);
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_stmts(walk: &mut BoundsWalk, block: &Block, from: i64, facts: &mut BoundsFacts, bound: &mut Vec<String>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let mut at = from;
    for stmt in nikaia_std::index::get(&block.stmts, nikaia_std::index::at(from..)).iter() {
        match &stmt.node {
            Stmt::Let { names, .. } => {
                bound.reserve(names.iter().size_hint().0); for name in names.iter() {
                    let name = *name;
                    bound.push(nikaia_std::block::Text::from(words.resolve(name).to_string()));
                }
            },
            Stmt::Comptime { name, .. } => { let name = *name; bound.push(nikaia_std::block::Text::from(words.resolve(name).to_string())); },
            _ => { },
        }
        walk.at = stmt.span.start as i64;
        let looped = matches!(stmt.node, Stmt::For { .. } | Stmt::While { .. });
        if looped && context.through_loops && !walk.collecting && !walk.checking { return bounding_past_loop(walk, block, at, &stmt.node, facts, bound, context, program, words, &mut &mut *ask); }
        if bounding_stmt(walk, &stmt.node, facts, context, program, words, &mut &mut *ask) { return true; }
        at += 1;
    }
    false
}

pub(crate) fn bounding_maybe_block(walk: &mut BoundsWalk, block: Option<&Block>, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return false };
    bounding_block(walk, present, facts, context, program, words, &mut &mut *ask)
}

pub(crate) fn bounding_stmt(walk: &mut BoundsWalk, stmt: &Stmt, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    walk.defining.clear();
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            bounding_let(walk, names, (ty).as_ref(), value, facts, context, program, words, &mut &mut *ask);
            return false;
        },
        Stmt::Comptime { name, value, .. } => {
            let name = *name;
            bounding_expr(walk, value, facts, context, program, words, &mut &mut *ask);
            let text = words.resolve(name);
            bounding_forget(&walk, facts, text);
            facts.ints.remove(text);
            return false;
        },
        Stmt::Assign { target, op, value } => {
            let at = walk.at;
            bounding_expr(walk, value, facts, context, program, words, &mut &mut *ask);
            bounding_place(walk, target, facts, context, program, words, &mut &mut *ask);
            rules_element_write(walk, &facts, target, (op).as_ref(), value, context, program, words, &mut &mut *ask);
            bounding_compound(walk, (op).as_ref(), target, value, at, &facts, context, program, words, &mut &mut *ask);
            if op.is_none() {
                match target {
                    Expr::Field { name, .. } => {
                        let name = *name;
                        let key = format!(".{}", words.resolve(name));
                        if walk.shape.fields.contains(&key) { bounding_field_list(walk, &key, value, &facts, context, program, words, &mut &mut *ask); }
                    },
                    Expr::Index { base, .. } => {
                        let base = nikaia_std::boxed::open(base);
                        let key = elements_key(&walk.shape, base, words);
                        if key.is_some() { bounding_write(walk, nikaia_std::index::or(key.as_deref(), || ""), value, &facts, context, program, words, &mut &mut *ask); }
                    },
                    _ => { },
                }
            }
            bounding_forget_aliases(&walk, facts, target, words);
            match target {
                Expr::Variable(name, _) => {
                    let name = *name;
                    bounding_forget_elements_at(&walk, facts, words.resolve(name));
                    bounding_assign(walk, facts, words.resolve(name), (op).as_ref(), value, context, program, words, &mut &mut *ask);
                },
                Expr::Field { .. } => { bounding_assign_place(walk, facts, target, (op).as_ref(), value, context, program, words, &mut &mut *ask); },
                Expr::Index { .. } => { bounding_assign_place(walk, facts, target, (op).as_ref(), value, context, program, words, &mut &mut *ask); },
                _ => { },
            }
            return false;
        },
        Stmt::For { .. } => {
            bounding_loop_stmt(walk, stmt, facts, context, program, words, &mut &mut *ask);
            return false;
        },
        Stmt::While { .. } => {
            bounding_loop_stmt(walk, stmt, facts, context, program, words, &mut &mut *ask);
            return false;
        },
        Stmt::Return(value) => {
            if value.is_some() {
                let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return true };
                bounding_expr(walk, returned, facts, context, program, words, &mut &mut *ask);
            }
            rules_exit(walk, &facts, (value).as_ref(), false, context, program, words, &mut &mut *ask);
            return true;
        },
        Stmt::Break => {
            bounding_turn_end(walk, &facts, true, true, &mut &mut *ask);
            return true;
        },
        Stmt::Continue => {
            bounding_turn_end(walk, &facts, true, false, &mut &mut *ask);
            return true;
        },
        Stmt::Expr(expr) => return bounding_expr_leaves(walk, expr, facts, context, program, words, &mut &mut *ask),
        Stmt::Emit(expr) => return bounding_expr_leaves(walk, expr, facts, context, program, words, &mut &mut *ask),
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_for_stmt(walk: &mut BoundsWalk, bindings: &[winnow_grammar::Symbol], iter: &Expr, body: &Block, facts: &mut BoundsFacts, invariant: &[i64], context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let changed = bounding_changed(body, context, words);
    #[allow(unused_mut)] let mut cands = bounding_candidates(&walk, &changed, &facts);
    if cands.is_empty() {
        bounding_for(walk, bindings, iter, body, facts, &cands, invariant, context, program, words, &mut &mut *ask);
        return;
    }
    let start = facts.clone();
    let proven = walk.proven.clone();
    let written = walk.written.copy_owned(); #[allow(unused_mut, clippy::redundant_locals)] let mut cands = cands; #[allow(clippy::redundant_locals)] let proven = proven;
    let poisoned = walk.poisoned.copy_owned(); #[allow(unused_mut, clippy::redundant_locals)] let mut cands = cands; #[allow(clippy::redundant_locals)] let proven = proven;
    let falls = bounding_falls(&changed, &cands); #[allow(clippy::redundant_locals)] let proven = proven;
    loop {
        let added = bounding_grow(walk, &cands, &falls);
        bounding_for(walk, bindings, iter, body, facts, &cands, invariant, context, program, words, &mut &mut *ask);
        let failed = bounding_grew(walk, &cands, &added);
        if failed.is_empty() { return; }
        walk.proven = proven.clone();
        walk.written = written.copy_owned();
        walk.poisoned = poisoned.copy_owned();
        facts.facts = start.facts.copy_owned();
        facts.ints = start.ints.copy_owned();
        cands = bounding_without(&cands, &failed);
    }
    return;
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_while_stmt(walk: &mut BoundsWalk, cond: &Expr, body: &Block, facts: &mut BoundsFacts, invariant: &[i64], context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let mut changed = bounding_changed(body, context, words);
    bounding_extend(&mut changed, &bounding_changed_in_expr(cond, context, words));
    #[allow(unused_mut)] let mut cands = bounding_candidates(&walk, &changed, &facts);
    if cands.is_empty() {
        bounding_while(walk, cond, body, &changed, &cands, facts, invariant, context, program, words, &mut &mut *ask);
        return;
    }
    let start = facts.clone();
    let proven = walk.proven.clone();
    let written = walk.written.copy_owned(); #[allow(unused_mut, clippy::redundant_locals)] let mut cands = cands; #[allow(clippy::redundant_locals)] let proven = proven;
    let poisoned = walk.poisoned.copy_owned(); #[allow(unused_mut, clippy::redundant_locals)] let mut cands = cands; #[allow(clippy::redundant_locals)] let proven = proven;
    let falls = bounding_falls(&changed, &cands); #[allow(clippy::redundant_locals)] let proven = proven;
    loop {
        let added = bounding_grow(walk, &cands, &falls);
        bounding_while(walk, cond, body, &changed, &cands, facts, invariant, context, program, words, &mut &mut *ask);
        let failed = bounding_grew(walk, &cands, &added);
        if failed.is_empty() { return; }
        walk.proven = proven.clone();
        walk.written = written.copy_owned();
        walk.poisoned = poisoned.copy_owned();
        facts.facts = start.facts.copy_owned();
        facts.ints = start.ints.copy_owned();
        cands = bounding_without(&cands, &failed);
    }
    return;
}

pub(crate) fn bounding_loop_stmt(walk: &mut BoundsWalk, stmt: &Stmt, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let start = walk.at;
    let open = walk.open;
    walk.settled_loops.remove(&start);
    if !context.through_loops || walk.collecting || walk.checking {
        bounding_loop_framed(walk, stmt, facts, context, program, words, &mut &mut *ask);
        return;
    }
    let entry = facts.clone();
    let proven = walk.proven.clone();
    let written = walk.written.copy_owned(); #[allow(clippy::redundant_locals)] let proven = proven;
    let poisoned = walk.poisoned.copy_owned(); #[allow(clippy::redundant_locals)] let proven = proven;
    bounding_loop_framed(walk, stmt, facts, context, program, words, &mut &mut *ask);
    if walk.open == open { return; }
    let changed = bounding_loop_changed(stmt, context, words);
    let mut wanted: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (name, stamp) in walk.missed.iter() {
        let stamp = nikaia_std::num::value(stamp);
        if stamp > open && bounding_changes_name(&changed, name) { wanted.insert(nikaia_std::block::Text::from(name.to_string())); }
    }
    if wanted.is_empty() { return; }
    let after = facts.clone();
    let after_proven = walk.proven.clone();
    let after_written = walk.written.copy_owned();
    let after_poisoned = walk.poisoned.copy_owned();
    let after_open = walk.open;
    let found = bounding_loop_invariant(walk, stmt, start, entry, &written, &poisoned, &changed, &wanted, Some(open), context, program, words, &mut &mut *ask);
    if found.is_some() {
        let invariant = match found { Some(__nikaia_value) => __nikaia_value, None => return };
        if invariant.settled && bounding_could_pay(walk, &invariant.guesses, open, &mut &mut *ask) {
            walk.proven = proven.clone();
            walk.written = written.copy_owned();
            walk.poisoned = poisoned.copy_owned();
            walk.open = open;
            let mut here = invariant.entry.clone();
            walk.turns.push(BoundsTurn { guesses: invariant.guesses.copy_owned(), failed: collections::BTreeSet::new(), jumps: collections::BTreeSet::new() });
            bounding_loop_walk(walk, stmt, &mut here, &invariant.guesses, context, program, words, &mut &mut *ask);
            let frame = nikaia_std::index::or(walk.turns.pop(), || BoundsTurn { guesses: vec![], failed: collections::BTreeSet::new(), jumps: collections::BTreeSet::new() });
            if frame.failed.is_empty() && (frame.jumps.len() as i64) == invariant.ways && bounding_proven_count(&walk.proven) > bounding_proven_count(&after_proven) {
                bounding_loop_found(walk, start, &invariant);
                facts.facts = here.facts.copy_owned();
                facts.ints = here.ints.copy_owned();
                bounding_loop_left(&walk, facts, &invariant.guesses, &changed);
                walk.settled_loops.insert(start);
                return;
            }
        }
    }
    walk.proven = after_proven;
    walk.written = after_written;
    walk.poisoned = after_poisoned;
    walk.open = after_open;
    facts.facts = after.facts.copy_owned();
    facts.ints = after.ints.copy_owned();
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct BoundsInvariant {
    pub(crate) guesses: Vec<i64>,
    pub(crate) origins: collections::BTreeMap<i64, String>,
    pub(crate) entry: BoundsFacts,
    pub(crate) past: BoundsFacts,
    pub(crate) settled: bool,
    pub(crate) ways: i64,
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_loop_invariant(walk: &mut BoundsWalk, stmt: &Stmt, start: i64, entry: BoundsFacts, written: &collections::BTreeMap<String, Range>, poisoned: &collections::BTreeSet<String>, changed: &BoundsChanged, wanted: &collections::BTreeSet<String>, open: Option<i64>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<BoundsInvariant> {
    let ways = match stmt {
        Stmt::For { body, .. } => turn_jumps(body, words),
        Stmt::While { body, .. } => turn_jumps(body, words),
        _ => return None,
    };
    let mut reached = entry;
    let own_guesses = bounding_loop_guesses(walk, stmt, &reached, changed, context, program, words);
    let proposals = bounding_loop_proposals(walk, stmt, start, &reached, changed, words, &mut &mut *ask);
    let mut offered = proposals.candidates.copy_owned();
    offered.reserve(own_guesses.iter().size_hint().0); for guess in own_guesses.iter() {
        let guess = nikaia_std::num::value(guess);
        offered.push((guess, String::from("guess and check")));
    }
    for ghost in proposals.ghosts.iter() {
        let ghost = nikaia_std::num::value(ghost);
        reached.facts.push(ghost);
    }
    let mut origins: collections::BTreeMap<i64, String> = collections::BTreeMap::new();
    let mut guesses: Vec<i64> = vec![];
    guesses.reserve(proposals.fixed.iter().size_hint().0); for fixed in proposals.fixed.iter() {
        let fixed = nikaia_std::num::value(fixed);
        guesses.push(fixed);
        origins.insert(fixed, String::from("closed forms"));
    }
    for (guess, origin) in offered.iter() {
        let guess = nikaia_std::num::value(guess);
        if origins.contains_key(&guess) { continue; }
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(guess, &mut read);
        let mut useful = false;
        for name in read.iter() { if wanted.contains(name) { useful = true; } }
        if useful && bounding_proves(&walk, &reached, guess, &mut &mut *ask) {
            guesses.push(guess);
            origins.insert(guess, nikaia_std::block::Text::from(origin.to_string()));
        }
    }
    let mut asked: Vec<i64> = vec![];
    asked.reserve(offered.iter().size_hint().0); for (guess, _) in offered.iter() {
        let guess = nikaia_std::num::value(guess);
        asked.push(guess);
    }
    ({ let __nikaia_arg2 = format!("  loop: offered {}\n    held where reached: {}", bounding_texts(&walk, &asked), bounding_texts(&walk, &guesses)); bounding_turn_row(walk, start, __nikaia_arg2) });
    if (guesses.len() as i64) == proposals.fixed.len() as i64 { return None; }
    if guesses.is_empty() { return None; }
    if open.is_some() && !bounding_could_pay(walk, &guesses, nikaia_std::index::or(open, || 0), &mut &mut *ask) { return None; }
    let mut settled = false;
    let mut past = reached.clone();
    for attempt in 0..4 {
        walk.written = written.copy_owned();
        walk.poisoned = poisoned.copy_owned();
        let mut here = reached.clone();
        walk.collecting = true;
        walk.turns.push(BoundsTurn { guesses: guesses.copy_owned(), failed: collections::BTreeSet::new(), jumps: collections::BTreeSet::new() });
        bounding_loop_walk(walk, stmt, &mut here, &guesses, context, program, words, &mut &mut *ask);
        walk.collecting = false;
        let frame = match walk.turns.pop() { Some(__nikaia_value) => __nikaia_value, None => break };
        bounding_turn_row(walk, start, format!("  loop round {}: {} of {} ways out walked, {} of {} not kept", attempt, frame.jumps.len() as i64, ways, frame.failed.len() as i64, guesses.len() as i64));
        if (frame.jumps.len() as i64) != ways { break; }
        if frame.failed.is_empty() {
            settled = true;
            past = here;
            break;
        }
        let mut kept: Vec<i64> = vec![];
        for k in 0..guesses.len() as i64 { if !frame.failed.contains(&k) { kept.push(*unsafe { nikaia_std::proven::read(&guesses, (k) as usize) }); } }
        guesses = kept;
        if guesses.is_empty() { break; }
    }
    Some(BoundsInvariant { guesses, origins, entry: reached, past, settled, ways })
}

pub(crate) fn bounding_loop_found(walk: &mut BoundsWalk, start: i64, invariant: &BoundsInvariant) {
    let mut parts: Vec<(i64, String)> = vec![];
    parts.reserve(invariant.guesses.iter().size_hint().0); for guess in invariant.guesses.iter() {
        let guess = nikaia_std::num::value(guess);
        parts.push((guess, nikaia_std::block::Text::from(nikaia_std::index::or(*nikaia_std::index::get(&invariant.origins, &guess), || "guess and check").to_string())));
    }
    walk.proven.loops.insert(start, loop_parts_text(&walk.arena, &LoopFound { parts }));
}

pub(crate) fn bounding_loop_left(walk: &BoundsWalk, facts: &mut BoundsFacts, guesses: &[i64], changed: &BoundsChanged) {
    for guess in guesses.iter() {
        let guess = nikaia_std::num::value(guess);
        if walk.leaving.contains(&guess) {
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            walk.arena.variables(guess, &mut read);
            for name in read.iter() { if bounding_changes_name(changed, name) { bounding_forget(walk, facts, name); } }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct BoundsMark {
    pub(crate) facts: BoundsFacts,
    pub(crate) proven: BoundsProven,
    pub(crate) written: collections::BTreeMap<String, Range>,
    pub(crate) poisoned: collections::BTreeSet<String>,
    pub(crate) open: i64,
    pub(crate) missed: collections::BTreeMap<String, i64>,
    pub(crate) missed_goals: Vec<BoundsMissed>,
    pub(crate) turns: Vec<BoundsTurn>,
    pub(crate) grow_failed: collections::BTreeSet<String>,
    pub(crate) fall_failed: collections::BTreeSet<String>,
    pub(crate) checked_results: collections::BTreeSet<i64>,
    pub(crate) rule_failed: collections::BTreeSet<i64>,
    pub(crate) bound: Vec<String>,
}

pub(crate) fn bounding_mark(walk: &BoundsWalk, facts: &BoundsFacts, bound: &[String]) -> BoundsMark { BoundsMark { facts: facts.clone(), proven: walk.proven.clone(), written: walk.written.copy_owned(), poisoned: walk.poisoned.copy_owned(), open: walk.open, missed: walk.missed.copy_owned(), missed_goals: walk.missed_goals.copy_owned(), turns: walk.turns.copy_owned(), grow_failed: walk.grow_failed.copy_owned(), fall_failed: walk.fall_failed.copy_owned(), checked_results: walk.checked_results.copy_owned(), rule_failed: walk.rule_failed.copy_owned(), bound: bound.copy_owned() } }

pub(crate) fn bounding_back(walk: &mut BoundsWalk, facts: &mut BoundsFacts, bound: &mut Vec<String>, mark: &BoundsMark) {
    facts.facts = mark.facts.facts.copy_owned();
    facts.ints = mark.facts.ints.copy_owned();
    walk.proven = mark.proven.clone();
    walk.written = mark.written.copy_owned();
    walk.poisoned = mark.poisoned.copy_owned();
    walk.open = mark.open;
    walk.missed = mark.missed.copy_owned();
    walk.missed_goals = mark.missed_goals.copy_owned();
    walk.turns = mark.turns.copy_owned();
    walk.grow_failed = mark.grow_failed.copy_owned();
    walk.fall_failed = mark.fall_failed.copy_owned();
    walk.checked_results = mark.checked_results.copy_owned();
    walk.rule_failed = mark.rule_failed.copy_owned();
    bound.clear();
    bound.reserve(mark.bound.iter().size_hint().0); for name in mark.bound.iter() { bound.push(nikaia_std::block::Text::from(name.to_string())); }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_past_loop(walk: &mut BoundsWalk, block: &Block, from: i64, stmt: &Stmt, facts: &mut BoundsFacts, bound: &mut Vec<String>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let start = walk.at;
    let entry = facts.clone();
    let written = walk.written.copy_owned();
    let poisoned = walk.poisoned.copy_owned();
    bounding_stmt(walk, stmt, facts, context, program, words, &mut &mut *ask);
    let past = bounding_mark(&walk, &facts, &bound);
    let leaves = bounding_stmts(walk, block, from + 1, facts, bound, context, program, words, &mut &mut *ask);
    if walk.open == past.open || walk.settled_loops.contains(&start) { return leaves; }
    let changed = bounding_loop_changed(stmt, context, words);
    let mut wanted: collections::BTreeSet<String> = collections::BTreeSet::new(); #[allow(clippy::redundant_locals)] let past = past;
    for (name, stamp) in walk.missed.iter() {
        let stamp = nikaia_std::num::value(stamp);
        if stamp > past.open && bounding_changes_name(&changed, name) { wanted.insert(nikaia_std::block::Text::from(name.to_string())); }
    }
    let mut only_flags: Option<i64> = None;
    if wanted.is_empty() {
        for missed in walk.missed_goals.iter() {
            if missed.stamp <= past.open { continue; }
            for fact in missed.facts.iter() {
                let fact = nikaia_std::num::value(fact);
                let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
                walk.arena.variables(fact, &mut read);
                for name in read.iter() { if bounding_changes_name(&changed, name) && (walk.flagged.contains_key(name) || name.ends_with(".len()")) { wanted.insert(nikaia_std::block::Text::from(name.to_string())); } }
            }
        }
        only_flags = Some(past.open);
    }
    if wanted.is_empty() { return leaves; }
    let end = bounding_mark(&walk, &facts, &bound);
    let found = bounding_loop_invariant(walk, stmt, start, entry, &written, &poisoned, &changed, &wanted, only_flags, context, program, words, &mut &mut *ask);
    if found.is_some() {
        let invariant = match found { Some(__nikaia_value) => __nikaia_value, None => return leaves };
        if invariant.settled {
            bounding_back(walk, facts, bound, &past);
            facts.facts = invariant.past.facts.copy_owned();
            facts.ints = invariant.past.ints.copy_owned();
            bounding_loop_left(&walk, facts, &invariant.guesses, &changed);
            let again = bounding_stmts(walk, block, from + 1, facts, bound, context, program, words, &mut &mut *ask);
            if bounding_proven_count(&walk.proven) > bounding_proven_count(&end.proven) {
                bounding_loop_found(walk, start, &invariant);
                return again;
            }
        }
    }
    bounding_back(walk, facts, bound, &end);
    leaves
}

pub(crate) fn bounding_could_pay(walk: &mut BoundsWalk, guesses: &[i64], open: i64, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    for missed in walk.missed_goals.iter() {
        if missed.stamp <= open { continue; }
        let mut there = BoundsFacts { ints: collections::BTreeSet::new(), facts: missed.facts.copy_owned(), evicted: 0 };
        for guess in guesses.iter() {
            let guess = nikaia_std::num::value(guess);
            there.facts.push(guess);
        }
        if bounding_proves(&walk, &there, missed.goal, &mut *ask) { return true; }
    }
    false
}

pub(crate) fn bounding_loop_framed(walk: &mut BoundsWalk, stmt: &Stmt, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let none: Vec<i64> = vec![];
    if walk.turns.is_empty() {
        bounding_loop_walk(walk, stmt, facts, &none, context, program, words, &mut &mut *ask);
        return;
    }
    walk.turns.push(BoundsTurn { guesses: vec![], failed: collections::BTreeSet::new(), jumps: collections::BTreeSet::new() });
    bounding_loop_walk(walk, stmt, facts, &none, context, program, words, &mut &mut *ask);
    walk.turns.pop();
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_loop_walk(walk: &mut BoundsWalk, stmt: &Stmt, facts: &mut BoundsFacts, invariant: &[i64], context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    match stmt {
        Stmt::For { bindings, iter, body, .. } => { bounding_for_stmt(walk, bindings, iter, body, facts, invariant, context, program, words, &mut &mut *ask); },
        Stmt::While { cond, body } => { bounding_while_stmt(walk, cond, body, facts, invariant, context, program, words, &mut &mut *ask); },
        _ => { },
    }
}

pub(crate) fn bounding_loop_guesses(walk: &mut BoundsWalk, stmt: &Stmt, entry: &BoundsFacts, changed: &BoundsChanged, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Vec<i64> {
    #[allow(unused_mut)] let mut bound: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    match stmt {
        Stmt::For { bindings, .. } => {
            bound.reserve(bindings.iter().size_hint().0); for binding in bindings.iter() {
                let binding = *binding;
                bound.push(nikaia_std::block::Text::from(words.resolve(binding).to_string()));
            }
        },
        _ => { },
    }
    let mut head = entry.clone();
    bounding_after_change(walk, &mut head, changed);
    let mut kept: collections::BTreeSet<i64> = collections::BTreeSet::new();
    kept.extend(head.facts.iter().cloned());
    let mut out: Vec<i64> = vec![];
    for fact in entry.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if kept.contains(&fact) { continue; }
        let mut reads_bound = false;
        for name in bound.iter() { if bounding_touches(&walk, fact, name) { reads_bound = true; } }
        if reads_bound { continue; }
        match walk.arena.at(fact) {
            logic::SolverTerm::Eq(a, b) => {
                out.push(walk.arena.le(a, b));
                out.push(walk.arena.ge(a, b));
                for restated in bounding_restated(walk, entry, changed, a, b) { if !out.contains(&restated) { out.push(restated); } }
            },
            _ => { out.push(fact); },
        }
    }
    let body = match stmt {
        Stmt::For { body, .. } => body,
        Stmt::While { body, .. } => body,
        _ => return out,
    };
    for (flag, held) in walk.flagged.iter() {
        if !bounding_changes_name(changed, flag) { continue; }
        let n = walk.arena.var(flag);
        let zero = walk.arena.int(0);
        let down = walk.arena.le(n, zero);
        for fact in held.iter() {
            let fact = nikaia_std::num::value(fact);
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            walk.arena.variables(fact, &mut read);
            let mut reads_changed = false;
            for name in read.iter() { if bounding_changes_name(changed, name) { reads_changed = true; } }
            let mut reads_bound = false;
            for name in bound.iter() { if bounding_touches(&walk, fact, name) { reads_bound = true; } }
            if reads_changed && !reads_bound {
                let guess = walk.arena.or(vec![down, fact]);
                if !out.contains(&guess) { out.push(guess); }
            }
        }
    }
    let mut remainders: Vec<(String, i64)> = vec![]; #[allow(unused_mut, clippy::redundant_locals)] let mut bound = bound;
    bounding_remainders_set(walk, body, entry, changed, context, program, words, &mut remainders);
    for (name, most) in remainders.iter() {
        let most = nikaia_std::num::value(most);
        if nikaia_std::list::contains(&bound, &name) { continue; }
        let n = walk.arena.var(name);
        let zero = walk.arena.int(0);
        let top = walk.arena.int(most);
        for guess in [walk.arena.ge(n, zero), walk.arena.le(n, top)] { if !out.contains(&guess) { out.push(guess); } }
    }
    for each in body.stmts.iter() {
        let guard = match bounding_break_guard(&each.node) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let denied = match bounding_denial(walk, &guard, entry, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let mut reads_bound = false;
        for name in bound.iter() { if bounding_touches(&walk, denied, name) { reads_bound = true; } }
        if !reads_bound {
            walk.leaving.insert(denied);
            out.push(denied);
        }
    }
    out
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_remainders_set(walk: &mut BoundsWalk, block: &Block, entry: &BoundsFacts, changed: &BoundsChanged, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, out: &mut Vec<(String, i64)>) {
    for each in block.stmts.iter() {
        match &each.node {
            Stmt::Assign { target, op, value } => {
                let place = match path_of(target, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
                if place.contains('.') || !entry.ints.contains(&place) || !bounding_changes_name(changed, &place) { continue; }
                let mut divisor: Option<Expr> = None;
                if bounding_is_op((op).as_ref(), &BinaryOp::Rem) { divisor = Some(value.clone()); } else if op.is_none() {
                    match value {
                        Expr::Binary { op, rhs, .. } => {
                            let rhs = nikaia_std::boxed::open(rhs);
                            if *op == BinaryOp::Rem { divisor = Some(rhs.clone()); }
                        },
                        _ => { },
                    }
                }
                let d = match divisor { Some(__nikaia_value) => __nikaia_value, None => continue };
                let term = match bounding_lin(walk, &d, entry, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
                let m = match walk.arena.constant(term) { Some(__nikaia_value) => __nikaia_value, None => continue };
                if m >= 1 { out.push((nikaia_std::block::Text::from(place.to_string()), unsafe { nikaia_std::proven::sub::<i64>(m, 1) })); }
            },
            Stmt::Expr(expr) => { match expr {
                Expr::If { then_branch, else_branch, .. } => {
                    bounding_remainders_set(walk, then_branch, entry, changed, context, program, words, out);
                    let other = match else_branch { Some(__nikaia_value) => __nikaia_value, None => continue };
                    bounding_remainders_set(walk, other, entry, changed, context, program, words, out);
                },
                _ => { },
            }; },
            _ => { },
        }
    }
}

pub(crate) fn bounding_restated(walk: &mut BoundsWalk, entry: &BoundsFacts, changed: &BoundsChanged, a: i64, b: i64) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    let (counter, start) = match walk.arena.at(a) {
        logic::SolverTerm::Var(ref x) => {
            match walk.arena.at(b) {
                logic::SolverTerm::Var(ref v) => (nikaia_std::block::Text::from(x.to_string()), nikaia_std::block::Text::from(v.to_string())),
                _ => return out,
            }
        },
        _ => return out,
    };
    let mut moving = false;
    let mut still = true;
    for name in changed.values.iter() {
        if *name == counter { moving = true; }
        if path_within(&start, name) { still = false; }
    }
    if !moving || !still { return out; }
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    given.insert(nikaia_std::block::Text::from(start.to_string()), a);
    for fact in entry.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if !walk.arena.mentions(fact, &start) || walk.arena.mentions(fact, &counter) { continue; }
        let mut touched = false;
        for name in changed.values.iter() { if bounding_touches(&walk, fact, name) { touched = true; } }
        if !touched { out.push(walk.arena.substitute(fact, &given)); }
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct BoundsProposals {
    pub(crate) ghosts: Vec<i64>,
    pub(crate) fixed: Vec<i64>,
    pub(crate) candidates: Vec<(i64, String)>,
}

pub(crate) fn bounding_loop_proposals(walk: &mut BoundsWalk, stmt: &Stmt, start: i64, entry: &BoundsFacts, changed: &BoundsChanged, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> BoundsProposals {
    match stmt {
        Stmt::While { cond, body } => bounding_while_proposals(walk, start, cond, body, entry, changed, words, &mut *ask),
        _ => BoundsProposals { ghosts: vec![], fixed: vec![], candidates: vec![] },
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_while_proposals(walk: &mut BoundsWalk, start: i64, cond: &Expr, body: &Block, entry: &BoundsFacts, changed: &BoundsChanged, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> BoundsProposals {
    let mut out = BoundsProposals { ghosts: vec![], fixed: vec![], candidates: vec![] };
    #[allow(unused_mut)] let mut state: Vec<String> = vec![];
    let mut ints = entry.ints.copy_owned(); #[allow(unused_mut, clippy::redundant_locals)] let mut state = state;
    for name in changed.values.iter() { if entry.ints.contains(name) && !walk.pinned.contains(&path_root(name)) { state.push(nikaia_std::block::Text::from(name.to_string())); } }
    let none: collections::BTreeSet<String> = collections::BTreeSet::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut state = state;
    for fact in entry.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(fact, &mut read);
        for name in read.iter() { if name.ends_with(".len()") { ints.insert(nikaia_std::block::Text::from(name.to_string())); } }
    }
    for name in changed.values.iter() {
        if !entry.ints.contains(name) && walk.flagged.contains_key(name) && !name.contains('.') && !walk.pinned.contains(name) && !walk.shape.constants.contains_key(name) {
            state.push(nikaia_std::block::Text::from(name.to_string()));
            ints.insert(nikaia_std::block::Text::from(name.to_string()));
        }
    }
    for list in changed.lengths.iter() {
        let length = length_of(list);
        if !list.contains('.') && !list.contains('#') && !list.contains('[') && !list.contains('(') && !walk.pinned.contains(list) && !nikaia_std::list::contains(&state, &length) && prover_length_follows(&length, cond, body, &none, words) {
            state.push(nikaia_std::block::Text::from(length.to_string()));
            ints.insert(length);
        }
    }
    if state.is_empty() { return out; }
    let constants = walk.shape.constants.copy_owned(); #[allow(unused_mut, clippy::redundant_locals)] let mut state = state;
    let claims: collections::BTreeSet<(i64, i64)> = collections::BTreeSet::new();
    let record = match loop_record(&mut walk.arena, start, &state, &entry.facts, &ints, &mut |name| { (*nikaia_std::index::get(&constants, name)).copied() }, cond, body, words, &claims, &mut |e| { bounding_no_throw(e) }, &mut |e| { bounding_no_holes(e) }) { Some(__nikaia_value) => __nikaia_value, None => return out };
    for name in state.iter() {
        let here = walk.arena.var(name);
        let before = walk.arena.var(&loop_before_name(name, start));
        out.ghosts.push(walk.arena.equal(here, before));
    }
    for k in 0..entry.facts.len() as i64 {
        let mut moved = false;
        for name in state.iter() { if walk.arena.mentions(*unsafe { nikaia_std::proven::read(&entry.facts, (k) as usize) }, name) { moved = true; } }
        if moved && ((k) as usize) < record.problem.fixed.len() { out.fixed.push(*unsafe { nikaia_std::proven::read(&record.problem.fixed, (k) as usize) }); }
    }
    let mut asked: Vec<i64> = vec![];
    for (candidate, origin) in loop_candidates(&mut walk.arena, &record, &mut *ask, &mut asked) {
        match walk.arena.at(candidate) {
            logic::SolverTerm::Eq(a, b) => {
                out.candidates.push((walk.arena.le(a, b), nikaia_std::block::Text::from(origin.to_string())));
                out.candidates.push((walk.arena.ge(a, b), nikaia_std::block::Text::from(origin.to_string())));
            },
            _ => { out.candidates.push((candidate, nikaia_std::block::Text::from(origin.to_string()))); },
        }
    }
    out
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn bounding_no_throw(e: &Expr) -> bool { false }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn bounding_no_holes(e: &Expr) -> Vec<Expr> { vec![] }

pub(crate) fn bounding_break_guard(stmt: &Stmt) -> Option<Expr> {
    match stmt {
        Stmt::Expr(expr) => match expr {
            Expr::If { cond, then_branch, else_branch, .. } => {
                let cond = nikaia_std::boxed::open(cond);
                if else_branch.is_some() || then_branch.stmts.len() != 1 { return None; }
                match &unsafe { nikaia_std::proven::read(&then_branch.stmts, (0) as usize) }.node {
                    Stmt::Break => Some(cond.clone()),
                    _ => None,
                }
            },
            _ => None,
        },
        _ => None,
    }
}

pub(crate) fn bounding_loop_changed(stmt: &Stmt, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> BoundsChanged {
    let mut changed = nothing_changed();
    match stmt {
        Stmt::For { body, .. } => { changed = bounding_changed(body, context, words); },
        Stmt::While { cond, body } => {
            changed = bounding_changed(body, context, words);
            bounding_extend(&mut changed, &bounding_changed_in_expr(cond, context, words));
        },
        _ => { },
    }
    changed
}

pub(crate) fn bounding_changes_name(changed: &BoundsChanged, name: &str) -> bool {
    for value in changed.values.iter() { if path_within(name, value) { return true; } }
    for list in changed.lengths.iter() { if name == length_of(list) { return true; } }
    for part in changed.parts.iter() { if path_within(name, part) { return true; } }
    for value in changed.values.iter() { if bounding_in_elements(name, value) { return true; } }
    for place in changed.elements.iter() { if bounding_element_hit(name, place, false) { return true; } }
    false
}

pub(crate) fn bounding_turn_end(walk: &mut BoundsWalk, facts: &BoundsFacts, jump: bool, leaves: bool, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    rules_turn_end(walk, facts, &mut *ask);
    if walk.turns.is_empty() { return; }
    let mut frame = match walk.turns.pop() { Some(__nikaia_value) => __nikaia_value, None => return };
    if jump { frame.jumps.insert(walk.at); }
    for k in 0..frame.guesses.len() as i64 {
        if leaves && walk.leaving.contains(unsafe { nikaia_std::proven::read(&frame.guesses, (k) as usize) }) { continue; }
        if !frame.failed.contains(&k) && !bounding_proves(&walk, facts, *unsafe { nikaia_std::proven::read(&frame.guesses, (k) as usize) }, &mut *ask) {
            frame.failed.insert(k);
            let at = walk.at;
            ({ let __nikaia_arg2 = format!("  turn end: {} not kept\n    facts: {}", walk.arena.text(*unsafe { nikaia_std::proven::read(&frame.guesses, (k) as usize) }), bounding_texts(&walk, &facts.facts)); bounding_turn_row(walk, at, __nikaia_arg2) });
        }
    }
    walk.turns.push(frame);
}

pub(crate) fn bounding_proven_count(proven: &BoundsProven) -> i64 { unsafe { nikaia_std::proven::add::<i64>(nikaia_std::proven::add::<i64>(nikaia_std::proven::add::<i64>(proven.indices.len() as i64, proven.arithmetic.len() as i64), proven.nonnegative.len() as i64), proven.negations.len() as i64) } }

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_while(walk: &mut BoundsWalk, cond: &Expr, body: &Block, changed: &BoundsChanged, cands: &[String], facts: &mut BoundsFacts, invariant: &[i64], context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let outside = bounding_changed_in_expr(cond, context, words).values;
    let mut pairs: Vec<(String, String)> = vec![];
    let steps = bounding_turn_steps(walk, body, &outside, changed, &facts, context, words, &mut &mut *ask, &mut pairs);
    let mut turn_facts: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut step: Vec<(String, i64, i64, Option<i64>)> = vec![];
    let mut others: Vec<(String, i64, i64, Option<i64>)> = vec![];
    let compared = bounding_compared(cond, words);
    let mut counter = String::new();
    for (name, low, high, floor) in steps.iter() {
        let low = nikaia_std::num::value(low);let high = nikaia_std::num::value(high);let floor = *floor;
        if low == 1 && high == 1 && floor.is_none() && (counter.is_empty() || *name == compared) { counter = nikaia_std::block::Text::from(name.to_string()); }
    }
    for (name, low, high, floor) in steps.iter() {
        let low = nikaia_std::num::value(low);let high = nikaia_std::num::value(high);let floor = *floor;
        if step.is_empty() && *name == counter { step.push((nikaia_std::block::Text::from(name.to_string()), low, high, floor)); } else { others.push((nikaia_std::block::Text::from(name.to_string()), low, high, floor)); }
    }
    let mut head_facts: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    if !step.is_empty() {
        let below = bounding_counter_below(walk, cond, &unsafe { nikaia_std::proven::read(&step, (0) as usize) }.0, changed, &facts, context, program, words, &mut &mut *ask);
        if below.is_some() { head_facts.push(nikaia_std::index::or(below, || 0)); }
    }
    let scales = bounding_turn_scales(&walk, body, &outside, changed, &facts, context, words);
    if !scales.is_empty() {
        let multiplies = scales.iter().any(|s| { s.1 > 1 });
        let most = bounding_turns_most(walk, cond, &steps, changed, &facts, !multiplies, context, program, words, &mut &mut *ask);
        for fact in bounding_scaled_bounds(walk, &facts, &scales, most, &mut &mut *ask) { head_facts.push(fact); }
    }
    if !step.is_empty() && !others.is_empty() {
        let t = walk.arena.var(&format!("#turn{}", walk.entries));
        walk.entries += 1;
        let zero = walk.arena.int(0);
        turn_facts.push(walk.arena.ge(t, zero));
        for fact in bounding_turn_bounds(walk, facts, &step, t) { turn_facts.push(fact); }
        for fact in bounding_turn_bounds(walk, facts, &others, t) { turn_facts.push(fact); }
    }
    for fact in bounding_pair_bounds(walk, facts, &pairs, &counter) { turn_facts.push(fact); }
    let kept = rules_loop_entry(walk, &facts, changed, &mut &mut *ask);
    bounding_loop_change(walk, facts, changed, cands);
    rules_loop_give(walk, facts, &kept, changed);
    for fact in invariant.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    for fact in head_facts.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    bounding_expr(walk, cond, facts, context, program, words, &mut &mut *ask);
    let mut inner = facts.clone();
    bounding_assume(walk, &mut inner, cond, context, program, words);
    for fact in turn_facts.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, &mut inner, fact);
    }
    walk.rule_loops.push(kept);
    if !bounding_block(walk, body, &mut inner, context, program, words, &mut &mut *ask) { bounding_turn_end(walk, &inner, false, false, &mut &mut *ask); }
    walk.rule_loops.pop();
    if !breaks(body, words) {
        bounding_assume_not(walk, facts, cond, context, program, words);
        for fact in turn_facts.iter() {
            let fact = nikaia_std::num::value(fact);
            bounding_push(&walk, facts, fact);
        }
    }
}

pub(crate) fn bounding_compared(cond: &Expr, words: &winnow_grammar::InternerContext) -> String {
    match cond {
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if *op == BinaryOp::Lt { return nikaia_std::index::or(path_of(lhs, words), || "".into()); }
            if *op == BinaryOp::And {
                let left = bounding_compared(lhs, words);
                if !left.is_empty() { return left; }
                return bounding_compared(rhs, words);
            }
            return String::from("");
        },
        _ => return String::from(""),
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_counter_below(walk: &mut BoundsWalk, cond: &Expr, x: &str, changed: &BoundsChanged, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<i64> {
    match cond {
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if *op == BinaryOp::And {
                let left = bounding_counter_below(walk, lhs, x, changed, facts, context, program, words, &mut &mut *ask);
                if left.is_some() { return std::convert::identity(left); }
                return bounding_counter_below(walk, rhs, x, changed, facts, context, program, words, &mut &mut *ask);
            }
            if *op != BinaryOp::Lt || nikaia_std::index::or(path_of(lhs, words), || "".into()) != x || !bounding_unchanged_end(rhs, changed, words) { return None; }
            let end = match bounding_lin(walk, rhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let now = walk.arena.var(x);
            let below = walk.arena.le(now, end);
            if !bounding_proves(&walk, facts, below, &mut &mut *ask) { return None; }
            return Some(below);
        },
        _ => return None,
    }
}

pub(crate) fn bounding_unchanged_end(end: &Expr, changed: &BoundsChanged, words: &winnow_grammar::InternerContext) -> bool {
    let named = path_of(end, words);
    if named.is_some() { return !bounding_changes_name(changed, nikaia_std::index::or(named.as_deref(), || "")); }
    match end {
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); return bounding_unchanged_end(expr, changed, words) },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() || words.resolve(method) != "len" { return false; }
            let list = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
            return !bounding_changes_name(changed, &length_of(&list));
        },
        _ => return false,
    }
}

pub(crate) fn bounding_candidates(walk: &BoundsWalk, changed: &BoundsChanged, facts: &BoundsFacts) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for x in changed.values.iter() {
        if changed.jumps.contains(x) && changed.drops.contains(x) || walk.pinned.contains(&path_root(x)) { continue; }
        if !facts.ints.contains(x) && !x.contains('.') { continue; }
        let mut inside = false;
        for v in changed.values.iter() { if v != x && path_within(x, v) { inside = true; } }
        for v in changed.parts.iter() { if path_within(x, v) { inside = true; } }
        if !inside { out.push(nikaia_std::block::Text::from(x.to_string())); }
    }
    out
}

pub(crate) fn bounding_grow(walk: &mut BoundsWalk, cands: &[String], falls: &[String]) -> Vec<String> {
    let mut added: Vec<String> = vec![];
    added.reserve(cands.iter().size_hint().0); for c in cands.iter() {
        if walk.growing.contains(c) || walk.falling.contains(c) { continue; }
        if nikaia_std::list::contains(&falls, &c) {
            walk.falling.insert(nikaia_std::block::Text::from(c.to_string()));
            walk.fall_failed.remove(c);
        } else {
            walk.growing.insert(nikaia_std::block::Text::from(c.to_string()));
            walk.grow_failed.remove(c);
        }
        added.push(nikaia_std::block::Text::from(c.to_string()));
    }
    added
}

pub(crate) fn bounding_grew(walk: &mut BoundsWalk, cands: &[String], added: &[String]) -> Vec<String> {
    let mut failed: Vec<String> = vec![];
    for c in cands.iter() { if walk.falling.contains(c) { if walk.fall_failed.contains(c) { failed.push(nikaia_std::block::Text::from(c.to_string())); } } else if walk.grow_failed.contains(c) { failed.push(nikaia_std::block::Text::from(c.to_string())); } }
    for c in added.iter() {
        walk.growing.remove(c);
        walk.falling.remove(c);
    }
    failed
}

pub(crate) fn bounding_without(cands: &[String], failed: &[String]) -> Vec<String> {
    let mut kept: Vec<String> = vec![];
    for c in cands.iter() { if !nikaia_std::list::contains(&failed, &c) { kept.push(nikaia_std::block::Text::from(c.to_string())); } }
    kept
}

pub(crate) fn bounding_falls(changed: &BoundsChanged, cands: &[String]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for c in cands.iter() { if changed.jumps.contains(c) { out.push(nikaia_std::block::Text::from(c.to_string())); } }
    out
}

pub(crate) fn bounding_loop_change(walk: &mut BoundsWalk, facts: &mut BoundsFacts, changed: &BoundsChanged, cands: &[String]) {
    let mut entries: Vec<(String, String)> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    entries.reserve(cands.iter().size_hint().0); for x in cands.iter() {
        let entry = format!("{}#{}", x, walk.entries);
        walk.entries += 1;
        let e = walk.arena.var(&entry);
        let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        given.insert(nikaia_std::block::Text::from(x.to_string()), e);
        for fact in facts.facts.iter_mut() { if walk.arena.mentions(*fact, x) { *fact = walk.arena.substitute(*fact, &given); } }
        entries.push((nikaia_std::block::Text::from(x.to_string()), entry));
    }
    bounding_after_change(walk, facts, changed);
    for (x, entry) in entries.iter() {
        let now = walk.arena.var(x);
        let then = walk.arena.var(entry);
        let fact = if walk.falling.contains(x) { walk.arena.le(now, then) } else { walk.arena.ge(now, then) };
        bounding_push(&walk, facts, fact);
    }
}

pub(crate) fn bounding_steps_up(name: &str, op: Option<&BinaryOp>, value: &Expr, words: &winnow_grammar::InternerContext) -> bool {
    if op.is_some() { return bounding_is_op(std::convert::identity(op), &BinaryOp::Add); }
    match value {
        Expr::Binary { op: added, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); *added == BinaryOp::Add && (nikaia_std::index::or(path_of(lhs, words), || "".into()) == name || nikaia_std::index::or(path_of(rhs, words), || "".into()) == name) },
        Expr::Call { args, .. } => args.iter().any(|arg| { nikaia_std::index::or(path_of(arg, words), || "".into()) == name || bounding_steps_up(name, None, arg, words) }),
        _ => false,
    }
}

pub(crate) fn bounding_steps_down(name: &str, op: Option<&BinaryOp>, value: &Expr, words: &winnow_grammar::InternerContext) -> bool {
    if op.is_some() { return bounding_is_op(std::convert::identity(op), &BinaryOp::Sub); }
    match value {
        Expr::Binary { op: taken, lhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); *taken == BinaryOp::Sub && nikaia_std::index::or(path_of(lhs, words), || "".into()) == name },
        Expr::Variable(other, _) => { let other = *other; words.resolve(other) != name },
        _ => false,
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct BoundsSteps {
    pub(crate) names: Vec<String>,
    pub(crate) low: Vec<i64>,
    pub(crate) high: Vec<i64>,
    pub(crate) gap_low: Vec<i64>,
    pub(crate) gap_high: Vec<i64>,
    pub(crate) live: bool,
}

pub(crate) fn bounding_steps_add(state: &mut BoundsSteps, k: i64, by: i64) {
    state.low[nikaia_std::index::at(k)] += by;
    state.high[nikaia_std::index::at(k)] += by;
    let n = state.names.len() as i64;
    for j in 0..n {
        if j != k {
            state.gap_low[nikaia_std::index::at(k * n + j)] += by;
            state.gap_high[nikaia_std::index::at(k * n + j)] += by;
            state.gap_low[nikaia_std::index::at(j * n + k)] -= by;
            state.gap_high[nikaia_std::index::at(j * n + k)] -= by;
        }
    }
}

pub(crate) fn bounding_steps_join(a: &mut BoundsSteps, b: &BoundsSteps) {
    if !b.live { return; }
    if !a.live {
        a.low = b.low.copy_owned();
        a.high = b.high.copy_owned();
        a.gap_low = b.gap_low.copy_owned();
        a.gap_high = b.gap_high.copy_owned();
        a.live = true;
        return;
    }
    for k in 0..a.names.len() as i64 {
        if *nikaia_std::index::get(&b.low, (k) as usize) < *nikaia_std::index::get(&a.low, (k) as usize) { { let __nikaia_stored = *unsafe { nikaia_std::proven::read(&b.low, (k) as usize) }; unsafe { nikaia_std::proven::write(&mut a.low, (k) as usize, __nikaia_stored) }; } }
        if *nikaia_std::index::get(&b.high, (k) as usize) > *nikaia_std::index::get(&a.high, (k) as usize) { { let __nikaia_stored = *unsafe { nikaia_std::proven::read(&b.high, (k) as usize) }; unsafe { nikaia_std::proven::write(&mut a.high, (k) as usize, __nikaia_stored) }; } }
    }
    for k in 0..a.gap_low.len() as i64 {
        if *nikaia_std::index::get(&b.gap_low, (k) as usize) < *unsafe { nikaia_std::proven::read(&a.gap_low, (k) as usize) } { { let __nikaia_stored = *unsafe { nikaia_std::proven::read(&b.gap_low, (k) as usize) }; unsafe { nikaia_std::proven::write(&mut a.gap_low, (k) as usize, __nikaia_stored) }; } }
        if *nikaia_std::index::get(&b.gap_high, (k) as usize) > *nikaia_std::index::get(&a.gap_high, (k) as usize) { { let __nikaia_stored = *unsafe { nikaia_std::proven::read(&b.gap_high, (k) as usize) }; unsafe { nikaia_std::proven::write(&mut a.gap_high, (k) as usize, __nikaia_stored) }; } }
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_turn_steps(walk: &mut BoundsWalk, body: &Block, outside: &collections::BTreeSet<String>, changed: &BoundsChanged, facts: &BoundsFacts, context: &BoundsContext, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool, pairs: &mut Vec<(String, String)>) -> Vec<(String, i64, i64, Option<i64>)> {
    let mut start = BoundsSteps { names: vec![], low: vec![], high: vec![], gap_low: vec![], gap_high: vec![], live: true };
    for x in changed.values.iter() {
        if walk.pinned.contains(&path_root(x)) || outside.contains(x) || !facts.ints.contains(x) { continue; }
        let mut inside = false;
        for v in changed.values.iter() { if v != x && path_within(x, v) { inside = true; } }
        for v in changed.parts.iter() { if path_within(x, v) { inside = true; } }
        for place in changed.elements.iter() { if bounding_element_hit(x, place, false) { inside = true; } }
        if !inside {
            start.names.push(nikaia_std::block::Text::from(x.to_string()));
            start.low.push(0);
            start.high.push(0);
        }
    }
    for list in changed.lengths.iter() {
        let x = length_of(list);
        if walk.pinned.contains(&path_root(list)) || changed.falls.contains(list) || outside.contains(list) { continue; }
        let mut inside = false;
        for v in changed.values.iter() { if path_within(list, v) { inside = true; } }
        for v in changed.parts.iter() { if v != list && path_within(list, v) { inside = true; } }
        for place in changed.elements.iter() { if bounding_element_hit(list, place, false) { inside = true; } }
        if !inside {
            start.names.push(x);
            start.low.push(0);
            start.high.push(0);
        }
    }
    if start.names.is_empty() { return vec![]; }
    for _ in 0..start.names.len() as i64 * start.names.len() as i64 {
        start.gap_low.push(0);
        start.gap_high.push(0);
    }
    #[allow(unused_mut)] let mut ends = BoundsSteps { names: start.names.copy_owned(), low: start.low.copy_owned(), high: start.high.copy_owned(), gap_low: start.gap_low.copy_owned(), gap_high: start.gap_high.copy_owned(), live: false };
    let mut bad: collections::BTreeSet<String> = collections::BTreeSet::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut ends = ends;
    let mut resets: collections::BTreeMap<String, (i64, i64)> = collections::BTreeMap::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut ends = ends;
    bounding_steps_block(body, &mut start, &mut ends, &mut bad, &mut resets, context, words);
    bounding_steps_join(&mut ends, &start);
    let mut out: Vec<(String, i64, i64, Option<i64>)> = vec![]; #[allow(unused_mut, clippy::redundant_locals)] let mut ends = ends;
    if !ends.live { return out; }
    for k in 0..ends.names.len() as i64 {
        let name = nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&ends.names, (k) as usize) }).to_string());
        if bad.contains(&name) || *nikaia_std::index::get(&ends.low, (k) as usize) < 0 && *nikaia_std::index::get(&ends.high, (k) as usize) > 0 || *nikaia_std::index::get(&ends.low, (k) as usize) == 0 && *nikaia_std::index::get(&ends.high, (k) as usize) == 0 { continue; }
        if !resets.contains_key(&name) {
            out.push((name, *nikaia_std::index::get(&ends.low, (k) as usize), *nikaia_std::index::get(&ends.high, (k) as usize), None));
            continue;
        }
        let (least, most) = nikaia_std::index::or(resets.get(&name), || (0, 0));
        if *nikaia_std::index::get(&ends.low, (k) as usize) < 0 || *nikaia_std::index::get(&ends.high, (k) as usize) <= 0 { continue; }
        let now = walk.arena.var(&name);
        let top = walk.arena.int(most);
        let under = walk.arena.le(top, now);
        if bounding_proves(&walk, facts, under, &mut *ask) { out.push((name, 0, *nikaia_std::index::get(&ends.high, (k) as usize), Some(least))); }
    }
    let n = ends.names.len() as i64;
    for a in 0..n { for b in 0..n { if a != b && *nikaia_std::index::get(&ends.gap_high, nikaia_std::index::at(a * n + b)) <= 0 && bounding_steps_rising(&out, unsafe { nikaia_std::proven::read(&ends.names, (a) as usize) }) && bounding_steps_rising(&out, unsafe { nikaia_std::proven::read(&ends.names, (b) as usize) }) { pairs.push((nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&ends.names, (a) as usize) }).to_string()), nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&ends.names, (b) as usize) }).to_string()))); } } }
    out
}

pub(crate) fn bounding_steps_rising(steps: &[(String, i64, i64, Option<i64>)], name: &str) -> bool {
    for (each, low, high, floor) in steps.iter() {
        let low = nikaia_std::num::value(low);let high = nikaia_std::num::value(high);let floor = *floor;
        if each == name { return floor.is_none() && low >= 0 && high > 0; }
    }
    false
}

pub(crate) fn bounding_steps_block(block: &Block, state: &mut BoundsSteps, ends: &mut BoundsSteps, bad: &mut collections::BTreeSet<String>, resets: &mut collections::BTreeMap<String, (i64, i64)>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    for each in block.stmts.iter() {
        if !state.live { return; }
        match &each.node {
            Stmt::Let { names, .. } => {
                bounding_steps_other(each, state, ends, bad, context, words);
                for name in names.iter() {
                    let name = *name;
                    bad.insert(nikaia_std::block::Text::from(words.resolve(name).to_string()));
                }
            },
            Stmt::Comptime { name, .. } => {
                let name = *name;
                bounding_steps_other(each, state, ends, bad, context, words);
                bad.insert(nikaia_std::block::Text::from(words.resolve(name).to_string()));
            },
            Stmt::Assign { target, op, value } => {
                let place = nikaia_std::index::or(path_of(target, words), || "".into());
                let by = bounding_step_by(&place, (op).as_ref(), value, words);
                let mut k: i64 = 0;
                while k < state.names.len() as i64 && *unsafe { nikaia_std::proven::read(&state.names, (k) as usize) } != place { k = unsafe { nikaia_std::proven::add::<i64>(k, 1) }; }
                let back = bounding_step_literal(value);
                if by.is_some() && k < state.names.len() as i64 { bounding_steps_add(state, k, nikaia_std::index::or(by, || 0)); } else if op.is_none() && back.is_some() && k < state.names.len() as i64 {
                    let c = nikaia_std::index::or(back, || 0);
                    { let __nikaia_stored = 0; nikaia_std::index::set(&mut state.low, nikaia_std::index::at(k), __nikaia_stored); }
                    { let __nikaia_stored = 0; nikaia_std::index::set(&mut state.high, nikaia_std::index::at(k), __nikaia_stored); }
                    let (least, most) = nikaia_std::index::or(resets.get(&place), || (c, c));
                    resets.insert(nikaia_std::block::Text::from(place.to_string()), (least.min(c), most.max(c)));
                } else { bounding_steps_other(each, state, ends, bad, context, words); }
            },
            Stmt::Return(value) => {
                bounding_steps_other(each, state, ends, bad, context, words);
                state.live = false;
            },
            Stmt::Break => { state.live = false; },
            Stmt::Continue => {
                bounding_steps_join(ends, &state);
                state.live = false;
            },
            Stmt::Expr(expr) => { match expr {
                Expr::If { cond, then_branch, else_branch, .. } => {
                    let cond = nikaia_std::boxed::open(cond);
                    bounding_steps_cond(each, cond, then_branch, (else_branch).as_ref(), state, ends, bad, context, words);
                    let mut other = BoundsSteps { names: state.names.copy_owned(), low: state.low.copy_owned(), high: state.high.copy_owned(), gap_low: state.gap_low.copy_owned(), gap_high: state.gap_high.copy_owned(), live: state.live };
                    bounding_steps_block(then_branch, state, ends, bad, resets, context, words);
                    bounding_steps_maybe((else_branch).as_ref(), &mut other, ends, bad, resets, context, words);
                    bounding_steps_join(state, &other);
                },
                Expr::MethodCall { receiver, method, args, .. } => {
                    let receiver = nikaia_std::boxed::open(receiver); let method = *method;
                    if !bounding_steps_push(each, receiver, method, args, state, bad, context, words) { bounding_steps_other(each, state, ends, bad, context, words); }
                },
                _ => { bounding_steps_other(each, state, ends, bad, context, words); },
            }; },
            _ => { bounding_steps_other(each, state, ends, bad, context, words); },
        }
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_steps_push(each: &Spanned<Stmt>, receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], state: &mut BoundsSteps, bad: &mut collections::BTreeSet<String>, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> bool {
    if words.resolve(method) != "push" || args.len() != 1 { return false; }
    let list = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let x = length_of(&list);
    let mut k: i64 = 0;
    while k < state.names.len() as i64 && *unsafe { nikaia_std::proven::read(&state.names, (k) as usize) } != x { k = unsafe { nikaia_std::proven::add::<i64>(k, 1) }; }
    let one = Block { stmts: vec![each.clone()] };
    if k >= state.names.len() as i64 || turn_jumps(&one, words) > 0 { return false; }
    let changed = bounding_changed_in_expr(unsafe { nikaia_std::proven::read(&args, (0) as usize) }, context, words);
    for name in state.names.iter() { if bounding_changes_name(&changed, name) { bad.insert(nikaia_std::block::Text::from(name.to_string())); } }
    for name in assigned_in_expr(unsafe { nikaia_std::proven::read(&args, (0) as usize) }, words) { bad.insert(nikaia_std::block::Text::from(name.to_string())); }
    bounding_steps_add(state, k, 1);
    true
}

pub(crate) fn bounding_steps_maybe(block: Option<&Block>, state: &mut BoundsSteps, ends: &mut BoundsSteps, bad: &mut collections::BTreeSet<String>, resets: &mut collections::BTreeMap<String, (i64, i64)>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_steps_block(present, state, ends, bad, resets, context, words);
}

pub(crate) fn bounding_maybe_jumps(block: Option<&Block>, words: &winnow_grammar::InternerContext) -> i64 {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return 0 };
    turn_jumps(present, words)
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_steps_cond(each: &Spanned<Stmt>, cond: &Expr, then_branch: &Block, else_branch: Option<&Block>, state: &mut BoundsSteps, ends: &mut BoundsSteps, bad: &mut collections::BTreeSet<String>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let changed = bounding_changed_in_expr(cond, context, words);
    for name in state.names.iter() { if bounding_changes_name(&changed, name) { bad.insert(nikaia_std::block::Text::from(name.to_string())); } }
    for name in assigned_in_expr(cond, words) { bad.insert(nikaia_std::block::Text::from(name.to_string())); }
    let one = Block { stmts: vec![each.clone()] };
    if turn_jumps(&one, words) > turn_jumps(then_branch, words) + bounding_maybe_jumps(else_branch, words) { bounding_steps_join(ends, &state); }
}

pub(crate) fn bounding_steps_other(each: &Spanned<Stmt>, state: &mut BoundsSteps, ends: &mut BoundsSteps, bad: &mut collections::BTreeSet<String>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let one = Block { stmts: vec![each.clone()] };
    let changed = bounding_changed(&one, context, words);
    for name in state.names.iter() { if bounding_changes_name(&changed, name) { bad.insert(nikaia_std::block::Text::from(name.to_string())); } }
    for name in assigned_in_statement(&each.node, words) { bad.insert(nikaia_std::block::Text::from(name.to_string())); }
    if turn_jumps(&one, words) > 0 { bounding_steps_join(ends, &state); }
}

pub(crate) fn bounding_step_by(name: &str, op: Option<&BinaryOp>, value: &Expr, words: &winnow_grammar::InternerContext) -> Option<i64> {
    if name == "" { return None; }
    if op.is_some() {
        let by = match bounding_step_literal(value) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if bounding_is_op(std::convert::identity(op), &BinaryOp::Add) { return Some(by); }
        if bounding_is_op(std::convert::identity(op), &BinaryOp::Sub) { return Some(0 - by); }
        return None;
    }
    match value {
        Expr::Binary { op: added, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let left = nikaia_std::index::or(path_of(lhs, words), || "".into()) == name;
            let right = nikaia_std::index::or(path_of(rhs, words), || "".into()) == name;
            if *added == BinaryOp::Add && left { return bounding_step_literal(rhs); }
            if *added == BinaryOp::Add && right { return bounding_step_literal(lhs); }
            if *added == BinaryOp::Sub && left {
                let by = match bounding_step_literal(rhs) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return Some(0 - by);
            }
            None
        },
        _ => None,
    }
}

pub(crate) fn bounding_step_literal(expr: &Expr) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative, .. } => {
            let negative = *negative; let value = *value;
            if value > 1048576u64 { return None; }
            if negative { return Some(0 - i64::try_from(value).unwrap_or_else(|_| panic!("the value does not fit in an `i64`"))); }
            Some(i64::try_from(value).unwrap_or_else(|_| panic!("the value does not fit in an `i64`")))
        },
        _ => None,
    }
}

pub(crate) fn bounding_turn_bounds(walk: &mut BoundsWalk, facts: &mut BoundsFacts, steps: &[(String, i64, i64, Option<i64>)], turns: i64) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    out.reserve(steps.iter().size_hint().0); for (name, low, high, floor) in steps.iter() {
        let low = nikaia_std::num::value(low);let high = nikaia_std::num::value(high);let floor = *floor;
        let e = bounding_entry_value(walk, facts, name);
        let now = walk.arena.var(name);
        let moved = walk.arena.sub(now, e);
        let least = walk.arena.int(low);
        let most = walk.arena.int(high);
        let ceiling = walk.arena.mul(most, turns);
        if floor.is_some() {
            let back = walk.arena.int(nikaia_std::index::or(floor, || 0));
            out.push(walk.arena.ge(now, back));
        } else {
            let lowest = walk.arena.mul(least, turns);
            out.push(walk.arena.ge(moved, lowest));
        }
        out.push(walk.arena.le(moved, ceiling));
    }
    out
}

pub(crate) fn bounding_entry_value(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str) -> i64 {
    let entry = if name.ends_with(".len()") { format!("#{}:{}", walk.entries, name) } else { format!("{}#{}", name, walk.entries) };
    walk.entries += 1;
    let e = walk.arena.var(&entry);
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    given.insert(nikaia_std::block::Text::from(name.to_string()), e);
    let mut copies: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if walk.arena.mentions(fact, name) { copies.push(walk.arena.substitute(fact, &given)); }
    }
    for copy in copies.iter() {
        let copy = nikaia_std::num::value(copy);
        bounding_push(&walk, facts, copy);
    }
    e
}

pub(crate) fn bounding_pair_bounds(walk: &mut BoundsWalk, facts: &mut BoundsFacts, pairs: &[(String, String)], skip: &str) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    let mut entered: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    out.reserve(pairs.iter().size_hint().0); for (n, m) in pairs.iter() {
        if out.len() >= 8 || n == skip || m == skip { continue; }
        if !entered.contains_key(n) {
            let e = bounding_entry_value(walk, facts, n);
            entered.insert(nikaia_std::block::Text::from(n.to_string()), e);
        }
        if !entered.contains_key(m) {
            let e = bounding_entry_value(walk, facts, m);
            entered.insert(nikaia_std::block::Text::from(m.to_string()), e);
        }
        let n_then = match entered.get(n) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
        let m_then = match entered.get(m) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
        let n_now = walk.arena.var(n);
        let m_now = walk.arena.var(m);
        let n_moved = walk.arena.sub(n_now, n_then);
        let m_moved = walk.arena.sub(m_now, m_then);
        out.push(walk.arena.le(n_moved, m_moved));
    }
    out
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_turns_most(walk: &mut BoundsWalk, cond: &Expr, steps: &[(String, i64, i64, Option<i64>)], changed: &BoundsChanged, facts: &BoundsFacts, constant_only: bool, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<i64> {
    match cond {
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if *op == BinaryOp::And {
                let left = bounding_turns_most(walk, lhs, steps, changed, facts, constant_only, context, program, words, &mut &mut *ask);
                let right = bounding_turns_most(walk, rhs, steps, changed, facts, constant_only, context, program, words, &mut &mut *ask);
                if left.is_none() { return right; }
                if right.is_none() { return std::convert::identity(left); }
                return Some(nikaia_std::index::or(left, || 0).min(nikaia_std::index::or(right, || 0)));
            }
            let x = match path_of(lhs, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let rising = *op == BinaryOp::Lt || *op == BinaryOp::Le;
            let falling = *op == BinaryOp::Gt || *op == BinaryOp::Ge;
            let mut by: i64 = 0;
            for (name, low, high, floor) in steps.iter() {
                let low = nikaia_std::num::value(low);let high = nikaia_std::num::value(high);let floor = *floor;
                if *name == x && floor.is_none() {
                    if rising && low >= 1 { by = low; }
                    if falling && high <= -1 { by = 0 - high; }
                }
            }
            if by == 0 { return None; }
            let end = match bounding_lin(walk, rhs, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if constant_only && walk.arena.constant(end).is_none() || !bounding_stable(&walk, end, changed, &x) { return None; }
            let now = walk.arena.var(&x);
            let mut gap = if rising { walk.arena.sub(end, now) } else { walk.arena.sub(now, end) };
            if *op == BinaryOp::Le || *op == BinaryOp::Ge {
                let one = walk.arena.int(1);
                gap = walk.arena.add(gap, one);
            }
            let most = match bounding_term(walk, gap, facts, &mut &mut *ask).hi { Some(__nikaia_value) => __nikaia_value, None => return None };
            if most <= 0 { return Some(0); }
            return Some((unsafe { nikaia_std::proven::sub::<i64>(most + by, 1) }) / by);
        },
        _ => return None,
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_for_turns_most(walk: &mut BoundsWalk, low: Option<i64>, high: Option<i64>, closed: bool, changed: &BoundsChanged, name: &str, facts: &BoundsFacts, constant_only: bool, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<i64> {
    let l = match low { Some(__nikaia_value) => __nikaia_value, None => return None };
    let h = match high { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !bounding_stable(&walk, l, changed, name) || !bounding_stable(&walk, h, changed, name) { return None; }
    let mut span = walk.arena.sub(h, l);
    if closed {
        let one = walk.arena.int(1);
        span = walk.arena.add(span, one);
    }
    if constant_only && walk.arena.constant(span).is_none() { return None; }
    let most = match bounding_term(walk, span, facts, &mut *ask).hi { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(most.max(0))
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct BoundsScales {
    pub(crate) names: Vec<String>,
    pub(crate) a: Vec<i64>,
    pub(crate) b: Vec<i64>,
}

pub(crate) fn bounding_turn_scales(walk: &BoundsWalk, body: &Block, outside: &collections::BTreeSet<String>, changed: &BoundsChanged, facts: &BoundsFacts, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Vec<(String, i64, i64)> {
    #[allow(unused_mut)] let mut state = BoundsScales { names: vec![], a: vec![], b: vec![] };
    for x in changed.values.iter() {
        if walk.pinned.contains(&path_root(x)) || outside.contains(x) || !facts.ints.contains(x) || x.contains('.') { continue; }
        state.names.push(nikaia_std::block::Text::from(x.to_string()));
        state.a.push(1);
        state.b.push(0);
    }
    if state.names.is_empty() { return vec![]; }
    let mut bad: collections::BTreeSet<String> = collections::BTreeSet::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut state = state;
    bounding_scales_block(body, &mut state, &mut bad, context, words);
    let mut out: Vec<(String, i64, i64)> = vec![]; #[allow(unused_mut, clippy::redundant_locals)] let mut state = state;
    for k in 0..state.names.len() as i64 { if !bad.contains(unsafe { nikaia_std::proven::read(&state.names, (k) as usize) }) && (*unsafe { nikaia_std::proven::read(&state.a, (k) as usize) } > 1 || *unsafe { nikaia_std::proven::read(&state.b, (k) as usize) } > 0) { out.push((nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&state.names, (k) as usize) }).to_string()), *unsafe { nikaia_std::proven::read(&state.a, (k) as usize) }, *unsafe { nikaia_std::proven::read(&state.b, (k) as usize) })); } }
    out
}

pub(crate) fn bounding_scales_block(block: &Block, state: &mut BoundsScales, bad: &mut collections::BTreeSet<String>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    for each in block.stmts.iter() {
        match &each.node {
            Stmt::Let { names, .. } => {
                bounding_scales_other(each, &state, bad, context, words);
                for name in names.iter() {
                    let name = *name;
                    bad.insert(nikaia_std::block::Text::from(words.resolve(name).to_string()));
                }
            },
            Stmt::Comptime { name, .. } => {
                let name = *name;
                bounding_scales_other(each, &state, bad, context, words);
                bad.insert(nikaia_std::block::Text::from(words.resolve(name).to_string()));
            },
            Stmt::Assign { target, op, value } => {
                let place = nikaia_std::index::or(path_of(target, words), || "".into());
                let mut k: i64 = 0;
                while ((k) as usize) < state.names.len() && *unsafe { nikaia_std::proven::read(&state.names, (k) as usize) } != place { k = unsafe { nikaia_std::proven::add::<i64>(k, 1) }; }
                let map = bounding_scale_by(&place, (op).as_ref(), value, words);
                if ((k) as usize) < state.names.len() && map.is_some() {
                    let (a, b) = nikaia_std::index::or(map, || (1, 0));
                    if *nikaia_std::index::get(&state.a, (k) as usize) > 1048576 || *nikaia_std::index::get(&state.b, (k) as usize) > 1048576 { bad.insert(nikaia_std::block::Text::from(place.to_string())); } else {
                        { let __nikaia_stored = a * *unsafe { nikaia_std::proven::read(&state.a, (k) as usize) }; unsafe { nikaia_std::proven::write(&mut state.a, (k) as usize, __nikaia_stored) }; }
                        { let __nikaia_stored = a * *nikaia_std::index::get(&state.b, (k) as usize) + b; unsafe { nikaia_std::proven::write(&mut state.b, (k) as usize, __nikaia_stored) }; }
                    }
                } else { bounding_scales_other(each, &state, bad, context, words); }
            },
            Stmt::Expr(expr) => { match expr {
                Expr::If { cond, then_branch, else_branch, .. } => {
                    let cond = nikaia_std::boxed::open(cond);
                    let changed = bounding_changed_in_expr(cond, context, words);
                    for name in state.names.iter() { if bounding_changes_name(&changed, name) { bad.insert(nikaia_std::block::Text::from(name.to_string())); } }
                    for name in assigned_in_expr(cond, words) { bad.insert(nikaia_std::block::Text::from(name.to_string())); }
                    let mut other = BoundsScales { names: state.names.copy_owned(), a: state.a.copy_owned(), b: state.b.copy_owned() };
                    bounding_scales_block(then_branch, state, bad, context, words);
                    if else_branch.is_some() { bounding_scales_maybe(Option::as_ref(else_branch), &mut other, bad, context, words); }
                    for k in 0..state.names.len() as i64 {
                        { let __nikaia_stored = (*nikaia_std::index::get(&state.a, (k) as usize)).max(*unsafe { nikaia_std::proven::read(&other.a, (k) as usize) }); unsafe { nikaia_std::proven::write(&mut state.a, (k) as usize, __nikaia_stored) }; }
                        { let __nikaia_stored = (*nikaia_std::index::get(&state.b, (k) as usize)).max(*unsafe { nikaia_std::proven::read(&other.b, (k) as usize) }); unsafe { nikaia_std::proven::write(&mut state.b, (k) as usize, __nikaia_stored) }; }
                    }
                },
                _ => { bounding_scales_other(each, &state, bad, context, words); },
            }; },
            _ => { bounding_scales_other(each, &state, bad, context, words); },
        }
    }
}

pub(crate) fn bounding_scales_maybe(block: Option<&Block>, state: &mut BoundsScales, bad: &mut collections::BTreeSet<String>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_scales_block(present, state, bad, context, words);
}

pub(crate) fn bounding_scales_other(each: &Spanned<Stmt>, state: &BoundsScales, bad: &mut collections::BTreeSet<String>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let one = Block { stmts: vec![each.clone()] };
    let changed = bounding_changed(&one, context, words);
    for name in state.names.iter() { if bounding_changes_name(&changed, name) { bad.insert(nikaia_std::block::Text::from(name.to_string())); } }
    for name in assigned_in_statement(&each.node, words) { bad.insert(nikaia_std::block::Text::from(name.to_string())); }
}

pub(crate) fn bounding_scale_by(name: &str, op: Option<&BinaryOp>, value: &Expr, words: &winnow_grammar::InternerContext) -> Option<(i64, i64)> {
    if name == "" { return None; }
    let mut map: Option<(i64, i64)> = None;
    if op.is_some() {
        let c = match bounding_step_literal(value) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if bounding_is_op(std::convert::identity(op), &BinaryOp::Add) { map = Some((1, c)); }
        if bounding_is_op(std::convert::identity(op), &BinaryOp::Mul) { map = Some((c, 0)); }
    } else { map = bounding_affine(value, name, words); }
    let (a, b) = match map { Some(__nikaia_value) => __nikaia_value, None => return None };
    if a < 1 || b < 0 { return None; }
    Some((a, b))
}

pub(crate) fn bounding_affine(expr: &Expr, name: &str, words: &winnow_grammar::InternerContext) -> Option<(i64, i64)> {
    if nikaia_std::index::or(path_of(expr, words), || "".into()) == name { return Some((1, 0)); }
    let c = bounding_step_literal(expr);
    if c.is_some() { return Some((0, nikaia_std::index::or(c, || 0))); }
    match expr {
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let (la, lb) = match bounding_affine(lhs, name, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let (ra, rb) = match bounding_affine(rhs, name, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let mut a: i64 = 0;
            let mut b: i64 = 0;
            if *op == BinaryOp::Add {
                a = la + ra;
                b = lb + rb;
            } else if *op == BinaryOp::Sub {
                a = la - ra;
                b = lb - rb;
            } else if *op == BinaryOp::Mul && la == 0 {
                a = lb * ra;
                b = lb * rb;
            } else if *op == BinaryOp::Mul && ra == 0 {
                a = rb * la;
                b = rb * lb;
            } else { return None; }
            if a.abs() > 1048576 || b.abs() > 1048576 { return None; }
            return Some((a, b));
        },
        _ => return None,
    }
}

pub(crate) fn bounding_scaled_bounds(walk: &mut BoundsWalk, facts: &BoundsFacts, scales: &[(String, i64, i64)], turns: Option<i64>, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    out.reserve(scales.iter().size_hint().0); for (name, a, b) in scales.iter() {
        let a = nikaia_std::num::value(a);let b = nikaia_std::num::value(b);
        if a == 1 && turns.is_none() { continue; }
        let now = walk.arena.var(name);
        let range = bounding_term(walk, now, facts, &mut *ask);
        let lo = match range.lo { Some(__nikaia_value) => __nikaia_value, None => continue };
        if lo < 0 { continue; }
        let least = walk.arena.int(lo);
        out.push(walk.arena.ge(now, least));
        let most_turns = match turns { Some(__nikaia_value) => __nikaia_value, None => continue };
        let mut top = match range.hi { Some(__nikaia_value) => __nikaia_value, None => continue };
        let mut fits = top <= solvable();
        if fits && a == 1 { if b > 0 && most_turns > (solvable() - top) / b { fits = false; } else { top += most_turns * b; } } else if fits {
            let mut k: i64 = 0;
            if top == 0 && b == 0 { k = most_turns; }
            while fits && k < most_turns {
                if top > (solvable() - b) / a { fits = false; } else { top = a * top + b; }
                k += 1;
            }
        }
        if fits {
            let most = walk.arena.int(top);
            out.push(walk.arena.le(now, most));
        }
    }
    out
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_let(walk: &mut BoundsWalk, names: &[winnow_grammar::Symbol], ty: Option<&Type>, value: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    bounding_expr(walk, value, facts, context, program, words, &mut &mut *ask);
    let value_lin = bounding_lin(walk, value, &facts, context, program, words);
    bounding_settle(walk, facts);
    let unwrapped = bounding_unwrapped(value);
    let mut value_range: Option<Range> = None;
    if value_lin.is_none() || bounding_reads_own(&walk, nikaia_std::index::or(value_lin, || 0)) {
        let range = nikaia_std::index::or(bounding_range(walk, value, &facts, context, program, words, &mut &mut *ask), || Range::open());
        if range.is_bounded() { value_range = Some(range); }
    }
    let whole_field = match value {
        Expr::Field { .. } => context.whole_fields.contains(&node_key(value)),
        Expr::Call { .. } => context.whole_fields.contains(&node_key(value)),
        Expr::MethodCall { .. } => context.whole_fields.contains(&node_key(value)),
        Expr::Coalesce { .. } => context.whole_fields.contains(&node_key(value)),
        _ => false,
    };
    let whole = nikaia_std::index::or(bounding_declared_whole(ty, words), || (value_lin.is_some() || value_range.is_some() || whole_field || bounding_found_whole(walk, unwrapped, context, words)).into());
    let mut relations: Vec<(bool, i64)> = vec![];
    if names.len() == 1 && value_lin.is_none() { relations = bounding_relations_of(walk, &facts, words.resolve(*unsafe { nikaia_std::proven::read(&names, (0) as usize) }), unwrapped, context, program, words, &mut &mut *ask); }
    let mut measured: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut field_paths: Vec<String> = vec![];
    let mut field_facts: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    if names.len() == 1 {
        let root = words.resolve(*unsafe { nikaia_std::proven::read(&names, (0) as usize) });
        measured = bounding_measured(walk, &facts, root, root, value, context, program, words);
        field_facts = bounding_fields_found(walk, &facts, root, value, &mut field_paths, context, program, words, &mut &mut *ask);
    }
    let mut halves: Option<i64> = None;
    if names.len() == 2 { halves = bounding_halves(walk, names, value, &facts, context, program, words); }
    let mut wide_term: Option<i64> = None;
    if names.len() == 1 {
        wide_term = bounding_narrowed(walk, value, &facts, context, program, words, &mut &mut *ask);
        let named = matches!(value, Expr::Variable(_, _));
        if wide_term.is_none() && !named { wide_term = bounding_wide(walk, value, &facts, context, program, words, &mut &mut *ask); }
    }
    for symbol in names.iter() {
        let symbol = *symbol;
        let name = words.resolve(symbol);
        bounding_forget(&walk, facts, name);
        facts.ints.remove(name);
    }
    if wide_term.is_some() {
        let exact = nikaia_std::index::or(wide_term, || 0);
        let held = words.resolve(*nikaia_std::index::get(&names, 0));
        if !walk.arena.mentions(exact, held) {
            facts.ints.insert(nikaia_std::block::Text::from(held.to_string()));
            let v = walk.arena.var(held);
            let fact = walk.arena.equal(v, exact);
            bounding_push(&walk, facts, fact);
        }
    }
    if halves.is_some() {
        facts.ints.insert(nikaia_std::block::Text::from(words.resolve(*nikaia_std::index::get(&names, 0)).to_string()));
        match bounding_unwrapped(value) {
            Expr::MethodCall { method, .. } => {
                let method = *method;
                let named = words.resolve(method);
                if named == "widening_mul" || named == "narrowing_div_rem" { facts.ints.insert(nikaia_std::block::Text::from(words.resolve(*nikaia_std::index::get(&names, 1)).to_string())); }
            },
            _ => { },
        }
        bounding_push(&walk, facts, nikaia_std::index::or(halves, || 0));
    }
    if names.len() != 1 { return; }
    let name = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&names, (0) as usize) }).to_string());
    match value {
        Expr::LitBool(up, _) => { let up = *up; bounding_flag_set(walk, facts, &name, up); },
        _ => { },
    }
    if value_lin.is_none() {
        let chosen = bounding_choice_facts(walk, &facts, &name, value, context, program, words, &mut &mut *ask);
        if !chosen.is_empty() {
            facts.ints.insert(nikaia_std::block::Text::from(name.to_string()));
            for fact in chosen.iter() {
                let fact = nikaia_std::num::value(fact);
                bounding_push(&walk, facts, fact);
            }
        }
    }
    let held = walk.arena.var(&bounding_element_of(&name));
    for each in bounding_each(walk, value, held, None, &facts, context, program, words) {
        let fact = bounding_each_guarded(walk, each);
        bounding_push(&walk, facts, fact);
    }
    rules_result_facts(walk, facts, &name, value, context, words);
    bounding_returned_facts(walk, facts, &name, unwrapped, context, words);
    bounding_relations_push(walk, facts, &name, &relations);
    for fact in field_facts.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    for path in field_paths.iter() { facts.ints.insert(nikaia_std::block::Text::from(path.to_string())); }
    let read_from = bounding_read_out_of(value, words);
    if read_from.is_some() {
        let key = elements_key(&walk.shape, nikaia_std::index::or(read_from, || value.into()), words);
        if key.is_some() { bounding_end_facts(walk, facts, &name, nikaia_std::index::or(key.as_deref(), || "")); }
    }
    rules_element_facts(walk, facts, &name, value, words);
    rules_ascending_facts(walk, facts, &name, value, context, program, words, &mut &mut *ask);
    if whole {
        facts.ints.insert(nikaia_std::block::Text::from(name.to_string()));
        if value_lin.is_some() {
            let v = nikaia_std::index::or(value_lin, || 0);
            if !walk.arena.mentions(v, &name) {
                let n = walk.arena.var(&name);
                let fact = walk.arena.equal(n, v);
                bounding_push(&walk, facts, fact);
            }
        }
        if bounding_declared_unsigned(ty, words) { bounding_at_least_zero(walk, facts, &name); }
        if value_range.is_some() { bounding_bounded(walk, facts, &name, &nikaia_std::index::or(value_range, || Range::open())); }
    }
    bounding_built(walk, facts, &name, value, words);
    for fact in measured.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    bounding_built_choice(walk, facts, &name, value, context, program, words, &mut &mut *ask);
    if bounding_declared_list(ty, words) { bounding_collected(walk, facts, &name, value, context, program, words); }
    if walk.shape.roots.contains(&name) {
        match value {
            Expr::ListLit { items, .. } => { for item in items.iter() { bounding_write(walk, &name, item, &facts, context, program, words, &mut &mut *ask); } },
            Expr::ListRepeat { value: item, .. } => { let item = nikaia_std::boxed::open(item); bounding_write(walk, &name, item, &facts, context, program, words, &mut &mut *ask); },
            Expr::Call { .. } => { bounding_call_root(walk, &name, value, context, words); },
            _ => { },
        }
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_built_choice(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    match value {
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
            let first = match bounding_arm_value(then_branch) { Some(__nikaia_value) => __nikaia_value, None => return };
            let second = match bounding_arm_value(otherwise) { Some(__nikaia_value) => __nikaia_value, None => return };
            let length = length_of(name);
            let mut taken = facts.clone();
            bounding_assume(walk, &mut taken, cond, context, program, words);
            bounding_built(walk, &mut taken, name, first, words);
            let mut passed = facts.clone();
            bounding_assume_not(walk, &mut passed, cond, context, program, words);
            bounding_built(walk, &mut passed, name, second, words);
            if !bounding_reads_name(&walk, &taken, &length) || !bounding_reads_name(&walk, &passed, &length) { return; }
            let mut changed = nothing_changed();
            changed.values.insert(nikaia_std::block::Text::from(name.to_string()));
            bounding_if_join(walk, facts, &changed, &taken, &passed, &mut *ask);
            bounding_flag_join(walk, facts, &changed, &taken, &passed, &mut *ask);
        },
        _ => { },
    }
}

pub(crate) fn bounding_reads_name(walk: &BoundsWalk, facts: &BoundsFacts, name: &str) -> bool {
    for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if walk.arena.mentions(fact, name) { return true; }
    }
    false
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_choice_facts(walk: &mut BoundsWalk, facts: &BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Vec<i64> {
    let mut own: Vec<Vec<i64>> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut states: Vec<BoundsFacts> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    match value {
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
            let mut taken = facts.clone();
            bounding_assume(walk, &mut taken, cond, context, program, words);
            let mut passed = facts.clone();
            bounding_assume_not(walk, &mut passed, cond, context, program, words);
            let first = match bounding_arm_value(then_branch) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
            let mut held = match bounding_arm_facts(walk, facts, name, first, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
            bounding_arm_restated(walk, facts, &taken, name, first, context, program, words, &mut held);
            own.push(held);
            states.push(taken);
            let second = match bounding_arm_value(otherwise) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
            let mut held_else = match bounding_arm_facts(walk, facts, name, second, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
            bounding_arm_restated(walk, facts, &passed, name, second, context, program, words, &mut held_else);
            own.push(held_else);
            states.push(passed);
        },
        Expr::Match { arms, .. } => {
            for arm in arms.iter() {
                let mut bound: Vec<String> = vec![];
                match &arm.pattern {
                    MatchPattern::Path(segments) => { if segments.len() == 1 { return vec![]; } },
                    _ => { frame_pattern_names(&arm.pattern, words, &mut bound); },
                }
                if !bound.is_empty() { return vec![]; }
                let arm_value = match bounding_arm_body(&arm.body) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
                own.push(match bounding_arm_facts(walk, facts, name, arm_value, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return vec![] });
                states.push(facts.clone());
            }
        },
        Expr::Coalesce { value: held, fallback, .. } => {
            let held = nikaia_std::boxed::open(held); let fallback = nikaia_std::boxed::open(fallback);
            if bounding_leaves(fallback) { return vec![]; }
            own.push(match bounding_arm_facts(walk, facts, name, held, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return vec![] });
            states.push(facts.clone());
            own.push(match bounding_arm_facts(walk, facts, name, fallback, context, program, words, &mut *ask) { Some(__nikaia_value) => __nikaia_value, None => return vec![] });
            states.push(facts.clone());
        },
        _ => { return vec![]; },
    }
    let mut out: Vec<i64> = vec![];
    if own.len() < 2 { return out; }
    for k in 0..own.len() as i64 {
        for fact in (*unsafe { nikaia_std::proven::read(&own, (k) as usize) }).iter() {
            let fact = nikaia_std::num::value(fact);
            if out.contains(&fact) { continue; }
            let mut every = true;
            for j in 0..own.len() as i64 {
                if !every || j == k || (*unsafe { nikaia_std::proven::read(&own, (j) as usize) }).contains(&fact) { continue; }
                let mut trial = (*unsafe { nikaia_std::proven::read(&states, (j) as usize) }).clone();
                for held in (*unsafe { nikaia_std::proven::read(&own, (j) as usize) }).iter() {
                    let held = nikaia_std::num::value(held);
                    bounding_push(&walk, &mut trial, held);
                }
                every = bounding_proves(&walk, &trial, fact, &mut *ask);
            }
            if every { out.push(fact); }
        }
    }
    out
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_arm_restated(walk: &mut BoundsWalk, facts: &BoundsFacts, state: &BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, held: &mut Vec<i64>) {
    let term = match bounding_lin(walk, value, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(term, &mut read);
    if read.len() != 1 { return; }
    let mut v: String = String::from("");
    for only in read.iter() { v = nikaia_std::block::Text::from(only.to_string()); }
    let mut at_zero: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    at_zero.insert(nikaia_std::block::Text::from(v.to_string()), walk.arena.int(0));
    let mut at_one: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    at_one.insert(nikaia_std::block::Text::from(v.to_string()), walk.arena.int(1));
    let zero = walk.arena.substitute(term, &at_zero);
    let one = walk.arena.substitute(term, &at_one);
    let c = match walk.arena.constant(zero) { Some(__nikaia_value) => __nikaia_value, None => return };
    let d = match walk.arena.constant(one) { Some(__nikaia_value) => __nikaia_value, None => return };
    if d - c != 1 { return; }
    let named = walk.arena.var(name);
    let shift = walk.arena.int(c);
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    given.insert(nikaia_std::block::Text::from(v.to_string()), walk.arena.sub(named, shift));
    for fact in state.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if facts.facts.contains(&fact) || !walk.arena.mentions(fact, &v) { continue; }
        let restated = walk.arena.substitute(fact, &given);
        if !held.contains(&restated) { held.push(restated); }
    }
}

pub(crate) fn bounding_arm_body(body: &Expr) -> Option<&Expr> {
    match body {
        Expr::Block(block, _) => { return bounding_arm_value(block); },
        _ => { },
    }
    Some(body)
}

pub(crate) fn bounding_arm_value(arm: &Block) -> Option<&Expr> {
    if arm.stmts.len() != 1 { return None; }
    match &unsafe { nikaia_std::proven::read(&arm.stmts, (0) as usize) }.node {
        Stmt::Expr(value) => Some(value),
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_arm_facts(walk: &mut BoundsWalk, facts: &BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Option<Vec<i64>> {
    let n = walk.arena.var(name);
    let lin = bounding_lin(walk, value, facts, context, program, words);
    if lin.is_some() {
        let term = nikaia_std::index::or(lin, || 0);
        if walk.arena.mentions(term, name) { return None; }
        let mut sides = vec![walk.arena.le(n, term), walk.arena.ge(n, term)];
        let mut read = facts.clone();
        rules_element_facts(walk, &mut read, name, value, words);
        for fact in read.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            if walk.arena.mentions(fact, name) && !sides.contains(&fact) { sides.push(fact); }
        }
        return Some(sides);
    }
    let call = matches!(value, Expr::Call { .. } | Expr::MethodCall { .. });
    if !call { return None; }
    let relations = bounding_relations_of(walk, facts, name, value, context, program, words, &mut *ask);
    let mut given = facts.clone();
    given.facts = vec![];
    bounding_returned_facts(walk, &mut given, name, value, context, words);
    bounding_relations_push(walk, &mut given, name, &relations);
    let range = nikaia_std::index::or(bounding_range(walk, value, facts, context, program, words, &mut *ask), || Range::open());
    if range.lo.is_some() {
        let least = walk.arena.int(nikaia_std::index::or(range.lo, || 0));
        let low = walk.arena.ge(n, least);
        bounding_push(&walk, &mut given, low);
    }
    if range.hi.is_some() {
        let most = walk.arena.int(nikaia_std::index::or(range.hi, || 0));
        let high = walk.arena.le(n, most);
        bounding_push(&walk, &mut given, high);
    }
    Some(given.facts.copy_owned())
}

pub(crate) fn bounding_read_out_of<'r>(value: &'r Expr, words: &winnow_grammar::InternerContext) -> Option<&'r Expr> {
    match value {
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); Some(base) },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if args.len() == 1 && words.resolve(method) == "get" { return Some(receiver); }
            return None;
        },
        Expr::Coalesce { value: inner, fallback, .. } => {
            let inner = nikaia_std::boxed::open(inner); let fallback = nikaia_std::boxed::open(fallback);
            if bounding_leaves(fallback) { return bounding_read_out_of(inner, words); }
            return None;
        },
        _ => None,
    }
}

pub(crate) fn bounding_leaves(expr: &Expr) -> bool { matches!(expr, Expr::Return(_, _) | Expr::Continue(_) | Expr::Break(_)) }

pub(crate) fn bounding_unwrapped(value: &Expr) -> &Expr {
    match value {
        Expr::Coalesce { value: inner, fallback, .. } => {
            let inner = nikaia_std::boxed::open(inner); let fallback = nikaia_std::boxed::open(fallback);
            if bounding_leaves(fallback) { return bounding_unwrapped(inner); }
            value
        },
        _ => value,
    }
}

pub(crate) fn bounding_found_whole(walk: &mut BoundsWalk, value: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> bool {
    let call = matches!(value, Expr::Call { .. } | Expr::MethodCall { .. });
    if !call { return false; }
    let callee = match bounding_found_key(&walk, value, context, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
    walk.found_asked.insert(nikaia_std::block::Text::from(callee.to_string()));
    walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
    let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return false };
    !found.each && found.plain
}

pub(crate) fn bounding_declared_whole(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> Option<bool> {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(t.generics.is_empty() && is_whole_number(words.resolve(t.name)))
}

pub(crate) fn bounding_declared_list(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    let name = words.resolve(t.name);
    t.generics.len() == 1 && (name == "Vec" || name == "List")
}

pub(crate) fn bounding_collected(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) {
    match value {
        Expr::MethodCall { receiver: sequence, method, args, .. } => {
            let sequence = nikaia_std::boxed::open(sequence); let method = *method;
            if !args.is_empty() || words.resolve(method) != "collect" { return; }
            match sequence {
                Expr::MethodCall { method: made, args: given, .. } => {
                    let made = *made;
                    let ty = match *nikaia_std::index::get(&context.std_receivers, &(node_key(sequence))) { Some(__nikaia_value) => __nikaia_value, None => return };
                    let collected = match *nikaia_std::index::get(&context.collected, &(format!("{}::{}", ty, words.resolve(made)))) { Some(__nikaia_value) => __nikaia_value, None => return };
                    if (given.len() as i64) != collected.params.len() as i64 { return; }
                    let mut named: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
                    for k in 0..given.len() as i64 {
                        let term = if *nikaia_std::index::get(&collected.chars, (k) as usize) { bounding_code_of(walk, unsafe { nikaia_std::proven::read(&given, (k) as usize) }, context, words) } else { nikaia_std::index::or(bounding_lin(walk, unsafe { nikaia_std::proven::read(&given, (k) as usize) }, &facts, context, program, words), || bounding_fresh(walk).into()) };
                        named.insert(nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&collected.params, (k) as usize) }).to_string()), term);
                    }
                    named.insert(length_of("result"), walk.arena.var(&length_of(name)));
                    for nodes in collected.conditions.iter() {
                        let read = walk.arena.adopt(nodes);
                        let fact = walk.arena.substitute(read, &named);
                        bounding_push(&walk, facts, fact);
                    }
                },
                _ => { },
            }
        },
        _ => { },
    }
}

pub(crate) fn bounding_declared_unsigned(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    words.resolve(t.name).starts_with('u')
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_assign_place(walk: &mut BoundsWalk, facts: &mut BoundsFacts, target: &Expr, op: Option<&BinaryOp>, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let p = match bounding_place_path(target, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    if context.whole_fields.contains(&node_key(target)) { facts.ints.insert(nikaia_std::block::Text::from(p.to_string())); } else { facts.ints.remove(&p); }
    bounding_assign(walk, facts, &p, op, value, context, program, words, &mut *ask);
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_compound(walk: &mut BoundsWalk, op: Option<&BinaryOp>, target: &Expr, value: &Expr, at: i64, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let operation = match op { Some(__nikaia_value) => __nikaia_value, None => return };
    let arithmetic = matches!(operation, BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul);
    if walk.collecting { return; }
    let divided = *nikaia_std::index::get(&context.divisions, &at);
    if divided.is_some() {
        if bounding_place_path(target, words).is_some() && bounding_divides(walk, target, value, nikaia_std::index::or(divided, || ""), facts, context, program, words, &mut *ask) { walk.proven.arithmetic.insert(at); }
        return;
    }
    if !arithmetic { return; }
    let place = bounding_place_path(target, words);
    if place.is_none() { return; }
    let ty = match *nikaia_std::index::get(&context.arithmetic, &at) { Some(__nikaia_value) => __nikaia_value, None => return };
    if bounding_fits(walk, operation, target, value, ty, facts, context, program, words, &mut *ask) { walk.proven.arithmetic.insert(at); } else { walk.open += 1; }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_for(walk: &mut BoundsWalk, bindings: &[winnow_grammar::Symbol], iter: &Expr, body: &Block, facts: &mut BoundsFacts, cands: &[String], invariant: &[i64], context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    bounding_expr(walk, iter, facts, context, program, words, &mut &mut *ask);
    let changed = bounding_changed(body, context, words);
    let kept = rules_loop_entry(walk, &facts, &changed, &mut &mut *ask);
    let mut counted = false;
    let mut name: String = String::from("");
    let mut low: Option<i64> = None;
    let mut high: Option<i64> = None;
    let mut closed = false;
    if bindings.len() == 1 {
        match iter {
            Expr::Range { start, end, inclusive, .. } => {
                let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); let inclusive = *inclusive;
                low = bounding_lin(walk, start, &facts, context, program, words);
                high = bounding_lin(walk, end, &facts, context, program, words);
                counted = true;
                name = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&bindings, (0) as usize) }).to_string());
                closed = inclusive;
            },
            _ => { },
        }
    }
    let mut inner = facts.clone();
    let mut outside: collections::BTreeSet<String> = collections::BTreeSet::new();
    for binding in bindings.iter() {
        let binding = *binding;
        outside.insert(nikaia_std::block::Text::from(words.resolve(binding).to_string()));
    }
    let mut pairs: Vec<(String, String)> = vec![];
    let steps = bounding_turn_steps(walk, body, &outside, &changed, &facts, context, words, &mut &mut *ask, &mut pairs);
    let mut turn_facts: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut all_turns: Option<i64> = None;
    if !steps.is_empty() {
        let turn_name = format!("#turn{}", walk.entries);
        let t = walk.arena.var(&turn_name);
        walk.entries += 1;
        let mut limit: Option<i64> = None;
        let mut binding_at: Option<i64> = None;
        if counted && low.is_some() && high.is_some() {
            let l = nikaia_std::index::or(low, || 0);
            let h = nikaia_std::index::or(high, || 0);
            if bounding_stable(&walk, l, &changed, &name) && bounding_stable(&walk, h, &changed, &name) {
                let reached = walk.arena.add(l, t);
                limit = Some(bounding_below(walk, reached, h, closed));
                let bound = walk.arena.var(&name);
                binding_at = Some(walk.arena.equal(bound, reached));
                let mut span = walk.arena.sub(h, l);
                if closed {
                    let one = walk.arena.int(1);
                    span = walk.arena.add(span, one);
                }
                let ordered = walk.arena.le(l, h);
                if bounding_proves(&walk, &facts, ordered, &mut &mut *ask) { all_turns = Some(span); }
            }
        } else if !counted {
            let walked = nikaia_std::index::or(path_of(iter, words), || "".into());
            let mut stable = walked != "" && !changed.lengths.contains(&walked);
            for v in changed.values.iter() { if path_within(&walked, v) { stable = false; } }
            if stable {
                let length = bounding_length(walk, iter, &walked, context);
                if length.is_some() {
                    limit = Some(walk.arena.lt(t, nikaia_std::index::or(length, || 0)));
                    all_turns = std::convert::identity(length);
                }
            }
            let text = nikaia_std::index::or(bounding_chars_of(iter, context, words), || "".into());
            if limit.is_none() && text != "" && !text.contains('.') && !changed.values.contains(&text) && !changed.lengths.contains(&text) {
                let length = bounding_length_named(walk, &text, false);
                limit = Some(walk.arena.lt(t, length));
            }
        }
        let mut counted_by: Vec<i64> = vec![];
        if limit.is_none() && bindings.len() == 1 {
            let element = bounding_fresh(walk);
            let mut tied = false;
            for fact in bounding_each(walk, iter, element, Some(t), &facts, context, program, words) {
                tied = tied || walk.arena.mentions(fact, &turn_name);
                counted_by.push(fact);
            }
            if !tied { counted_by = vec![]; }
        }
        if limit.is_some() || !counted_by.is_empty() {
            let zero = walk.arena.int(0);
            turn_facts.push(walk.arena.ge(t, zero));
            if limit.is_some() { turn_facts.push(nikaia_std::index::or(limit, || 0)); }
            turn_facts.extend(counted_by);
            if binding_at.is_some() { turn_facts.push(nikaia_std::index::or(binding_at, || 0)); }
            for fact in bounding_turn_bounds(walk, &mut inner, &steps, t) { turn_facts.push(fact); }
        }
    }
    for fact in bounding_pair_bounds(walk, &mut inner, &pairs, "") { turn_facts.push(fact); }
    let followers = bounding_followers(walk, body, &name, counted, low, high, &changed, &facts, words, &mut &mut *ask);
    let mut scaled: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let scales = bounding_turn_scales(&walk, body, &outside, &changed, &facts, context, words);
    if !scales.is_empty() {
        let multiplies = scales.iter().any(|s| { s.1 > 1 });
        let mut most: Option<i64> = None;
        if counted { most = bounding_for_turns_most(walk, low, high, closed, &changed, &name, &facts, !multiplies, &mut &mut *ask); }
        scaled = bounding_scaled_bounds(walk, &facts, &scales, most, &mut &mut *ask);
    }
    let mut entered: Vec<(String, i64)> = nikaia_std::block::list(nikaia_std::block::Place::Block); #[allow(clippy::redundant_locals)] let followers = followers;
    entered.reserve(followers.iter().size_hint().0); for x in followers.iter() {
        let e = bounding_rename(walk, &mut inner, x);
        entered.push((nikaia_std::block::Text::from(x.to_string()), e));
    }
    bounding_loop_change(walk, &mut inner, &changed, cands);
    rules_loop_give(walk, &mut inner, &kept, &changed);
    for binding in bindings.iter() {
        let binding = *binding;
        let bound = words.resolve(binding);
        bounding_forget(&walk, &mut inner, bound);
        inner.ints.remove(bound);
    }
    for (x, e) in entered.iter() {
        let e = nikaia_std::num::value(e);
        let v = walk.arena.var(x);
        let n = walk.arena.var(&name);
        let above = walk.arena.ge(v, e);
        bounding_push(&walk, &mut inner, above);
        let below = walk.arena.lt(v, n);
        bounding_push(&walk, &mut inner, below);
    }
    for fact in invariant.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, &mut inner, fact);
    }
    for fact in turn_facts.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, &mut inner, fact);
    }
    for fact in scaled.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, &mut inner, fact);
    }
    let mut classed: Option<String> = None;
    if bindings.len() == 1 && !counted {
        let over = bounding_chars_of(iter, context, words);
        if over.is_some() {
            let text = nikaia_std::index::or(over, || "".into());
            let class = *nikaia_std::index::get(&context.text_classes, &text);
            if class.is_some() && !walk.shape.bound.contains(&text) {
                let only = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&bindings, (0) as usize) }).to_string());
                walk.loop_classes.insert(nikaia_std::block::Text::from(only.to_string()), nikaia_std::index::or(class, || Range::open()));
                classed = Some(only);
            }
        }
    }
    if bindings.len() == 1 && !counted {
        let element = context.whole_loops.get(&node_key(iter));
        if element.is_some() {
            let only = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&bindings, (0) as usize) }).to_string());
            inner.ints.insert(nikaia_std::block::Text::from(only.to_string()));
            let held = Range::held_by_type(nikaia_std::index::or(element, || ""));
            if held.is_some() { bounding_bounded(walk, &mut inner, &only, &nikaia_std::index::or(held, || Range::open())); }
        }
    }
    let parts = context.whole_parts.get(&node_key(iter));
    if bindings.len() > 1 && parts.is_some() {
        for (at, binding) in bindings.iter().enumerate().map(|(at, item)| (at as i64, item)) {
            if nikaia_std::index::or(match parts {
                Some(__nikaia_it) => Some(__nikaia_it.contains(&(at as i64))),
                None => None,
            }, || false) { inner.ints.insert(nikaia_std::block::Text::from(words.resolve(*binding).to_string())); }
        }
    }
    if bindings.len() == 1 && !counted {
        let key = elements_key(&walk.shape, iter, words);
        if key.is_some() {
            let bound = bounding_assumed(walk, nikaia_std::index::or(key.as_deref(), || ""));
            if bound.is_some() {
                let only = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&bindings, (0) as usize) }).to_string());
                inner.ints.insert(nikaia_std::block::Text::from(only.to_string()));
                bounding_bounded(walk, &mut inner, &only, &nikaia_std::index::or(bound, || Range::open()));
            }
            let only = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&bindings, (0) as usize) }).to_string());
            bounding_end_facts(walk, &mut inner, &only, nikaia_std::index::or(key.as_deref(), || ""));
        }
    }
    if bindings.len() == 1 && !counted {
        let only = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&bindings, (0) as usize) }).to_string());
        let item = walk.arena.var(&only);
        let mut stated = bounding_each(walk, iter, item, None, &facts, context, program, words);
        let mut held = path_of(iter, words);
        if held.is_none() {
            let outer = rules_inner_of(iter, words);
            if outer.is_some() { held = Some(format!("{}[]", nikaia_std::index::or(outer.as_deref(), || ""))); }
        }
        if held.is_some() {
            let element = bounding_element_of(nikaia_std::index::or(held.as_deref(), || ""));
            let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            given.insert(nikaia_std::block::Text::from(element.to_string()), item);
            let mut of_every = false;
            for fact in facts.facts.iter() {
                let fact = nikaia_std::num::value(fact);
                if walk.arena.mentions(fact, &element) {
                    stated.push(walk.arena.substitute(fact, &given));
                    of_every = true;
                }
            }
            for (each, fact) in walk.rule_facts.copy_owned() {
                if each == element && rules_standing(&walk, &facts, fact) {
                    stated.push(walk.arena.substitute(fact, &given));
                    of_every = true;
                }
            }
            if of_every { stated.push(bounding_each_present(walk, nikaia_std::index::or(held.as_deref(), || ""))); }
        }
        for fact in stated.iter() {
            let fact = nikaia_std::num::value(fact);
            if bounding_unchanged(&walk, fact, &changed) {
                inner.ints.insert(nikaia_std::block::Text::from(only.to_string()));
                bounding_push(&walk, &mut inner, fact);
            }
        }
    }
    if counted {
        inner.ints.insert(nikaia_std::block::Text::from(name.to_string()));
        let n = walk.arena.var(&name);
        if low.is_some() {
            let l = nikaia_std::index::or(low, || 0);
            if bounding_stable(&walk, l, &changed, &name) {
                let fact = walk.arena.le(l, n);
                bounding_push(&walk, &mut inner, fact);
            }
        }
        if high.is_some() {
            let h = nikaia_std::index::or(high, || 0);
            if bounding_stable(&walk, h, &changed, &name) {
                let fact = bounding_below(walk, n, h, closed);
                bounding_push(&walk, &mut inner, fact);
            }
        }
    }
    walk.rule_loops.push(kept.copy_owned());
    if !bounding_block(walk, body, &mut inner, context, program, words, &mut &mut *ask) { bounding_turn_end(walk, &inner, false, false, &mut &mut *ask); }
    walk.rule_loops.pop();
    if classed.is_some() { walk.loop_classes.remove(nikaia_std::index::or(classed.as_deref(), || "")); }
    let mut filled: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut count: i64 = 0;
    if counted && low.is_some() && high.is_some() {
        let l = nikaia_std::index::or(low, || 0);
        let h = nikaia_std::index::or(high, || 0);
        let mut stable = true;
        for c in changed.values.iter() { if bounding_reads(&walk, l, h, c) { stable = false; } }
        for c in changed.lengths.iter() { if bounding_reads(&walk, l, h, c) { stable = false; } }
        let mut lists: Vec<String> = vec![];
        if stable { lists = filled_once(body, &walk.pinned, words); }
        let not_empty = walk.arena.le(l, h);
        if !lists.is_empty() && bounding_proves(&walk, &facts, not_empty, &mut &mut *ask) {
            let mut taken: i64 = 0;
            if closed { taken = 1; }
            let one = walk.arena.int(taken);
            let span = walk.arena.sub(h, l);
            count = walk.arena.add(span, one);
            filled = lists;
        }
    }
    let mut outer = BoundsChanged { values: changed.values.copy_owned(), lengths: changed.lengths.copy_owned(), parts: changed.parts.copy_owned(), jumps: changed.jumps.copy_owned(), drops: changed.drops.copy_owned(), falls: changed.falls.copy_owned(), bare_falls: changed.bare_falls.copy_owned(), elements: changed.elements.copy_owned() };
    for list in filled.iter() {
        outer.lengths.remove(list);
        outer.falls.remove(list);
        outer.bare_falls.remove(list);
    }
    let mut past: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    if walk.through_loops && all_turns.is_some() && !breaks(body, words) {
        let mut counters: Vec<(String, i64, i64, Option<i64>)> = vec![];
        for (name, low, high, floor) in steps.iter() {
            let low = nikaia_std::num::value(low);let high = nikaia_std::num::value(high);let floor = *floor;
            if !filled.iter().any(|list| { length_of(list) == *name }) { counters.push((nikaia_std::block::Text::from(name.to_string()), low, high, floor)); }
        }
        past = bounding_turn_bounds(walk, facts, &counters, nikaia_std::index::or(all_turns, || 0));
    }
    let mut paired: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    if !breaks(body, words) { paired = bounding_pair_bounds(walk, facts, &pairs, ""); }
    let mut left: Vec<(String, i64)> = nikaia_std::block::list(nikaia_std::block::Place::Block); #[allow(clippy::redundant_locals)] let followers = followers;
    left.reserve(followers.iter().size_hint().0); for x in followers.iter() {
        let e = bounding_rename(walk, facts, x);
        left.push((nikaia_std::block::Text::from(x.to_string()), e));
    }
    bounding_loop_change(walk, facts, &outer, cands);
    rules_loop_give(walk, facts, &kept, &outer);
    for fact in invariant.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    for (x, e) in left.iter() {
        let e = nikaia_std::num::value(e);
        let v = walk.arena.var(x);
        let above = walk.arena.ge(v, e);
        bounding_push(&walk, facts, above);
        let h = nikaia_std::index::or(high, || 0);
        let entered_below = bounding_below(walk, e, h, closed);
        if bounding_proves(&walk, &facts, entered_below, &mut &mut *ask) {
            let below = bounding_below(walk, v, h, closed);
            bounding_push(&walk, facts, below);
        }
    }
    for fact in past.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    for fact in scaled.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
    for list in filled.iter() { bounding_shift(walk, facts, &length_of(list), count); }
    for fact in paired.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_followers(walk: &mut BoundsWalk, body: &Block, name: &str, counted: bool, low: Option<i64>, high: Option<i64>, changed: &BoundsChanged, facts: &BoundsFacts, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Vec<String> {
    let mut found: Vec<String> = vec![];
    if !counted || low.is_none() || high.is_none() { return found; }
    let l = nikaia_std::index::or(low, || 0);
    let h = nikaia_std::index::or(high, || 0);
    if !bounding_stable(&walk, l, changed, name) || !bounding_stable(&walk, h, changed, name) { return found; }
    for x in changed.values.iter() {
        if x == name || x.contains('.') || !facts.ints.contains(x) || walk.pinned.contains(x) { continue; }
        if !follows_only(body, x, name, words) { continue; }
        let v = walk.arena.var(x);
        let before = walk.arena.lt(v, l);
        if bounding_proves(&walk, facts, before, &mut *ask) { found.push(nikaia_std::block::Text::from(x.to_string())); }
    }
    found
}

pub(crate) fn bounding_rename(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str) -> i64 {
    let e = walk.arena.var(&format!("{}#{}", name, walk.entries));
    walk.entries += 1;
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    given.insert(nikaia_std::block::Text::from(name.to_string()), e);
    let mut kept: Vec<i64> = vec![];
    kept.reserve(facts.facts.iter().size_hint().0); for fact in facts.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if walk.arena.mentions(fact, name) { kept.push(walk.arena.substitute(fact, &given)); }
        kept.push(fact);
    }
    facts.facts = kept;
    e
}

pub(crate) fn bounding_below(walk: &mut BoundsWalk, n: i64, h: i64, closed: bool) -> i64 {
    if closed { return walk.arena.le(n, h); }
    walk.arena.lt(n, h)
}

pub(crate) fn bounding_stable(walk: &BoundsWalk, t: i64, changed: &BoundsChanged, name: &str) -> bool { bounding_unchanged(walk, t, changed) && !walk.arena.mentions(t, name) }

pub(crate) fn bounding_unchanged(walk: &BoundsWalk, t: i64, changed: &BoundsChanged) -> bool {
    for c in changed.values.iter() { if bounding_touches(walk, t, c) { return false; } }
    for c in changed.lengths.iter() { if walk.arena.mentions(t, &length_of(c)) { return false; } }
    for c in changed.parts.iter() { if bounding_touches(walk, t, c) { return false; } }
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(t, &mut read);
    for v in read.iter() { for place in changed.elements.iter() { if bounding_element_hit(v, place, false) { return false; } } }
    true
}

pub(crate) fn bounding_reads(walk: &BoundsWalk, l: i64, h: i64, c: &str) -> bool {
    let length = length_of(c);
    bounding_touches(walk, l, c) || bounding_touches(walk, h, c) || walk.arena.mentions(l, &length) || walk.arena.mentions(h, &length)
}

pub(crate) fn bounding_lowers(walk: &mut BoundsWalk, facts: &BoundsFacts, by: Option<i64>, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    let step = match by { Some(__nikaia_value) => __nikaia_value, None => return false };
    let zero = walk.arena.int(0);
    let goal = walk.arena.le(step, zero);
    bounding_proves(&walk, facts, goal, &mut *ask)
}

pub(crate) fn bounding_set_lower(walk: &mut BoundsWalk, facts: &BoundsFacts, name: &str, op: Option<&BinaryOp>, value_lin: Option<i64>, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    if op.is_some() { return false; }
    let v = match value_lin { Some(__nikaia_value) => __nikaia_value, None => return false };
    if walk.arena.mentions(v, name) { return false; }
    let now = walk.arena.var(name);
    let goal = walk.arena.le(v, now);
    bounding_proves(&walk, facts, goal, &mut *ask)
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_assign(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, op: Option<&BinaryOp>, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if !facts.ints.contains(name) {
        if walk.growing.contains(name) { walk.grow_failed.insert(nikaia_std::block::Text::from(name.to_string())); }
        if walk.falling.contains(name) { walk.fall_failed.insert(nikaia_std::block::Text::from(name.to_string())); }
        let mut measured: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        if op.is_none() { measured = bounding_measured(walk, &facts, name, name, value, context, program, words); }
        bounding_forget(&walk, facts, name);
        bounding_built(walk, facts, name, value, words);
        for fact in measured.iter() {
            let fact = nikaia_std::num::value(fact);
            bounding_push(&walk, facts, fact);
        }
        if op.is_none() {
            match value {
                Expr::LitBool(up, _) => { let up = *up; bounding_flag_set(walk, facts, name, up); },
                _ => { },
            }
        }
        return;
    }
    let value_lin = bounding_lin(walk, value, &facts, context, program, words);
    bounding_settle(walk, facts);
    let now = walk.arena.var(name);
    let mut by: Option<i64> = None;
    if value_lin.is_some() {
        let v = nikaia_std::index::or(value_lin, || 0);
        if bounding_is_op(op, &BinaryOp::Add) && !walk.arena.mentions(v, name) { by = Some(v); } else if bounding_is_op(op, &BinaryOp::Sub) && !walk.arena.mentions(v, name) { by = Some(walk.arena.neg(v)); } else if op.is_none() && walk.arena.mentions(v, name) {
            let d = walk.arena.sub(v, now);
            let mut at_zero: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            at_zero.insert(nikaia_std::block::Text::from(name.to_string()), walk.arena.int(0));
            let d0 = walk.arena.substitute(d, &at_zero);
            let mut at_one: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            at_one.insert(nikaia_std::block::Text::from(name.to_string()), walk.arena.int(1));
            let d1 = walk.arena.substitute(d, &at_one);
            let same = walk.arena.equal(d0, d1);
            let none: Vec<i64> = vec![];
            if ask(&walk.arena, &none, same) { by = Some(d0); }
        }
    }
    if walk.growing.contains(name) {
        let mut grows = false;
        if by.is_some() {
            let zero = walk.arena.int(0);
            let goal = walk.arena.ge(nikaia_std::index::or(by, || 0), zero);
            grows = bounding_proves(&walk, &facts, goal, &mut *ask);
        }
        if !grows && op.is_none() && value_lin.is_none() { grows = bounding_relation_grows(walk, &facts, name, value, context, program, words, &mut *ask); }
        if !grows { walk.grow_failed.insert(nikaia_std::block::Text::from(name.to_string())); }
    }
    if walk.falling.contains(name) && !bounding_lowers(walk, &facts, by, &mut *ask) && !bounding_set_lower(walk, &facts, name, op, value_lin, &mut *ask) { walk.fall_failed.insert(nikaia_std::block::Text::from(name.to_string())); }
    if by.is_some() {
        bounding_shift(walk, facts, name, nikaia_std::index::or(by, || 0));
        return;
    }
    if op.is_none() && value_lin.is_some() {
        let mut own_range: Option<Range> = None;
        if bounding_reads_own(&walk, nikaia_std::index::or(value_lin, || 0)) { own_range = bounding_range(walk, value, &facts, context, program, words, &mut *ask); }
        let mut given = nikaia_std::index::or(value_lin, || 0);
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(given, &mut read);
        if walk.arena.mentions(given, name) || !read.is_empty() {
            let old = bounding_rename(walk, facts, name);
            let mut renamed: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            renamed.insert(nikaia_std::block::Text::from(name.to_string()), old);
            given = walk.arena.substitute(given, &renamed);
        }
        bounding_forget(&walk, facts, name);
        let n = walk.arena.var(name);
        let fact = walk.arena.equal(n, given);
        bounding_push(&walk, facts, fact);
        if own_range.is_some() { bounding_bounded(walk, facts, name, &nikaia_std::index::or(own_range, || Range::open())); }
        return;
    }
    let mut range: Option<Range> = None;
    let mut relations: Vec<(bool, i64)> = vec![];
    if op.is_none() && value_lin.is_none() {
        range = bounding_range(walk, value, &facts, context, program, words, &mut *ask);
        relations = bounding_relations_of(walk, &facts, name, value, context, program, words, &mut *ask);
    }
    bounding_forget(&walk, facts, name);
    if walk.nonnegative.contains(name) || walk.shape.unsigned.contains(name) { bounding_at_least_zero(walk, facts, name); }
    if range.is_some() { bounding_bounded(walk, facts, name, &nikaia_std::index::or(range, || Range::open())); }
    bounding_relations_push(walk, facts, name, &relations);
}

pub(crate) fn bounding_literal_chars(expr: &Expr, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match expr {
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            if words.resolve(name) != "scalars" { return None; }
            bounding_ascii_length(base)
        },
        _ => None,
    }
}

pub(crate) fn bounding_ascii_length(expr: &Expr) -> Option<i64> {
    match expr {
        Expr::LitStr { text, .. } => {
            if (text.chars().count() as i64) != text.len() as i64 { return None; }
            Some(text.len() as i64)
        },
        _ => None,
    }
}

pub(crate) fn bounding_is_op(op: Option<&BinaryOp>, wanted: &BinaryOp) -> bool {
    let given = match op { Some(__nikaia_value) => __nikaia_value, None => return false };
    given == wanted
}

pub(crate) fn bounding_built(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, value: &Expr, words: &winnow_grammar::InternerContext) {
    match value {
        Expr::ListLit { items, .. } => {
            let length = length_of(name);
            let len = walk.arena.var(&length);
            let n = walk.arena.int(items.len() as i64);
            let fact = walk.arena.equal(len, n);
            bounding_push(&walk, facts, fact);
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() { return; }
            if words.resolve(method) == "collect" {
                let count = match bounding_literal_chars(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return };
                let len = walk.arena.var(&length_of(name));
                let n = walk.arena.int(count);
                let fact = walk.arena.equal(len, n);
                bounding_push(&walk, facts, fact);
                return;
            }
            if words.resolve(method) != "clone" { return; }
            let from = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return };
            if path_within(&from, name) || path_within(name, &from) { return; }
            let len = walk.arena.var(&length_of(name));
            let copied = walk.arena.var(&length_of(&from));
            let fact = walk.arena.equal(len, copied);
            bounding_push(&walk, facts, fact);
        },
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() {
                let given = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                let path = format!("{}.{}", name, words.resolve(field.name));
                let literal = bounding_step_literal(given);
                if literal.is_some() {
                    let v = walk.arena.var(&path);
                    let c = walk.arena.int(nikaia_std::index::or(literal, || 0));
                    let fact = walk.arena.equal(v, c);
                    bounding_push(&walk, facts, fact);
                    facts.ints.insert(nikaia_std::block::Text::from(path.to_string()));
                }
                bounding_built(walk, facts, &path, given, words);
            }
        },
        _ => { },
    }
}

pub(crate) fn bounding_place(walk: &mut BoundsWalk, target: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    match target {
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            bounding_place(walk, base, facts, context, program, words, &mut &mut *ask);
            bounding_expr(walk, index, facts, context, program, words, &mut &mut *ask);
            bounding_index(walk, base, index, &facts, context, program, words, &mut &mut *ask);
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_place(walk, base, facts, context, program, words, &mut &mut *ask); },
        _ => { },
    }
}

pub(crate) fn bounding_expr_leaves(walk: &mut BoundsWalk, expr: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    match expr {
        Expr::If { cond, then_branch, else_branch, .. } => { let cond = nikaia_std::boxed::open(cond); return bounding_if_leaves(walk, cond, then_branch, (else_branch).as_ref(), facts, context, program, words, &mut &mut *ask); },
        Expr::Return(value, _) => {
            let value = nikaia_std::boxed::open(value);
            if value.is_some() {
                let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return true };
                bounding_expr(walk, returned, facts, context, program, words, &mut &mut *ask);
            }
            rules_exit(walk, &facts, (value).as_ref(), false, context, program, words, &mut &mut *ask);
            return true;
        },
        Expr::Break(_) => {
            bounding_turn_end(walk, &facts, true, true, &mut &mut *ask);
            return true;
        },
        Expr::Continue(_) => {
            bounding_turn_end(walk, &facts, true, false, &mut &mut *ask);
            return true;
        },
        Expr::Throw(value, _) => {
            let value = nikaia_std::boxed::open(value);
            bounding_expr(walk, value, facts, context, program, words, &mut &mut *ask);
            rules_exit(walk, &facts, None, true, context, program, words, &mut &mut *ask);
            return true;
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = nikaia_std::index::or(bounding_variable(func, words), || "".into());
            if callee == "panic" {
                for arg in args.iter() { bounding_expr(walk, arg, facts, context, program, words, &mut &mut *ask); }
                return true;
            }
        },
        _ => { },
    }
    bounding_expr(walk, expr, facts, context, program, words, &mut &mut *ask);
    false
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_if_leaves(walk: &mut BoundsWalk, cond: &Expr, then_branch: &Block, else_branch: Option<&Block>, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) -> bool {
    bounding_expr(walk, cond, facts, context, program, words, &mut &mut *ask);
    let mut then_facts = facts.clone();
    bounding_assume(walk, &mut then_facts, cond, context, program, words);
    let mut then_leaves = bounding_block(walk, then_branch, &mut then_facts, context, program, words, &mut &mut *ask);
    let mut else_facts = facts.clone();
    bounding_assume_not(walk, &mut else_facts, cond, context, program, words);
    let mut else_leaves = bounding_maybe_block(walk, else_branch, &mut else_facts, context, program, words, &mut &mut *ask);
    let decided = bounding_decided(&walk, cond, context, words);
    if decided.is_some() { if nikaia_std::index::or(decided, || false) { else_leaves = true; } else { then_leaves = true; } }
    if then_leaves && else_leaves { return true; }
    if then_leaves {
        facts.ints = else_facts.ints;
        facts.facts = else_facts.facts;
    } else if else_leaves {
        facts.ints = then_facts.ints;
        facts.facts = then_facts.facts;
    } else {
        let mut changed = bounding_changed(then_branch, context, words);
        bounding_extend_maybe(&mut changed, else_branch, context, words);
        bounding_after_change(walk, facts, &changed);
        bounding_if_join(walk, facts, &changed, &then_facts, &else_facts, &mut &mut *ask);
        bounding_flag_join(walk, facts, &changed, &then_facts, &else_facts, &mut &mut *ask);
    }
    false
}

pub(crate) fn bounding_flag_join(walk: &mut BoundsWalk, facts: &mut BoundsFacts, changed: &BoundsChanged, then_facts: &BoundsFacts, else_facts: &BoundsFacts, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if changed.values.is_empty() { return; }
    let mut flags: collections::BTreeSet<String> = collections::BTreeSet::new();
    bounding_flag_names(&walk, then_facts, &mut flags);
    bounding_flag_names(&walk, else_facts, &mut flags);
    for flag in flags.iter() {
        let n = walk.arena.var(flag);
        let one = walk.arena.int(1);
        let zero = walk.arena.int(0);
        let up = walk.arena.ge(n, one);
        let down = walk.arena.le(n, zero);
        if bounding_proves(&walk, then_facts, up, &mut *ask) && bounding_proves(&walk, else_facts, down, &mut *ask) {
            bounding_flag_kept(walk, facts, then_facts, flag, down);
            bounding_flag_kept(walk, facts, else_facts, flag, up);
        } else if bounding_proves(&walk, then_facts, down, &mut *ask) && bounding_proves(&walk, else_facts, up, &mut *ask) {
            bounding_flag_kept(walk, facts, then_facts, flag, up);
            bounding_flag_kept(walk, facts, else_facts, flag, down);
        }
    }
}

pub(crate) fn bounding_flag_names(walk: &BoundsWalk, branch: &BoundsFacts, flags: &mut collections::BTreeSet<String>) {
    for fact in branch.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(fact, &mut read);
        if read.len() != 1 { continue; }
        for name in read.iter() {
            let list = nikaia_std::index::or(name.strip_suffix(".len()"), || std::convert::AsRef::<str>::as_ref(name));
            if !list.contains('.') && !list.contains('#') && !list.contains('[') && !list.contains('(') { flags.insert(nikaia_std::block::Text::from(name.to_string())); }
        }
    }
}

pub(crate) fn bounding_flag_kept(walk: &mut BoundsWalk, facts: &mut BoundsFacts, branch: &BoundsFacts, flag: &str, other: i64) {
    let mut own: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for fact in branch.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if !facts.facts.contains(&fact) && !bounding_touches(&walk, fact, flag) { own.push(fact); }
    }
    while (own.len() as i64) > most_flagged() { own.remove(0); }
    for fact in own.iter() {
        let fact = nikaia_std::num::value(fact);
        let kept = walk.arena.or(vec![other, fact]);
        if !facts.facts.contains(&kept) { bounding_push(&walk, facts, kept); }
    }
}

pub(crate) fn bounding_expr(walk: &mut BoundsWalk, expr: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    bounding_nonnegative(walk, expr, &facts, context, program, words, &mut &mut *ask);
    bounding_negation(walk, expr, &facts, context, program, words, &mut &mut *ask);
    match expr {
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            bounding_expr(walk, base, facts, context, program, words, &mut &mut *ask);
            bounding_expr(walk, index, facts, context, program, words, &mut &mut *ask);
            bounding_index(walk, base, index, &facts, context, program, words, &mut &mut *ask);
            rules_read_inside(walk, base, index, facts, context, program, words);
        },
        Expr::Binary { op, lhs, rhs, span, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); bounding_binary(walk, op, lhs, rhs, span.start as i64, facts, context, program, words, &mut &mut *ask); },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            bounding_expr(walk, cond, facts, context, program, words, &mut &mut *ask);
            let mut then_facts = facts.clone();
            bounding_assume(walk, &mut then_facts, cond, context, program, words);
            bounding_block(walk, then_branch, &mut then_facts, context, program, words, &mut &mut *ask);
            let mut changed = bounding_changed(then_branch, context, words);
            bounding_else(walk, (else_branch).as_ref(), cond, &facts, &mut changed, context, program, words, &mut &mut *ask);
            bounding_after_change(walk, facts, &changed);
        },
        Expr::Block(block, _) => { bounding_inner_block(walk, block, facts, context, program, words, &mut &mut *ask); },
        Expr::AsyncGroup(block, _, _, _, _) => { bounding_inner_block(walk, block, facts, context, program, words, &mut &mut *ask); },
        Expr::Unsafe(block, _) => {
            bounding_inner_block(walk, block, facts, context, program, words, &mut &mut *ask);
            for cond in prover_assumed_in_unsafe(block, words) { bounding_assume(walk, facts, &cond, context, program, words); }
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            bounding_expr(walk, value, facts, context, program, words, &mut &mut *ask);
            let mut changed = nothing_changed();
            let mut ends: Vec<BoundsFacts> = vec![];
            let mut bound: Vec<Vec<String>> = vec![];
            for arm in arms.iter() {
                let mut inner = facts.clone();
                let mut hidden: Vec<String> = vec![];
                frame_pattern_names(&arm.pattern, words, &mut hidden);
                for name in hidden.iter() {
                    bounding_forget(&walk, &mut inner, name);
                    inner.ints.remove(name);
                }
                match &arm.pattern {
                    MatchPattern::Path(segments) => {
                        if segments.len() == 1 && bounding_found_whole(walk, value, context, words) {
                            let name = nikaia_std::block::Text::from(words.resolve(*unsafe { nikaia_std::proven::read(&segments, (0) as usize) }).to_string());
                            let held = nikaia_std::index::or(bounding_arm_facts(walk, &facts, &name, value, context, program, words, &mut &mut *ask), || vec![].into());
                            if !held.is_empty() {
                                inner.ints.insert(nikaia_std::block::Text::from(name.to_string()));
                                for fact in held.iter() {
                                    let fact = nikaia_std::num::value(fact);
                                    bounding_push(&walk, &mut inner, fact);
                                }
                            }
                        }
                    },
                    _ => { },
                }
                bounding_maybe_expr(walk, (arm.guard).as_ref(), &mut inner, context, program, words, &mut &mut *ask);
                let mut leaves = false;
                match &arm.body {
                    Expr::Block(block, _) => { leaves = bounding_block(walk, block, &mut inner, context, program, words, &mut &mut *ask); },
                    _ => { bounding_expr(walk, &arm.body, &mut inner, context, program, words, &mut &mut *ask); },
                }
                bounding_extend(&mut changed, &bounding_changed_in_expr(&arm.body, context, words));
                if !leaves {
                    ends.push(inner);
                    bound.push(hidden);
                }
            }
            bounding_after_change(walk, facts, &changed);
            bounding_match_join(walk, facts, &changed, &ends, &bound, &mut &mut *ask);
        },
        Expr::Closure { .. } => { },
        Expr::Spawn { .. } => { },
        Expr::Overlap(_, _) => { },
        Expr::Select(_, _) => { },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            bounding_derived_call(walk, expr, words.resolve(method), (path_of(receiver, words)).as_deref(), args, &facts, context, program, words, &mut &mut *ask);
            bounding_required(walk, expr, receiver, words.resolve(method), args, &facts, context, program, words, &mut &mut *ask);
            bounding_method_call(walk, expr, receiver, words.resolve(method), args, facts, context, program, words, &mut &mut *ask);
        },
        Expr::SafeMethod { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            bounding_derived_call(walk, expr, words.resolve(method), (path_of(receiver, words)).as_deref(), args, &facts, context, program, words, &mut &mut *ask);
            bounding_method_call(walk, expr, receiver, words.resolve(method), args, facts, context, program, words, &mut &mut *ask);
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            let called = bounding_variable(func, words);
            if called.is_some() { bounding_derived_call(walk, expr, nikaia_std::index::or(called.as_deref(), || ""), None, args, &facts, context, program, words, &mut &mut *ask); }
            bounding_expr(walk, func, facts, context, program, words, &mut &mut *ask);
            for arg in args.iter() { bounding_expr(walk, arg, facts, context, program, words, &mut &mut *ask); }
            for c in config.iter() { bounding_expr(walk, &c.value, facts, context, program, words, &mut &mut *ask); }
            let loaded = nikaia_std::index::or(*nikaia_std::index::get(&context.simd_loads, &(node_key(func))), || 0);
            if loaded != 0 && args.len() == 2 {
                let list = path_of(unsafe { nikaia_std::proven::read(&args, (0) as usize) }, words);
                let read = if loaded < 0 { -loaded } else { loaded };
                if list.is_some() && bounding_word_inside(walk, nikaia_std::index::or(list.as_deref(), || ""), node_key(unsafe { nikaia_std::proven::read(&args, (0) as usize) }), unsafe { nikaia_std::proven::read(&args, (1) as usize) }, read, &facts, context, program, words, &mut &mut *ask) { walk.proven.indices.insert(node_key(func)); } else { walk.open += 1; }
            }
            let claimed = nikaia_std::index::or(bounding_variable(func, words), || "".into());
            if args.len() == 1 && (claimed == "assert" || claimed == "assume") { bounding_assume(walk, facts, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, context, program, words); }
            let frame = called_function_frame(func, context, words);
            let callee = callee_params(func, &context.around, words);
            let handing = !context.wide_calls.contains_key(&node_key(func));
            if walk.checking && loaded == 0 {
                let mut handed: Vec<String> = vec![];
                for at in 0..args.len() as i64 { if hands_on((callee).as_ref(), at) && handing { handed.push(match path_of(unsafe { nikaia_std::proven::read(&args, (at) as usize) }, words) { Some(__nikaia_value) => __nikaia_value, None => continue }); } }
                let changed = rules_changed_by((frame).as_ref(), None, &frame_handed(args, words), &handed);
                rules_at_call(walk, expr, None, &claimed, args, &changed, &facts, context, program, words, &mut &mut *ask);
            }
            if frame.is_some() && loaded == 0 {
                bounding_by_frame(walk, facts, &nikaia_std::index::or(frame, || nothing_changed().into()), func, args, words);
                return;
            }
            for at in 0..args.len() as i64 {
                let handed = match path_of(unsafe { nikaia_std::proven::read(&args, (at) as usize) }, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
                if hands_on((callee).as_ref(), at) && handing && loaded == 0 { bounding_forget(&walk, facts, &handed); }
            }
        },
        _ => { bounding_children(walk, expr, facts, context, program, words, &mut &mut *ask); },
    }
}

pub(crate) fn bounding_nonnegative(walk: &mut BoundsWalk, expr: &Expr, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if walk.collecting || context.nonnegative.is_empty() { return; }
    let node = node_key(expr);
    if !context.nonnegative.contains(&node) { return; }
    let term = match bounding_lin(walk, expr, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return };
    let zero = walk.arena.int(0);
    let goal = walk.arena.ge(term, zero);
    if bounding_proves_goal(walk, facts, goal, &mut *ask) { walk.proven.nonnegative.insert(node); } else { walk.open += 1; }
}

pub(crate) fn bounding_maybe_expr(walk: &mut BoundsWalk, expr: Option<&Expr>, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_expr(walk, present, facts, context, program, words, &mut &mut *ask);
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_else(walk: &mut BoundsWalk, else_branch: Option<&Block>, cond: &Expr, facts: &BoundsFacts, changed: &mut BoundsChanged, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let block = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut else_facts = facts.clone();
    bounding_assume_not(walk, &mut else_facts, cond, context, program, words);
    bounding_block(walk, block, &mut else_facts, context, program, words, &mut &mut *ask);
    bounding_extend(changed, &bounding_changed(block, context, words));
}

pub(crate) fn bounding_if_join(walk: &mut BoundsWalk, facts: &mut BoundsFacts, changed: &BoundsChanged, then_facts: &BoundsFacts, else_facts: &BoundsFacts, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if changed.values.is_empty() && changed.lengths.is_empty() { return; }
    let mut kept: Vec<i64> = vec![];
    for fact in bounding_join_candidates(walk, &facts, changed, then_facts) { if else_facts.facts.contains(&fact) || bounding_proves(&walk, else_facts, fact, &mut *ask) { kept.push(fact); } }
    for fact in bounding_join_candidates(walk, &facts, changed, else_facts) { if !kept.contains(&fact) && bounding_proves(&walk, then_facts, fact, &mut *ask) { kept.push(fact); } }
    bounding_emptied_join(walk, &facts, changed, then_facts, else_facts, &mut kept);
    bounding_emptied_join(walk, &facts, changed, else_facts, then_facts, &mut kept);
    for fact in kept.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
}

pub(crate) fn bounding_match_join(walk: &mut BoundsWalk, facts: &mut BoundsFacts, changed: &BoundsChanged, ends: &[BoundsFacts], bound: &[Vec<String>], ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if changed.values.is_empty() && changed.lengths.is_empty() || ends.len() < 2 { return; }
    let mut kept: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for k in 0..ends.len() as i64 {
        for fact in bounding_join_candidates(walk, &facts, changed, unsafe { nikaia_std::proven::read(&ends, (k) as usize) }) {
            if kept.contains(&fact) { continue; }
            let mut own = false;
            for name in (*nikaia_std::index::get(&bound, (k) as usize)).iter() { if bounding_touches(&walk, fact, name) { own = true; } }
            let mut every = !own;
            for j in 0..ends.len() as i64 {
                if !every || j == k || unsafe { nikaia_std::proven::read(&ends, (j) as usize) }.facts.contains(&fact) { continue; }
                every = bounding_proves(&walk, unsafe { nikaia_std::proven::read(&ends, (j) as usize) }, fact, &mut *ask);
            }
            if every { kept.push(fact); }
        }
    }
    for fact in kept.iter() {
        let fact = nikaia_std::num::value(fact);
        bounding_push(&walk, facts, fact);
    }
}

pub(crate) fn bounding_emptied_join(walk: &mut BoundsWalk, facts: &BoundsFacts, changed: &BoundsChanged, pinning: &BoundsFacts, other: &BoundsFacts, kept: &mut Vec<i64>) {
    let pins = bounding_pinned_lengths(&walk, facts, changed, pinning);
    if pins.is_empty() { return; }
    let mut own: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for fact in bounding_join_candidates(walk, facts, changed, other) { if !kept.contains(&fact) && !pins.contains(&fact) { own.push(fact); } }
    while (own.len() as i64) > most_flagged() { own.remove(0); }
    for pin in pins.iter() {
        let pin = nikaia_std::num::value(pin);
        for fact in own.iter() {
            let fact = nikaia_std::num::value(fact);
            let either = walk.arena.or(vec![pin, fact]);
            if !kept.contains(&either) && !facts.facts.contains(&either) { kept.push(either); }
        }
    }
}

pub(crate) fn bounding_pinned_lengths(walk: &BoundsWalk, facts: &BoundsFacts, changed: &BoundsChanged, branch: &BoundsFacts) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    for fact in branch.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if facts.facts.contains(&fact) { continue; }
        match walk.arena.at(fact) {
            logic::SolverTerm::Eq(a, b) => {
                let mut name: Option<String> = None;
                let mut value: Option<i64> = None;
                match walk.arena.at(a) {
                    logic::SolverTerm::Var(ref v) => {
                        name = Some(nikaia_std::block::Text::from(v.to_string()));
                        value = walk.arena.constant(b);
                    },
                    _ => {
                        match walk.arena.at(b) {
                            logic::SolverTerm::Var(ref v) => {
                                name = Some(nikaia_std::block::Text::from(v.to_string()));
                                value = walk.arena.constant(a);
                            },
                            _ => { },
                        }
                    },
                }
                let n = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                if value.is_none() { continue; }
                let list = match n.strip_suffix(".len()") { Some(__nikaia_value) => __nikaia_value, None => continue };
                if changed.values.contains(list) || changed.lengths.contains(list) { out.push(fact); }
            },
            _ => { },
        }
    }
    out
}

pub(crate) fn bounding_join_candidates(walk: &mut BoundsWalk, facts: &BoundsFacts, changed: &BoundsChanged, branch: &BoundsFacts) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    for fact in branch.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        if facts.facts.contains(&fact) || out.contains(&fact) { continue; }
        let mut touched = false;
        for name in changed.values.iter() {
            if bounding_touches(&walk, fact, name) {
                touched = true;
                break;
            }
        }
        for name in changed.lengths.iter() { if !touched && bounding_touches(&walk, fact, &length_of(name)) { touched = true; } }
        if touched { out.push(fact); }
    }
    let pinned = bounding_pinned(&walk, branch);
    if pinned.is_empty() { return out; }
    let mut settled: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for fact in out.iter() {
        let fact = nikaia_std::num::value(fact);
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        walk.arena.variables(fact, &mut read);
        let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        for v in read.iter() { if pinned.contains_key(v) { given.insert(nikaia_std::block::Text::from(v.to_string()), walk.arena.int(nikaia_std::index::or(*nikaia_std::index::get(&pinned, v), || 0))); } }
        if given.is_empty() { continue; }
        let plain = walk.arena.substitute(fact, &given);
        if !out.contains(&plain) && !settled.contains(&plain) && !facts.facts.contains(&plain) { settled.push(plain); }
    }
    out.reserve(settled.iter().size_hint().0); for fact in settled.iter() {
        let fact = nikaia_std::num::value(fact);
        out.push(fact);
    }
    out
}

pub(crate) fn bounding_pinned(walk: &BoundsWalk, branch: &BoundsFacts) -> collections::BTreeMap<String, i64> {
    let mut out: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for fact in branch.facts.iter() {
        let fact = nikaia_std::num::value(fact);
        match walk.arena.at(fact) {
            logic::SolverTerm::Eq(a, b) => {
                let mut name: Option<String> = None;
                let mut value: Option<i64> = None;
                match walk.arena.at(a) {
                    logic::SolverTerm::Var(ref v) => {
                        name = Some(nikaia_std::block::Text::from(v.to_string()));
                        value = walk.arena.constant(b);
                    },
                    _ => {
                        match walk.arena.at(b) {
                            logic::SolverTerm::Var(ref v) => {
                                name = Some(nikaia_std::block::Text::from(v.to_string()));
                                value = walk.arena.constant(a);
                            },
                            _ => { },
                        }
                    },
                }
                let n = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let k = match value { Some(__nikaia_value) => __nikaia_value, None => continue };
                if n.contains('#') { out.insert(n, k); }
            },
            _ => { },
        }
    }
    out
}

pub(crate) fn bounding_inner_block(walk: &mut BoundsWalk, block: &Block, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let mut inner = facts.clone();
    bounding_block(walk, block, &mut inner, context, program, words, &mut &mut *ask);
    let changed = bounding_changed(block, context, words);
    bounding_after_change(walk, facts, &changed);
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_binary(walk: &mut BoundsWalk, op: &BinaryOp, lhs: &Expr, rhs: &Expr, at: i64, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    match op {
        BinaryOp::And => {
            bounding_expr(walk, lhs, facts, context, program, words, &mut &mut *ask);
            let mut right = facts.clone();
            bounding_assume(walk, &mut right, lhs, context, program, words);
            bounding_expr(walk, rhs, &mut right, context, program, words, &mut &mut *ask);
            let changed = bounding_changed_in_expr(rhs, context, words);
            bounding_after_change(walk, facts, &changed);
            return;
        },
        BinaryOp::Or => {
            bounding_expr(walk, lhs, facts, context, program, words, &mut &mut *ask);
            let mut right = facts.clone();
            bounding_assume_not(walk, &mut right, lhs, context, program, words);
            bounding_expr(walk, rhs, &mut right, context, program, words, &mut &mut *ask);
            let changed = bounding_changed_in_expr(rhs, context, words);
            bounding_after_change(walk, facts, &changed);
            return;
        },
        _ => { },
    }
    bounding_expr(walk, lhs, facts, context, program, words, &mut &mut *ask);
    bounding_expr(walk, rhs, facts, context, program, words, &mut &mut *ask);
    let shifted = *nikaia_std::index::get(&context.shifts, &at);
    if shifted.is_some() && !bounding_literal(rhs) {
        if !walk.collecting && bounding_count_fits(walk, rhs, nikaia_std::index::or(shifted, || ""), &facts, context, program, words, &mut &mut *ask) { walk.proven.arithmetic.insert(at); } else if !walk.collecting { walk.open += 1; }
        return;
    }
    let divided = *nikaia_std::index::get(&context.divisions, &at);
    if divided.is_some() {
        if !walk.collecting && bounding_divides(walk, lhs, rhs, nikaia_std::index::or(divided, || ""), &facts, context, program, words, &mut &mut *ask) { walk.proven.arithmetic.insert(at); }
        return;
    }
    let arithmetic = matches!(op, BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul);
    if !arithmetic || walk.collecting { return; }
    let ty = match *nikaia_std::index::get(&context.arithmetic, &at) { Some(__nikaia_value) => __nikaia_value, None => return };
    if bounding_fits(walk, op, lhs, rhs, ty, &facts, context, program, words, &mut &mut *ask) { walk.proven.arithmetic.insert(at); } else { walk.open += 1; }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_method_call(walk: &mut BoundsWalk, call: &Expr, receiver: &Expr, method: &str, args: &[Expr], facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    bounding_expr(walk, receiver, facts, context, program, words, &mut &mut *ask);
    for arg in args.iter() { bounding_expr(walk, arg, facts, context, program, words, &mut &mut *ask); }
    let written = writes_a_value(method, args.len() as i64);
    if written.is_some() {
        let key = elements_key(&walk.shape, receiver, words);
        if key.is_some() { bounding_write(walk, nikaia_std::index::or(key.as_deref(), || ""), nikaia_std::index::get(&args, nikaia_std::index::at(nikaia_std::index::or(written, || 0))), &facts, context, program, words, &mut &mut *ask); }
    }
    let frame = called_frame(call, method, context);
    let receiver_path = path_of(receiver, words);
    if walk.checking {
        let mut handed: Vec<String> = vec![];
        if context.around.changing_receivers.contains(method) { handed.push(nikaia_std::index::or(path_of(receiver, words), || nikaia_std::index::or(rules_inner_of(receiver, words), || "self".into()).into())); }
        if context.around.changing_methods.contains(method) { handed.reserve(args.iter().size_hint().0); for arg in args.iter() { handed.push(match path_of(arg, words) { Some(__nikaia_value) => __nikaia_value, None => continue }); } }
        let changed = rules_changed_by((frame).as_ref(), (receiver_path).as_deref(), &frame_handed(args, words), &handed);
        rules_at_call(walk, call, (receiver_path).as_deref(), method, args, &changed, &facts, context, program, words, &mut &mut *ask);
    }
    if frame.is_some() {
        let known = nikaia_std::index::or(frame, || nothing_changed().into());
        bounding_by_frame(walk, facts, &known, receiver, args, words);
        let written = frame_at_call(&known, (receiver_path).as_deref(), &frame_handed(args, words));
        rules_after_call(walk, facts, call, (path_of(receiver, words)).as_deref(), context, false, &written);
        return;
    }
    if context.around.changing_receivers.contains(method) || !keeps_length(method) { bounding_forget_aliases(&walk, facts, receiver, words); }
    if receiver_path.is_some() {
        let name = nikaia_std::index::or(receiver_path, || "".into());
        let width = bytes_word_width(method);
        if width > 0 && args.len() == 1 { if bounding_word_inside(walk, &name, node_key(receiver), unsafe { nikaia_std::proven::read(&args, (0) as usize) }, width, &facts, context, program, words, &mut &mut *ask) { walk.proven.indices.insert(node_key(receiver)); } else { walk.open += 1; } }
        let left = rules_truncated(walk, &facts, &name, method, args, context, program, words, &mut &mut *ask);
        if context.around.changing_receivers.contains(method) || !keeps_length(method) { bounding_forget_parts(&walk, facts, &name); } else if !keeps_items(method) { bounding_forget_element(&walk, facts, &format!("{}|*|", name), false); }
        bounding_method(walk, facts, &name, method, args, context, program, words, &mut &mut *ask);
        for fact in left.iter() {
            let fact = nikaia_std::num::value(fact);
            bounding_push(&walk, facts, fact);
        }
        rules_capped_call(walk, &name, method);
    }
    if context.around.changing_methods.contains(method) {
        for arg in args.iter() {
            bounding_forget_aliases(&walk, facts, arg, words);
            let text = match path_of(arg, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
            bounding_forget(&walk, facts, &text);
        }
    }
    rules_after_call(walk, facts, call, (path_of(receiver, words)).as_deref(), context, true, &nothing_changed());
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_method(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, method: &str, args: &[Expr], context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if keeps_length(method) || facts.ints.contains(name) { return; }
    let length = length_of(name);
    let count = args.len() as i64;
    if method == "push" && count == 1 || method == "insert" && count == 2 {
        let one = walk.arena.int(1);
        bounding_shift(walk, facts, &length, one);
        let len = walk.arena.var(&length);
        let fact = walk.arena.ge(len, one);
        bounding_push(&walk, facts, fact);
        return;
    }
    if (method == "remove" || method == "swap_remove") && count == 1 {
        let one = walk.arena.int(-1);
        bounding_shift(walk, facts, &length, one);
        return;
    }
    if method == "truncate" && count == 1 {
        let to = bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, &facts, context, program, words);
        if to.is_some() {
            let n = nikaia_std::index::or(to, || 0);
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            walk.arena.variables(n, &mut read);
            let len = walk.arena.var(&length);
            let within = walk.arena.le(n, len);
            if !read.contains(&length) && bounding_proves(&walk, &facts, within, &mut *ask) {
                bounding_forget_length(&walk, facts, name);
                let now = walk.arena.var(&length);
                let fact = walk.arena.equal(now, n);
                bounding_push(&walk, facts, fact);
                return;
            }
        }
    }
    if method == "clear" && count == 0 {
        bounding_forget_length(&walk, facts, name);
        let len = walk.arena.var(&length);
        let zero = walk.arena.int(0);
        let fact = walk.arena.equal(len, zero);
        bounding_push(&walk, facts, fact);
        return;
    }
    if method == "resize" && count == 2 {
        let to = bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, &facts, context, program, words);
        bounding_forget_length(&walk, facts, name);
        if to.is_some() {
            let len = walk.arena.var(&length);
            let fact = walk.arena.equal(len, nikaia_std::index::or(to, || 0));
            bounding_push(&walk, facts, fact);
        }
        return;
    }
    if method == "extend" && count == 1 {
        let other = nikaia_std::index::or(bounding_variable(unsafe { nikaia_std::proven::read(&args, (0) as usize) }, words), || "".into());
        if !other.is_empty() && other != name {
            let mine = walk.arena.var(&length);
            let theirs = walk.arena.var(&length_of(&other));
            let mine_known = bounding_term(walk, mine, &facts, &mut *ask);
            let theirs_known = bounding_term(walk, theirs, &facts, &mut *ask);
            bounding_forget_length(&walk, facts, name);
            let len = walk.arena.var(&length);
            if mine_known.lo.is_some() && theirs_known.lo.is_some() {
                let lo = nikaia_std::index::or(mine_known.lo, || 0).checked_add(nikaia_std::index::or(theirs_known.lo, || 0));
                if lo.is_some() {
                    let k = walk.arena.int(nikaia_std::index::or(lo, || 0));
                    let fact = walk.arena.ge(len, k);
                    bounding_push(&walk, facts, fact);
                }
            }
            if mine_known.hi.is_some() && theirs_known.hi.is_some() {
                let hi = nikaia_std::index::or(mine_known.hi, || 0).checked_add(nikaia_std::index::or(theirs_known.hi, || 0));
                if hi.is_some() {
                    let k = walk.arena.int(nikaia_std::index::or(hi, || 0));
                    let fact = walk.arena.le(len, k);
                    bounding_push(&walk, facts, fact);
                }
            }
            return;
        }
    }
    let known = facts.facts.len() as i64;
    bounding_forget_length(&walk, facts, name);
    if (facts.facts.len() as i64) < known {
        let len = walk.arena.var(&length);
        let zero = walk.arena.int(0);
        let fact = walk.arena.ge(len, zero);
        bounding_push(&walk, facts, fact);
    }
}

pub(crate) fn bounding_children(walk: &mut BoundsWalk, expr: &Expr, facts: &mut BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut dyn FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    match expr {
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            bounding_expr(walk, start, facts, context, program, words, &mut &mut *ask);
            bounding_expr(walk, end, facts, context, program, words, &mut &mut *ask);
        },
        Expr::Tuple(items, _) => { for item in items.iter() { bounding_expr(walk, item, facts, context, program, words, &mut &mut *ask); } },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            bounding_expr(walk, value, facts, context, program, words, &mut &mut *ask);
            bounding_expr(walk, count, facts, context, program, words, &mut &mut *ask);
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { bounding_expr(walk, item, facts, context, program, words, &mut &mut *ask); } },
        Expr::LitInterpolated { parts, .. } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { bounding_expr(walk, expr, facts, context, program, words, &mut &mut *ask); },
                    _ => { },
                }
            }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_expr(walk, base, facts, context, program, words, &mut &mut *ask); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); bounding_expr(walk, base, facts, context, program, words, &mut &mut *ask); },
        Expr::StructLit { name, fields, .. } => {
            let name = *name;
            for field in fields.iter() { bounding_maybe_expr(walk, (field.value).as_ref(), facts, context, program, words, &mut &mut *ask); }
            bounding_field_inits(walk, fields, &facts, context, program, words, &mut &mut *ask);
            if walk.checking && node_key(expr) != walk.rule_built_literal { rules_literal_holds(walk, words.resolve(name), fields, &facts, context, program, words, &mut &mut *ask); }
        },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            bounding_expr(walk, base, facts, context, program, words, &mut &mut *ask);
            for field in fields.iter() { bounding_maybe_expr(walk, (field.value).as_ref(), facts, context, program, words, &mut &mut *ask); }
            bounding_field_inits(walk, fields, &facts, context, program, words, &mut &mut *ask);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); bounding_expr(walk, expr, facts, context, program, words, &mut &mut *ask); },
        Expr::Try(inner, _) => {
            let inner = nikaia_std::boxed::open(inner);
            bounding_expr(walk, inner, facts, context, program, words, &mut &mut *ask);
            rules_exit(walk, &facts, None, true, context, program, words, &mut &mut *ask);
        },
        Expr::Async(inner, _, _, _) => { let inner = nikaia_std::boxed::open(inner); bounding_expr(walk, inner, facts, context, program, words, &mut &mut *ask); },
        Expr::Throw(inner, _) => {
            let inner = nikaia_std::boxed::open(inner);
            bounding_expr(walk, inner, facts, context, program, words, &mut &mut *ask);
            rules_exit(walk, &facts, None, true, context, program, words, &mut &mut *ask);
        },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); bounding_expr(walk, expr, facts, context, program, words, &mut &mut *ask); },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            bounding_expr(walk, expr, facts, context, program, words, &mut &mut *ask);
            bounding_inner_block(walk, handler, facts, context, program, words, &mut &mut *ask);
        },
        Expr::Return(value, _) => {
            let value = nikaia_std::boxed::open(value);
            bounding_maybe_expr(walk, (value).as_ref(), facts, context, program, words, &mut &mut *ask);
            rules_exit(walk, &facts, (value).as_ref(), false, context, program, words, &mut &mut *ask);
        },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            bounding_expr(walk, value, facts, context, program, words, &mut &mut *ask);
            bounding_expr(walk, fallback, facts, context, program, words, &mut &mut *ask);
        },
        _ => { },
    }
}

pub(crate) fn bounding_extend(changed: &mut BoundsChanged, other: &BoundsChanged) {
    changed.values.extend(other.values.iter().cloned());
    changed.lengths.extend(other.lengths.iter().cloned());
    changed.parts.extend(other.parts.iter().cloned());
    changed.jumps.extend(other.jumps.iter().cloned());
    changed.drops.extend(other.drops.iter().cloned());
    changed.falls.extend(other.falls.iter().cloned());
    changed.bare_falls.extend(other.bare_falls.iter().cloned());
    changed.elements.extend(other.elements.iter().cloned());
}

pub(crate) fn bounding_extend_maybe(changed: &mut BoundsChanged, block: Option<&Block>, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    bounding_extend(changed, &bounding_changed(present, context, words));
}

pub(crate) fn bounding_changed(block: &Block, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> BoundsChanged {
    let mut out = nothing_changed();
    changed_in_block(block, context, words, &mut out);
    out
}

pub(crate) fn bounding_changed_in_expr(expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> BoundsChanged {
    let mut out = nothing_changed();
    changed_in_expr(expr, context, words, &mut out);
    out
}

pub(crate) fn changed_in_block(block: &Block, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Assign { target, op, value } => {
                let written = path_of(target, words);
                if written.is_some() {
                    let name = nikaia_std::index::or(written, || "".into());
                    if !bounding_steps_up(&name, (op).as_ref(), value, words) { out.jumps.insert(nikaia_std::block::Text::from(name.to_string())); }
                    if !bounding_steps_down(&name, (op).as_ref(), value, words) { out.drops.insert(nikaia_std::block::Text::from(name.to_string())); }
                    out.lengths.insert(nikaia_std::block::Text::from(name.to_string()));
                    changed_falls(out, &name);
                    out.values.insert(name);
                }
                bounding_element_changed(target, words, out);
                changed_in_expr(target, context, words, out);
                changed_in_expr(value, context, words, out);
            },
            Stmt::For { iter, body, .. } => {
                changed_in_expr(iter, context, words, out);
                changed_in_block(body, context, words, out);
            },
            Stmt::While { cond, body } => {
                changed_in_expr(cond, context, words, out);
                changed_in_block(body, context, words, out);
            },
            Stmt::Let { value, .. } => { changed_in_expr(value, context, words, out); },
            Stmt::Comptime { value, .. } => { changed_in_expr(value, context, words, out); },
            Stmt::Expr(value) => { changed_in_expr(value, context, words, out); },
            Stmt::Return(value) => { changed_in_maybe((value).as_ref(), context, words, out); },
            _ => { },
        }
    }
}

pub(crate) fn changed_in_maybe(expr: Option<&Expr>, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return };
    changed_in_expr(present, context, words, out);
}

pub(crate) fn changed_in_all(exprs: &[Expr], context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) { for e in exprs.iter() { changed_in_expr(e, context, words, out); } }

pub(crate) fn changed_in_expr(expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    changed_by(expr, context, words, out);
    match expr {
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            changed_in_expr(value, context, words, out);
            for arm in arms.iter() {
                changed_in_maybe((arm.guard).as_ref(), context, words, out);
                changed_in_expr(&arm.body, context, words, out);
            }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            changed_in_expr(start, context, words, out);
            changed_in_expr(end, context, words, out);
        },
        Expr::Tuple(items, _) => { changed_in_all(items, context, words, out); },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            changed_in_expr(value, context, words, out);
            changed_in_expr(count, context, words, out);
        },
        Expr::ListLit { items, .. } => { changed_in_all(items, context, words, out); },
        Expr::LitInterpolated { parts, .. } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { changed_in_expr(expr, context, words, out); },
                    _ => { },
                }
            }
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            changed_in_expr(cond, context, words, out);
            changed_in_block(then_branch, context, words, out);
            changed_in_maybe_block((else_branch).as_ref(), context, words, out);
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            changed_in_expr(func, context, words, out);
            changed_in_all(args, context, words, out);
            for c in config.iter() { changed_in_expr(&c.value, context, words, out); }
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); changed_in_expr(body, context, words, out); },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            changed_in_expr(receiver, context, words, out);
            changed_in_all(args, context, words, out);
            for c in config.iter() { changed_in_expr(&c.value, context, words, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            changed_in_expr(receiver, context, words, out);
            changed_in_all(args, context, words, out);
            for c in config.iter() { changed_in_expr(&c.value, context, words, out); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); changed_in_expr(base, context, words, out); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); changed_in_expr(base, context, words, out); },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { changed_in_maybe((field.value).as_ref(), context, words, out); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            changed_in_expr(base, context, words, out);
            for field in fields.iter() { changed_in_maybe((field.value).as_ref(), context, words, out); }
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); changed_in_expr(expr, context, words, out); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); changed_in_expr(inner, context, words, out); },
        Expr::Async(inner, _, _, _) => { let inner = nikaia_std::boxed::open(inner); changed_in_expr(inner, context, words, out); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); changed_in_expr(inner, context, words, out); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); changed_in_expr(expr, context, words, out); },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            changed_in_expr(expr, context, words, out);
            changed_in_block(handler, context, words, out);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            changed_in_expr(lhs, context, words, out);
            changed_in_expr(rhs, context, words, out);
        },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); changed_in_maybe((value).as_ref(), context, words, out); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            changed_in_expr(base, context, words, out);
            changed_in_expr(index, context, words, out);
        },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            changed_in_expr(value, context, words, out);
            changed_in_expr(fallback, context, words, out);
        },
        Expr::Select(arms, _) => {
            for arm in arms.iter() {
                changed_in_expr(&arm.value, context, words, out);
                changed_in_block(&arm.body, context, words, out);
            }
        },
        Expr::Block(b, _) => { changed_in_block(b, context, words, out); },
        Expr::AsyncGroup(b, _, _, _, _) => { changed_in_block(b, context, words, out); },
        Expr::Overlap(b, _) => { changed_in_block(b, context, words, out); },
        Expr::Unsafe(b, _) => { changed_in_block(b, context, words, out); },
        Expr::Closure { body, .. } => { changed_in_block(body, context, words, out); },
        _ => { },
    }
}

pub(crate) fn changed_in_maybe_block(block: Option<&Block>, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    changed_in_block(present, context, words, out);
}

pub(crate) fn changed_by(expr: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    match expr {
        Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; changed_by_method(expr, receiver, words.resolve(method), args, context, words, out); },
        Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; changed_by_method(expr, receiver, words.resolve(method), args, context, words, out); },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let frame = called_function_frame(func, context, words);
            if frame.is_some() && !context.simd_loads.contains_key(&node_key(func)) {
                changed_by_frame(&nikaia_std::index::or(frame, || nothing_changed().into()), func, args, words, out);
                return;
            }
            let callee = callee_params(func, &context.around, words);
            for at in 0..args.len() as i64 {
                let handed = match path_of(unsafe { nikaia_std::proven::read(&args, (at) as usize) }, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
                if hands_on((callee).as_ref(), at) && !context.simd_loads.contains_key(&node_key(func)) {
                    out.lengths.insert(nikaia_std::block::Text::from(handed.to_string()));
                    changed_falls(out, &handed);
                    out.jumps.insert(nikaia_std::block::Text::from(handed.to_string()));
                    out.drops.insert(nikaia_std::block::Text::from(handed.to_string()));
                    out.values.insert(handed);
                }
            }
        },
        _ => { },
    }
}

pub(crate) fn changed_by_method(call: &Expr, receiver: &Expr, method: &str, args: &[Expr], context: &BoundsContext, words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    let frame = called_frame(call, method, context);
    if frame.is_some() {
        let mut got = nothing_changed();
        changed_by_frame(&nikaia_std::index::or(frame, || nothing_changed().into()), receiver, args, words, &mut got);
        let on = path_of(receiver, words);
        if on.is_some() {
            let root = nikaia_std::index::or(on, || "".into());
            let mut bare: collections::BTreeSet<String> = collections::BTreeSet::new();
            for path in got.bare_falls.iter() {
                let field = nikaia_std::index::or(match path.strip_prefix(&*root) {
                    Some(__nikaia_it) => __nikaia_it.strip_prefix("."),
                    None => None,
                }, || "");
                if field.is_empty() || field.contains('.') { bare.insert(nikaia_std::block::Text::from(path.to_string())); }
            }
            got.bare_falls = bare;
        }
        bounding_extend(out, &got);
        return;
    }
    if context.around.changing_receivers.contains(method) || !keeps_length(method) { bounding_element_changed(receiver, words, out); }
    let receiver_path = path_of(receiver, words);
    if receiver_path.is_some() {
        let name = nikaia_std::index::or(receiver_path, || "".into());
        if !keeps_length(method) {
            out.lengths.insert(nikaia_std::block::Text::from(name.to_string()));
            if !only_adds(method) { changed_falls(out, &name); }
        }
        if context.around.changing_receivers.contains(method) || !keeps_length(method) { out.parts.insert(name); } else if !keeps_items(method) { out.elements.insert(format!("{}|*|", name)); }
    }
    if context.around.changing_methods.contains(method) {
        for arg in args.iter() {
            bounding_element_changed(arg, words, out);
            let text = match path_of(arg, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
            out.values.insert(nikaia_std::block::Text::from(text.to_string()));
            out.jumps.insert(nikaia_std::block::Text::from(text.to_string()));
            out.drops.insert(nikaia_std::block::Text::from(text.to_string()));
            changed_falls(out, &text);
            out.lengths.insert(text);
        }
    }
}

pub(crate) fn called_frame(call: &Expr, method: &str, context: &BoundsContext) -> Option<BoundsChanged> {
    let owner = match context.std_receivers.get(&node_key(call)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match context.around.frames.get(&format!("{}::{}", owner, method)) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

pub(crate) fn called_function_frame(func: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Option<BoundsChanged> {
    let name = match bounding_variable(func, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match context.around.frames.get(&name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

pub(crate) fn frame_handed(args: &[Expr], words: &winnow_grammar::InternerContext) -> Vec<Option<String>> { args.iter().map(|arg| { path_of(arg, words) }).collect::<Vec<_>>() }

pub(crate) fn bounding_by_frame(walk: &mut BoundsWalk, facts: &mut BoundsFacts, frame: &BoundsChanged, on: &Expr, args: &[Expr], words: &winnow_grammar::InternerContext) {
    if frame_writes(frame, "#self") { bounding_forget_aliases(&walk, facts, on, words); }
    for (at, arg) in args.iter().enumerate().map(|(at, item)| (at as i64, item)) { if frame_writes(frame, &format!("#{}", at)) { bounding_forget_aliases(&walk, facts, arg, words); } }
    let changed = frame_at_call(frame, (path_of(on, words)).as_deref(), &frame_handed(args, words));
    bounding_after_change(walk, facts, &changed);
}

pub(crate) fn changed_by_frame(frame: &BoundsChanged, on: &Expr, args: &[Expr], words: &winnow_grammar::InternerContext, out: &mut BoundsChanged) {
    if frame_writes(frame, "#self") { bounding_element_changed(on, words, out); }
    for (at, arg) in args.iter().enumerate().map(|(at, item)| (at as i64, item)) { if frame_writes(frame, &format!("#{}", at)) { bounding_element_changed(arg, words, out); } }
    bounding_extend(out, &frame_at_call(frame, (path_of(on, words)).as_deref(), &frame_handed(args, words)));
}

pub(crate) fn bounds_returns(context: &mut BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    let mut assumed: collections::BTreeMap<String, BoundsReturns> = collections::BTreeMap::new();
    let mut bodies: Vec<&Spanned<Item>> = vec![];
    #[allow(unused_mut)] let mut keys: Vec<String> = vec![];
    let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut twice: collections::BTreeSet<String> = collections::BTreeSet::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut keys = keys;
    let mut list_fields: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut keys = keys;
    let mut whole_fields: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut keys = keys;
    for item in program.items.iter() {
        match &item.node {
            Item::Struct { name, generics, fields, .. } => {
                let name = *name;
                if !generics.is_empty() { continue; }
                #[allow(unused_mut)] let mut lists: Vec<String> = vec![];
                let mut wholes: Vec<String> = vec![]; #[allow(unused_mut, clippy::redundant_locals)] let mut lists = lists;
                for field in fields.iter() { if bounding_is_list_type(&field.ty, words) { lists.push(nikaia_std::block::Text::from(words.resolve(field.name).to_string())); } else if !nikaia_std::index::or(bounding_returns_each(&field.ty, words), || true) { wholes.push(nikaia_std::block::Text::from(words.resolve(field.name).to_string())); } }
                list_fields.insert(nikaia_std::block::Text::from(words.resolve(name).to_string()), lists);
                whole_fields.insert(nikaia_std::block::Text::from(words.resolve(name).to_string()), wholes);
            },
            _ => { },
        }
    }
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, receiver, .. } => {
                let name = *name;
                if receiver.is_none() {
                    let named = nikaia_std::block::Text::from(words.resolve(match name { Some(__nikaia_value) => __nikaia_value, None => continue }).to_string());
                    if seen.contains(&named) { twice.insert(named); } else { seen.insert(named); }
                }
            },
            _ => { },
        }
    }
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, generics, receiver, args, config, spread, ret_type, .. } => {
                let name = *name; let spread = *spread;
                if receiver.is_some() || !config.is_empty() || spread.is_some() || !generics.is_empty() { continue; }
                let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                if twice.contains(words.resolve(symbol)) { continue; }
                let ret = match ret_type { Some(__nikaia_value) => __nikaia_value, None => continue };
                let kind = bounding_returns_kind(ret, words);
                let measures = bounding_returns_measures(ret, &list_fields, words);
                let mut projections: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block); #[allow(clippy::redundant_locals)] let measures = measures;
                if kind.is_none() { projections = bounding_struct_wholes(ret, &whole_fields, words); }
                if kind.is_none() && measures.is_empty() && projections.is_empty() { continue; }
                let each = nikaia_std::index::or(kind, || false);
                let mut below: collections::BTreeSet<i64> = collections::BTreeSet::new();
                let mut at_least: collections::BTreeSet<i64> = collections::BTreeSet::new();
                if kind.is_some() || !projections.is_empty() { for k in 0..args.len() as i64 { if bounding_is_list_type(&unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty, words) { below.insert(k); } else if !each && unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.generics.is_empty() && is_whole_number(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.name)) { at_least.insert(k); } } }
                let within = if each { collections::BTreeSet::new() } else { below.copy_owned() };
                if kind.is_some() || !measures.is_empty() {
                    let key = nikaia_std::block::Text::from(words.resolve(symbol).to_string());
                    let mut found = BoundsReturns { each, below: below.copy_owned(), sized: collections::BTreeSet::new(), range: None, pending: true, at_least: at_least.copy_owned(), within: within.copy_owned(), under: within.copy_owned(), fields: vec![], plain: kind.is_some(), measures: vec![], lengths: collections::BTreeMap::new(), reaches: collections::BTreeMap::new(), listed: collections::BTreeSet::new(), alike: collections::BTreeSet::new(), guards: collections::BTreeSet::new(), projected: String::from("") };
                    if kind.is_none() {
                        found.below = collections::BTreeSet::new();
                        found.at_least = collections::BTreeSet::new();
                        found.within = collections::BTreeSet::new();
                        found.under = collections::BTreeSet::new();
                    }
                    bounding_returns_measured(&mut found, &measures, args, words);
                    assumed.insert(nikaia_std::block::Text::from(key.to_string()), found);
                    bodies.push(item);
                    keys.push(key);
                }
                for projected in projections.iter() {
                    let key = bounding_projected_key(&nikaia_std::block::Text::from(words.resolve(symbol).to_string()), projected);
                    assumed.insert(nikaia_std::block::Text::from(key.to_string()), BoundsReturns { each: false, below: below.copy_owned(), sized: collections::BTreeSet::new(), range: None, pending: true, at_least: at_least.copy_owned(), within: within.copy_owned(), under: within.copy_owned(), fields: vec![], plain: true, measures: vec![], lengths: collections::BTreeMap::new(), reaches: collections::BTreeMap::new(), listed: collections::BTreeSet::new(), alike: collections::BTreeSet::new(), guards: collections::BTreeSet::new(), projected: nikaia_std::block::Text::from(projected.to_string()) });
                    bodies.push(item);
                    keys.push(key);
                }
            },
            Item::Impl { trait_name, target, methods } => {
                let trait_name = *trait_name;
                if trait_name.is_some() || !target.generics.is_empty() { continue; }
                let owner = nikaia_std::block::Text::from(words.resolve(target.name).to_string());
                let lists = match match list_fields.get(&owner) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                } { Some(__nikaia_value) => __nikaia_value, None => continue };
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, generics, receiver, args, config, spread, ret_type, .. } => {
                            let name = *name; let spread = *spread;
                            let taken = match receiver { Some(__nikaia_value) => __nikaia_value, None => continue };
                            if !config.is_empty() || spread.is_some() || !generics.is_empty() || taken.is_keep { continue; }
                            let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                            let ret = match ret_type { Some(__nikaia_value) => __nikaia_value, None => continue };
                            let kind = bounding_returns_kind(ret, words);
                            let measures = bounding_returns_measures(ret, &list_fields, words);
                            let mut projections: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block); #[allow(clippy::redundant_locals)] let measures = measures;
                            if kind.is_none() { projections = bounding_struct_wholes(ret, &whole_fields, words); }
                            if kind.is_none() && measures.is_empty() && projections.is_empty() { continue; }
                            let each = nikaia_std::index::or(kind, || false);
                            let mut below: collections::BTreeSet<i64> = collections::BTreeSet::new();
                            let mut at_least: collections::BTreeSet<i64> = collections::BTreeSet::new();
                            let mut within: collections::BTreeSet<i64> = collections::BTreeSet::new();
                            if kind.is_some() || !projections.is_empty() {
                                for k in 0..args.len() as i64 { if bounding_is_list_type(&unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty, words) { below.insert(k); } else if !each && unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.generics.is_empty() && is_whole_number(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.name)) { at_least.insert(k); } }
                                within = if each { collections::BTreeSet::new() } else { below.copy_owned() };
                                for j in 0..lists.len() as i64 {
                                    below.insert(unsafe { nikaia_std::proven::add::<i64>(args.len() as i64, j) });
                                    if !each && !taken.is_mut { within.insert(unsafe { nikaia_std::proven::add::<i64>(args.len() as i64, j) }); }
                                }
                            }
                            if kind.is_some() || !measures.is_empty() {
                                let key = format!("{}.{}", owner, words.resolve(symbol));
                                let mut found = BoundsReturns { each, below: below.copy_owned(), sized: collections::BTreeSet::new(), range: None, pending: true, at_least: at_least.copy_owned(), within: within.copy_owned(), under: within.copy_owned(), fields: lists.copy_owned(), plain: kind.is_some(), measures: vec![], lengths: collections::BTreeMap::new(), reaches: collections::BTreeMap::new(), listed: collections::BTreeSet::new(), alike: collections::BTreeSet::new(), guards: collections::BTreeSet::new(), projected: String::from("") };
                                if kind.is_none() {
                                    found.below = collections::BTreeSet::new();
                                    found.at_least = collections::BTreeSet::new();
                                    found.within = collections::BTreeSet::new();
                                    found.under = collections::BTreeSet::new();
                                }
                                bounding_returns_measured(&mut found, &measures, args, words);
                                assumed.insert(nikaia_std::block::Text::from(key.to_string()), found);
                                bodies.push(method);
                                keys.push(key);
                            }
                            for projected in projections.iter() {
                                let key = bounding_projected_key(&format!("{}.{}", owner, words.resolve(symbol)), projected);
                                assumed.insert(nikaia_std::block::Text::from(key.to_string()), BoundsReturns { each: false, below: below.copy_owned(), sized: collections::BTreeSet::new(), range: None, pending: true, at_least: at_least.copy_owned(), within: within.copy_owned(), under: within.copy_owned(), fields: lists.copy_owned(), plain: true, measures: vec![], lengths: collections::BTreeMap::new(), reaches: collections::BTreeMap::new(), listed: collections::BTreeSet::new(), alike: collections::BTreeSet::new(), guards: collections::BTreeSet::new(), projected: nikaia_std::block::Text::from(projected.to_string()) });
                                bodies.push(method);
                                keys.push(key);
                            }
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    if assumed.is_empty() { return; }
    for (name, wanted) in assumed.iter() { if wanted.each { context.around.returning.insert(nikaia_std::block::Text::from(name.to_string())); } }
    let mut walked: collections::BTreeMap<String, ReturnsWalked> = collections::BTreeMap::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut keys = keys;
    let mut measured: collections::BTreeMap<String, ReturnsMeasured> = collections::BTreeMap::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut keys = keys;
    context.returns = assumed.copy_owned();
    let mut collected = bounding_returns_round(context, &bodies, &keys, &assumed, program, words, &mut *ask, &mut walked, &mut measured);
    for _more in 0..assumed.len() as i64 {
        let mut known = assumed.copy_owned();
        for (name, found) in collected.iter() {
            if !found.each && found.range.is_some() {
                let mut next = found.clone();
                next.pending = false;
                known.insert(nikaia_std::block::Text::from(name.to_string()), next);
            }
        }
        context.returns = known.copy_owned();
        let again = bounding_returns_round(context, &bodies, &keys, &known, program, words, &mut *ask, &mut walked, &mut measured);
        let before = bounding_returns_ranged(&collected);
        collected = again;
        if bounding_returns_ranged(&collected) == before { break; }
    }
    let mut started: collections::BTreeMap<String, BoundsReturns> = collections::BTreeMap::new();
    for (name, wanted) in assumed.iter() {
        let mut next = wanted.clone();
        next.pending = false;
        next.range = match collected.get(name).and_then(|__nikaia_it| __nikaia_it.range.as_ref()) {
            Some(__nikaia_it) => Some(__nikaia_it.copy_owned()),
            None => None,
        };
        started.insert(nikaia_std::block::Text::from(name.to_string()), next);
    }
    assumed = started;
    let rounds = bounding_returns_count(&assumed) + 1;
    for _round in 0..rounds {
        context.returns = assumed.copy_owned();
        let found = bounding_returns_round(context, &bodies, &keys, &assumed, program, words, &mut *ask, &mut walked, &mut measured);
        if bounding_returns_count(&found) == bounding_returns_count(&assumed) {
            bounding_returns_settle(context, found);
            return;
        }
        assumed = found;
    }
    bounding_returns_settle(context, collections::BTreeMap::new());
}

pub(crate) fn bounding_returns_settle(context: &mut BoundsContext, found: collections::BTreeMap<String, BoundsReturns>) {
    context.around.returning.clear();
    for (name, wanted) in found.iter() { if wanted.each { context.around.returning.insert(nikaia_std::block::Text::from(name.to_string())); } }
    context.returns = found;
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct ReturnsWalked {
    pub(crate) asked: BoundsReturns,
    pub(crate) reads: collections::BTreeMap<String, BoundsReturns>,
    pub(crate) rules: Vec<BoundsRule>,
    pub(crate) returned: Option<collections::BTreeSet<i64>>,
    pub(crate) sized: collections::BTreeSet<i64>,
    pub(crate) range: Option<Range>,
    pub(crate) related: bool,
    pub(crate) at_least: collections::BTreeSet<i64>,
    pub(crate) within: collections::BTreeSet<i64>,
    pub(crate) under: collections::BTreeSet<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct ReturnsMeasured {
    pub(crate) lengths_asked: collections::BTreeMap<String, collections::BTreeSet<i64>>,
    pub(crate) alike_asked: collections::BTreeSet<String>,
    pub(crate) listed: collections::BTreeSet<i64>,
    pub(crate) reads: collections::BTreeMap<String, BoundsReturns>,
    pub(crate) rules: Vec<BoundsRule>,
    pub(crate) lengths: collections::BTreeMap<String, collections::BTreeSet<i64>>,
    pub(crate) reaches: collections::BTreeMap<String, collections::BTreeSet<i64>>,
    pub(crate) alike: collections::BTreeSet<String>,
    pub(crate) guards: collections::BTreeSet<i64>,
}

pub(crate) fn bounding_returns_asked(wanted: &BoundsReturns) -> BoundsReturns {
    let mut asked = wanted.clone();
    asked.pending = false;
    asked.range = None;
    asked.under = collections::BTreeSet::new();
    asked.sized = collections::BTreeSet::new();
    asked.measures = vec![];
    asked.lengths = collections::BTreeMap::new();
    asked.reaches = collections::BTreeMap::new();
    asked.listed = collections::BTreeSet::new();
    asked.alike = collections::BTreeSet::new();
    asked.guards = collections::BTreeSet::new();
    asked
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_returns_round(context: &mut BoundsContext, bodies: &[&Spanned<Item>], keys: &[String], assumed: &collections::BTreeMap<String, BoundsReturns>, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool, walked: &mut collections::BTreeMap<String, ReturnsWalked>, measured: &mut collections::BTreeMap<String, ReturnsMeasured>) -> collections::BTreeMap<String, BoundsReturns> {
    let mut found: collections::BTreeMap<String, BoundsReturns> = collections::BTreeMap::new();
    context.around.held.clear();
    for at in 0..bodies.len() as i64 {
        let item = *unsafe { nikaia_std::proven::read(&bodies, (at) as usize) };
        match &item.node {
            Item::Fn { args, body, receiver, .. } => {
                let key = nikaia_std::block::Text::from((*nikaia_std::index::get(&keys, (at) as usize)).to_string());
                let wanted = match assumed.get(&key) { Some(__nikaia_value) => __nikaia_value, None => continue };
                let taken_mut = nikaia_std::index::or(receiver.as_ref().map(|__nikaia_it| __nikaia_it.is_mut), || false);
                #[allow(unused_mut)] let mut walk = bounding_new(args, body, bp_names(&nonnegative_locals(body), words), &context, program, words);
                for k in 0..args.len() as i64 {
                    let param = nikaia_std::block::Text::from(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.name).to_string());
                    if wanted.below.contains(&k) && walk.lists.contains(&param) { walk.return_params.push(param); } else { walk.return_params.push(String::from("")); }
                }
                for field in wanted.fields.iter() {
                    let k = walk.return_params.len() as i64;
                    walk.return_params.push(if wanted.below.contains(&k) { format!("self.{}", field) } else { String::from("") });
                }
                walk.return_each = wanted.each && wanted.plain;
                walk.return_ranging = !wanted.each && wanted.plain;
                walk.return_field = nikaia_std::block::Text::from(wanted.projected.to_string());
                for k in 0..args.len() as i64 {
                    let param = nikaia_std::block::Text::from(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.name).to_string());
                    let mut scalar: String = String::from("");
                    let mut list: String = String::from("");
                    if wanted.at_least.contains(&k) && !seek_block(body, &Seek::Rebound(nikaia_std::block::Text::from(param.to_string())), words) { scalar = nikaia_std::block::Text::from(param.to_string()); }
                    let stays = if unsafe { nikaia_std::proven::read(&args, (k) as usize) }.mutable { length_stays(body, &param, words) } else { !seek_block(body, &Seek::Rebound(nikaia_std::block::Text::from(param.to_string())), words) };
                    if wanted.within.contains(&k) && walk.lists.contains(&param) && stays { list = nikaia_std::block::Text::from(param.to_string()); }
                    walk.return_scalars.push(scalar);
                    walk.return_lens.push(list);
                }
                for field in wanted.fields.iter() {
                    let k = walk.return_lens.len() as i64;
                    walk.return_scalars.push(String::from(""));
                    walk.return_lens.push(if wanted.within.contains(&k) && !taken_mut { format!("self.{}", field) } else { String::from("") });
                }
                let mut found_checked: collections::BTreeMap<String, RulesChecked> = collections::BTreeMap::new(); #[allow(unused_mut, clippy::redundant_locals)] let mut walk = walk;
                let found_held = rules_settle(&mut walk, args, body, &context, program, words, &mut *ask, &mut found_checked);
                for (of, holding) in found_held.iter() { context.around.held.insert(nikaia_std::block::Text::from(of.to_string()), holding.copy_owned()); }
                rules_checked_keep(context, &found_checked);
                let reads = rules_returns_read(body, &context, words);
                let rules = walk.rules.copy_owned();
                let fresh = context.trace.is_empty();
                let asked = bounding_returns_asked(wanted);
                let mut seen: Option<ReturnsWalked> = None;
                if fresh && walked.contains_key(&key) {
                    let got = match walked.get(&key) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    if got.asked == asked && got.reads == reads && got.rules == rules { seen = Some(got.clone()); }
                }
                if seen.is_none() {
                    let proven = bounds_rounds_settled(&mut walk, &found_held, &found_checked, args, body, &context, program, words, &mut *ask);
                    let returned = proven.returned.is_some();
                    let mut sized_seen: collections::BTreeSet<i64> = collections::BTreeSet::new();
                    for k in nikaia_std::index::or(match proven.returned.as_ref() {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || collections::BTreeSet::new().into()) { if wanted.below.contains(&k) && walk.axioms.contains_key(&length_of(nikaia_std::index::get(&walk.return_params, nikaia_std::index::at(k)))) { sized_seen.insert(k); } }
                    let mut range_seen: Option<Range> = None;
                    if wanted.each && returned { range_seen = bounding_returned_range(&walk); }
                    if !wanted.each && !walk.return_unranged && !walk.return_lost && !seek_block(body, &Seek::Unvisited(walk.return_seen.copy_owned()), words) {
                        range_seen = match walk.return_range.as_ref() {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        };
                    }
                    let related = !wanted.each && !walk.return_lost && !seek_block(body, &Seek::Unvisited(walk.return_seen.copy_owned()), words);
                    let made = ReturnsWalked { asked, reads: reads.copy_owned(), rules: rules.copy_owned(), returned: match proven.returned.as_ref() {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, sized: sized_seen, range: range_seen, related, at_least: nikaia_std::index::or(match walk.return_at_least.as_ref() {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || collections::BTreeSet::new().into()), within: nikaia_std::index::or(match walk.return_within.as_ref() {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || collections::BTreeSet::new().into()), under: nikaia_std::index::or(match walk.return_under.as_ref() {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || collections::BTreeSet::new().into()) };
                    if fresh { walked.insert(nikaia_std::block::Text::from(key.to_string()), made.clone()); }
                    seen = Some(made);
                }
                let last = match seen { Some(__nikaia_value) => __nikaia_value, None => continue };
                let mut held: collections::BTreeSet<i64> = collections::BTreeSet::new();
                let mut sized: collections::BTreeSet<i64> = collections::BTreeSet::new();
                for k in nikaia_std::index::or(last.returned, || collections::BTreeSet::new().into()) {
                    if wanted.below.contains(&k) {
                        held.insert(k);
                        if last.sized.contains(&k) { sized.insert(k); }
                    }
                }
                let mut range = match last.range.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                };
                let mut at_least: collections::BTreeSet<i64> = collections::BTreeSet::new();
                let mut within: collections::BTreeSet<i64> = collections::BTreeSet::new();
                let mut under: collections::BTreeSet<i64> = collections::BTreeSet::new();
                if last.related {
                    at_least = last.at_least.copy_owned();
                    within = last.within.copy_owned();
                    under = bounding_kept(&wanted.under, &last.under);
                }
                if range.is_some() && !wanted.pending {
                    let found_range = nikaia_std::index::or(range, || Range::open());
                    if !nikaia_std::index::or(wanted.range, || Range::open()).holds(&found_range) || wanted.range.is_none() { range = None; } else {
                        range = match wanted.range.as_ref() {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        };
                    }
                }
                let mut lengths: collections::BTreeMap<String, collections::BTreeSet<i64>> = collections::BTreeMap::new();
                let mut reaches: collections::BTreeMap<String, collections::BTreeSet<i64>> = collections::BTreeMap::new();
                let mut alike: collections::BTreeSet<String> = collections::BTreeSet::new();
                let mut guards: collections::BTreeSet<i64> = collections::BTreeSet::new();
                if !wanted.lengths.is_empty() || !wanted.alike.is_empty() {
                    let mut kept: Option<ReturnsMeasured> = None;
                    if fresh && measured.contains_key(&key) {
                        let got = match measured.get(&key) { Some(__nikaia_value) => __nikaia_value, None => continue };
                        if got.lengths_asked == wanted.lengths && got.alike_asked == wanted.alike && got.listed == wanted.listed && got.reads == reads && got.rules == rules { kept = Some(got.clone()); }
                    }
                    if kept.is_none() {
                        let mut measuring = bounding_new(args, body, bp_names(&nonnegative_locals(body), words), &context, program, words);
                        measuring.return_wanted = wanted.lengths.copy_owned();
                        measuring.return_wanted_alike = wanted.alike.copy_owned();
                        measuring.return_listed = wanted.listed.copy_owned();
                        let mut guards_seen: collections::BTreeSet<i64> = collections::BTreeSet::new();
                        for k in 0..args.len() as i64 {
                            let param = nikaia_std::block::Text::from(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.name).to_string());
                            let mut stays = !seek_block(body, &Seek::Rebound(nikaia_std::block::Text::from(param.to_string())), words);
                            if wanted.listed.contains(&k) {
                                if unsafe { nikaia_std::proven::read(&args, (k) as usize) }.mutable { stays = length_stays(body, &param, words); }
                                stays = stays && measuring.lists.contains(&param);
                            } else if stays && unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.generics.is_empty() && is_whole_number(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.name)) {
                                guards_seen.insert(k);
                                measuring.return_assumed.push(nikaia_std::block::Text::from(param.to_string()));
                            }
                            measuring.return_sources.push(if stays { param } else { String::from("") });
                        }
                        bounds_rounds(&mut measuring, args, body, &context, program, words, &mut *ask);
                        let mut made = ReturnsMeasured { lengths_asked: wanted.lengths.copy_owned(), alike_asked: wanted.alike.copy_owned(), listed: wanted.listed.copy_owned(), reads: reads.copy_owned(), rules: rules.copy_owned(), lengths: collections::BTreeMap::new(), reaches: collections::BTreeMap::new(), alike: collections::BTreeSet::new(), guards: guards_seen };
                        if !seek_block(body, &Seek::Unvisited(measuring.return_measured.copy_owned()), words) {
                            made.lengths = bounding_nonempty(&nikaia_std::index::or(measuring.return_lengths, || collections::BTreeMap::new().into()));
                            made.reaches = bounding_nonempty(&nikaia_std::index::or(measuring.return_reaches, || collections::BTreeMap::new().into()));
                            made.alike = nikaia_std::index::or(match measuring.return_alike.as_ref() {
                                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                                None => None,
                            }, || collections::BTreeSet::new().into());
                        }
                        if fresh { measured.insert(nikaia_std::block::Text::from(key.to_string()), made.clone()); }
                        kept = Some(made);
                    }
                    let got = match kept { Some(__nikaia_value) => __nikaia_value, None => continue };
                    lengths = got.lengths.copy_owned();
                    reaches = got.reaches.copy_owned();
                    alike = got.alike.copy_owned();
                    guards = got.guards.copy_owned();
                }
                if !held.is_empty() || range.is_some() || !at_least.is_empty() || !within.is_empty() || !lengths.is_empty() || !reaches.is_empty() || !alike.is_empty() { found.insert(nikaia_std::block::Text::from(key.to_string()), BoundsReturns { each: wanted.each, below: held, sized, range, pending: false, at_least, within, under, fields: wanted.fields.copy_owned(), plain: wanted.plain, measures: wanted.measures.copy_owned(), lengths, reaches, listed: wanted.listed.copy_owned(), alike, guards, projected: nikaia_std::block::Text::from(wanted.projected.to_string()) }); }
            },
            _ => { },
        }
    }
    context.around.held.clear();
    found
}

pub(crate) fn bounding_returned_range(walk: &BoundsWalk) -> Option<Range> {
    let mut out: Option<Range> = None;
    for name in walk.return_names.iter() {
        if !walk.written.contains_key(name) && !bounding_poisoned(walk, name) { continue; }
        let bound = match walk.assumed.get(name) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if out.is_none() { out = Some(bound.clone()); } else { out = Some(nikaia_std::index::or(out, || Range::open()).join(bound)); }
    }
    let range = match out { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !range.is_bounded() { return None; }
    Some(range)
}

pub(crate) fn bounding_returns_each(ty: &Type, words: &winnow_grammar::InternerContext) -> Option<bool> {
    if ty.is_nullable || ty.is_tuple { return None; }
    let name = words.resolve(ty.name);
    if ty.generics.is_empty() && is_whole_number(name) { return Some(false); }
    if ty.generics.len() == 1 && (name == "Vec" || name == "List") {
        let inner = unsafe { nikaia_std::proven::read(&ty.generics, (0) as usize) };
        if !inner.is_nullable && !inner.is_tuple && inner.generics.is_empty() && is_whole_number(words.resolve(inner.name)) { return Some(true); }
    }
    None
}

pub(crate) fn bounding_returns_kind(ty: &Type, words: &winnow_grammar::InternerContext) -> Option<bool> {
    if ty.is_nullable && !ty.is_tuple && ty.generics.is_empty() && is_whole_number(words.resolve(ty.name)) { return Some(false); }
    bounding_returns_each(ty, words)
}

pub(crate) fn bounding_returns_ranged(returns: &collections::BTreeMap<String, BoundsReturns>) -> i64 {
    let mut out: i64 = 0;
    for (_name, found) in returns.iter() { if !found.each && found.range.is_some() { out = unsafe { nikaia_std::proven::add::<i64>(out, 1) }; } }
    out
}

pub(crate) fn bounding_returns_count(returns: &collections::BTreeMap<String, BoundsReturns>) -> i64 {
    let mut out: i64 = 0;
    for (_name, found) in returns.iter() {
        out += unsafe { nikaia_std::proven::add::<i64>(nikaia_std::proven::add::<i64>(nikaia_std::proven::add::<i64>(found.below.len() as i64, found.at_least.len() as i64), found.within.len() as i64), found.under.len() as i64) } + found.alike.len() as i64;
        for (_m, positions) in found.lengths.iter() { out += positions.len() as i64; }
        for (_m, positions) in found.reaches.iter() { out += positions.len() as i64; }
        if found.range.is_some() { out += 1; }
    }
    out
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_returned(walk: &mut BoundsWalk, facts: &BoundsFacts, returned: Option<&Expr>, throwing: bool, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if throwing { return; }
    if bounding_null_returned(returned) {
        walk.return_seen.insert(node_key(match returned { Some(__nikaia_value) => __nikaia_value, None => return }));
        return;
    }
    bounding_return_lengths(walk, facts, returned, context, program, words, &mut *ask);
    if !walk.return_field.is_empty() {
        let built = match returned { Some(__nikaia_value) => __nikaia_value, None => {
            walk.return_lost = true;
            walk.return_unranged = true;
            return;
        } };
        walk.return_seen.insert(node_key(built));
        let field = nikaia_std::block::Text::from(walk.return_field.to_string());
        let picked = match bounding_field_built(built, &field, words) { Some(__nikaia_value) => __nikaia_value, None => {
            walk.return_lost = true;
            walk.return_unranged = true;
            return;
        } };
        bounding_returned_value(walk, facts, Some(&picked), context, program, words, &mut *ask);
        return;
    }
    bounding_returned_value(walk, facts, returned, context, program, words, &mut *ask);
}

pub(crate) fn bounding_null_returned(returned: Option<&Expr>) -> bool {
    let given = match returned { Some(__nikaia_value) => __nikaia_value, None => return false };
    matches!(given, Expr::LitNull(_))
}

pub(crate) fn bounding_returned_value(walk: &mut BoundsWalk, facts: &BoundsFacts, returned: Option<&Expr>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if walk.return_ranging {
        bounding_return_range(walk, facts, returned, context, program, words, &mut *ask);
        bounding_return_relations(walk, facts, returned, context, program, words, &mut *ask);
    }
    if walk.return_params.is_empty() {
        if walk.return_ranging {
            let seen = match returned { Some(__nikaia_value) => __nikaia_value, None => return };
            walk.return_seen.insert(node_key(seen));
        }
        return;
    }
    let value = match returned { Some(__nikaia_value) => __nikaia_value, None => {
        walk.return_lost = true;
        return;
    } };
    walk.return_seen.insert(node_key(value));
    if walk.return_each {
        match value {
            Expr::Variable(name, _) => {
                let name = *name;
                let list = words.resolve(name);
                if walk.shape.roots.contains(list) { walk.return_names.insert(nikaia_std::block::Text::from(list.to_string())); } else { walk.return_lost = true; }
            },
            Expr::ListLit { items, .. } => { if !items.is_empty() { walk.return_lost = true; } },
            _ => { walk.return_lost = true; },
        }
        return;
    }
    let called = bounding_returned_below(walk, value, false, context, words);
    let term = bounding_lin(walk, value, facts, context, program, words);
    let mut below: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for k in 0..walk.return_params.len() as i64 {
        let param = nikaia_std::block::Text::from((*unsafe { nikaia_std::proven::read(&walk.return_params, (k) as usize) }).to_string());
        if param.is_empty() { continue; }
        if called.contains_key(&param) {
            below.insert(k);
            continue;
        }
        let v = match term { Some(__nikaia_value) => __nikaia_value, None => continue };
        let zero = walk.arena.int(0);
        let len = walk.arena.var(&length_of(&param));
        let low = walk.arena.ge(v, zero);
        let high = walk.arena.lt(v, len);
        let goal = walk.arena.and(vec![low, high]);
        if bounding_proves(&walk, facts, goal, &mut *ask) { below.insert(k); }
    }
    let before = match match walk.return_below.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => {
        walk.return_below = Some(below);
        return;
    } };
    let mut kept: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for k in before.iter() {
        let k = nikaia_std::num::value(k);
        if below.contains(&k) { kept.insert(k); }
    }
    walk.return_below = Some(kept);
}

pub(crate) fn bounding_returns_measures(ty: &Type, fields: &collections::BTreeMap<String, Vec<String>>, words: &winnow_grammar::InternerContext) -> Vec<String> {
    if ty.is_nullable || ty.is_tuple { return vec![]; }
    if bounding_is_list_type(ty, words) { return vec![String::from("")]; }
    if !ty.generics.is_empty() { return vec![]; }
    nikaia_std::index::or(match fields.get(words.resolve(ty.name)) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into())
}

pub(crate) fn bounding_returns_measured(found: &mut BoundsReturns, measures: &[String], args: &[FnArg], words: &winnow_grammar::InternerContext) {
    let mut sources: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for k in 0..args.len() as i64 {
        if bounding_is_list_type(&unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty, words) {
            found.listed.insert(k);
            sources.insert(k);
        } else if unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.generics.is_empty() && is_whole_number(words.resolve(unsafe { nikaia_std::proven::read(&args, (k) as usize) }.ty.name)) { sources.insert(k); }
    }
    for m in measures.iter() {
        if !sources.is_empty() {
            found.lengths.insert(nikaia_std::block::Text::from(m.to_string()), sources.copy_owned());
            found.reaches.insert(nikaia_std::block::Text::from(m.to_string()), sources.copy_owned());
        }
        for other in measures.iter() { if !m.is_empty() && AsRef::<str>::as_ref(&(m)) < AsRef::<str>::as_ref(&(other)) { found.alike.insert(format!("{}|{}", m, other)); } }
    }
    found.measures = measures.copy_owned();
}

pub(crate) fn bounding_nonempty(sets: &collections::BTreeMap<String, collections::BTreeSet<i64>>) -> collections::BTreeMap<String, collections::BTreeSet<i64>> {
    let mut out: collections::BTreeMap<String, collections::BTreeSet<i64>> = collections::BTreeMap::new();
    for (m, positions) in sets.iter() { if !positions.is_empty() { out.insert(nikaia_std::block::Text::from(m.to_string()), positions.copy_owned()); } }
    out
}

pub(crate) fn bounding_return_lengths(walk: &mut BoundsWalk, facts: &BoundsFacts, returned: Option<&Expr>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) {
    if walk.return_wanted.is_empty() && walk.return_wanted_alike.is_empty() { return; }
    let mut lengths: collections::BTreeMap<String, collections::BTreeSet<i64>> = collections::BTreeMap::new();
    let mut reaches: collections::BTreeMap<String, collections::BTreeSet<i64>> = collections::BTreeMap::new();
    let mut alike: collections::BTreeSet<String> = collections::BTreeSet::new();
    let value = match returned { Some(__nikaia_value) => __nikaia_value, None => {
        walk.return_lengths = Some(lengths);
        walk.return_reaches = Some(reaches);
        walk.return_alike = Some(alike);
        return;
    } };
    walk.return_measured.insert(node_key(value));
    let mut given = facts.clone();
    let mut base = nikaia_std::index::or(path_of(value, words), || "".into());
    if base.is_empty() {
        base = String::from("result#");
        let measured = bounding_measured(walk, facts, &base, &base, value, context, program, words);
        bounding_forget(&walk, &mut given, &base);
        bounding_built(walk, &mut given, &base, value, words);
        for fact in measured.iter() {
            let fact = nikaia_std::num::value(fact);
            bounding_push(&walk, &mut given, fact);
        }
    }
    for (m, asked) in walk.return_wanted.copy_owned() {
        let path = if m.is_empty() { nikaia_std::block::Text::from(base.to_string()) } else { format!("{}.{}", base, m) };
        let len = bounding_length_named(walk, &path, false);
        let before = match (match walk.return_lengths.as_ref() {
            Some(__nikaia_it) => __nikaia_it.get(&m),
            None => None,
        }) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        let before_reach = match (match walk.return_reaches.as_ref() {
            Some(__nikaia_it) => __nikaia_it.get(&m),
            None => None,
        }) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        let mut equal: collections::BTreeSet<i64> = collections::BTreeSet::new();
        let mut least: collections::BTreeSet<i64> = collections::BTreeSet::new();
        for k in asked.iter() {
            let k = nikaia_std::num::value(k);
            if k >= walk.return_sources.len() as i64 || (*nikaia_std::index::get(&walk.return_sources, nikaia_std::index::at(k))).is_empty() { continue; }
            let held_equal = nikaia_std::index::or(match before.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.contains(&k)),
                None => None,
            }, || (walk.return_lengths.is_none()).into());
            let held_least = nikaia_std::index::or(match before_reach.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.contains(&k)),
                None => None,
            }, || (walk.return_reaches.is_none()).into());
            if !held_equal && !held_least { continue; }
            let source = nikaia_std::block::Text::from((*nikaia_std::index::get(&walk.return_sources, nikaia_std::index::at(k))).to_string());
            let term = if walk.return_listed.contains(&k) { bounding_length_named(walk, &source, false) } else { walk.arena.var(&source) };
            if held_equal {
                let goal = walk.arena.equal(len, term);
                if bounding_proves(&walk, &given, goal, &mut *ask) {
                    equal.insert(k);
                    continue;
                }
            }
            let goal = walk.arena.ge(len, term);
            if bounding_proves(&walk, &given, goal, &mut *ask) { least.insert(k); }
        }
        lengths.insert(nikaia_std::block::Text::from(m.to_string()), equal);
        reaches.insert(nikaia_std::block::Text::from(m.to_string()), least);
    }
    for pair in walk.return_wanted_alike.copy_owned() {
        if walk.return_alike.is_some() && !nikaia_std::index::or(match walk.return_alike.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.contains(&pair)),
            None => None,
        }, || false) { continue; }
        let parts: Vec<&str> = pair.split('|').collect::<Vec<_>>();
        if parts.len() != 2 { continue; }
        let a = bounding_length_named(walk, &format!("{}.{}", base, *unsafe { nikaia_std::proven::read(&parts, (0) as usize) }), false);
        let b = bounding_length_named(walk, &format!("{}.{}", base, *unsafe { nikaia_std::proven::read(&parts, (1) as usize) }), false); ::core::mem::drop(parts);
        let goal = walk.arena.equal(a, b);
        if bounding_proves(&walk, &given, goal, &mut *ask) { alike.insert(nikaia_std::block::Text::from(pair.to_string())); }
    }
    if walk.return_lengths.is_some() {
        let was = nikaia_std::index::or(std::mem::take(&mut walk.return_lengths), || collections::BTreeMap::new().into());
        let was_reach = nikaia_std::index::or(std::mem::take(&mut walk.return_reaches), || collections::BTreeMap::new().into());
        let mut kept: collections::BTreeMap<String, collections::BTreeSet<i64>> = collections::BTreeMap::new();
        let mut kept_reach: collections::BTreeMap<String, collections::BTreeSet<i64>> = collections::BTreeMap::new();
        for (m, now) in lengths.iter() {
            let old = nikaia_std::index::or(match was.get(m) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into());
            let old_reach = nikaia_std::index::or(match was_reach.get(m) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into());
            let now_reach = nikaia_std::index::or(match reaches.get(m) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into());
            let mut same: collections::BTreeSet<i64> = collections::BTreeSet::new();
            let mut most: collections::BTreeSet<i64> = collections::BTreeSet::new();
            for k in now.iter() {
                let k = nikaia_std::num::value(k);
                if old.contains(&k) { same.insert(k); } else if old_reach.contains(&k) { most.insert(k); }
            }
            for k in now_reach.iter() {
                let k = nikaia_std::num::value(k);
                if old.contains(&k) || old_reach.contains(&k) { most.insert(k); }
            }
            kept.insert(nikaia_std::block::Text::from(m.to_string()), same);
            kept_reach.insert(nikaia_std::block::Text::from(m.to_string()), most);
        }
        lengths = kept;
        reaches = kept_reach;
        alike = bounding_kept_names(&nikaia_std::index::or(std::mem::take(&mut walk.return_alike), || collections::BTreeSet::new().into()), &alike);
    }
    walk.return_lengths = Some(lengths);
    walk.return_reaches = Some(reaches);
    walk.return_alike = Some(alike);
}

pub(crate) fn bounding_kept_names(before: &collections::BTreeSet<String>, now: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut kept: collections::BTreeSet<String> = collections::BTreeSet::new();
    for name in before.iter() { if now.contains(name) { kept.insert(nikaia_std::block::Text::from(name.to_string())); } }
    kept
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_measured(walk: &mut BoundsWalk, facts: &BoundsFacts, root: &str, name: &str, value: &Expr, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    match value {
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() {
                let given = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                let path = format!("{}.{}", name, words.resolve(field.name));
                for fact in bounding_measured(walk, facts, root, &path, given, context, program, words) { out.push(fact); }
            }
            return out;
        },
        Expr::Call { .. } => { },
        Expr::MethodCall { .. } => { },
        _ => { return out; },
    }
    if bounding_found_options(value) { return out; }
    let callee = match bounding_found_key(&walk, value, context, words) { Some(__nikaia_value) => __nikaia_value, None => return out };
    walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
    let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return out };
    if found.pending { return out; }
    let mut below: Vec<i64> = vec![];
    below.reserve(found.guards.iter().size_hint().0); for k in found.guards.iter() {
        let k = nikaia_std::num::value(k);
        let term = match bounding_found_term(walk, value, k, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => return out };
        if bounding_touches(&walk, term, root) { return out; }
        let zero = walk.arena.int(0);
        below.push(walk.arena.lt(term, zero));
    }
    let mut stated: Vec<i64> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for at_least in [false, true] {
        let sets = if at_least { found.reaches.copy_owned() } else { found.lengths.copy_owned() };
        for (m, positions) in sets.iter() {
            let path = if m.is_empty() { nikaia_std::block::Text::from(name.to_string()) } else { format!("{}.{}", name, m) };
            let len = bounding_length_named(walk, &path, false);
            stated.reserve(positions.iter().size_hint().0); for k in positions.iter() {
                let k = nikaia_std::num::value(k);
                let term = if found.listed.contains(&k) {
                    let arg = match bounding_found_path(value, found, k, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    if walk.pinned.contains(&path_root(&arg)) { continue; }
                    bounding_length_named(walk, &arg, false)
                } else { match bounding_found_term(walk, value, k, facts, context, program, words) { Some(__nikaia_value) => __nikaia_value, None => continue } };
                if bounding_touches(&walk, term, root) { continue; }
                stated.push(if at_least { walk.arena.ge(len, term) } else { walk.arena.equal(len, term) });
            }
        }
    }
    stated.reserve(found.alike.iter().size_hint().0); for pair in found.alike.iter() {
        let parts: Vec<&str> = pair.split('|').collect::<Vec<_>>();
        if parts.len() != 2 { continue; }
        let a = bounding_length_named(walk, &format!("{}.{}", name, *unsafe { nikaia_std::proven::read(&parts, (0) as usize) }), false);
        let b = bounding_length_named(walk, &format!("{}.{}", name, *unsafe { nikaia_std::proven::read(&parts, (1) as usize) }), false);
        stated.push(walk.arena.equal(a, b));
    }
    for fact in stated.iter() {
        let fact = nikaia_std::num::value(fact);
        if below.is_empty() { out.push(fact); } else {
            let mut either = below.copy_owned();
            either.push(fact);
            out.push(walk.arena.or(either));
        }
    }
    out
}

pub(crate) fn bounding_returns_found(walk: &BoundsWalk, body: &Block, words: &winnow_grammar::InternerContext) -> Option<collections::BTreeSet<i64>> {
    if walk.return_lost || seek_block(body, &Seek::Unvisited(walk.return_seen.copy_owned()), words) { return None; }
    if !walk.return_each {
        return match walk.return_below.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
    }
    let mut out: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for k in 0..walk.return_params.len() as i64 {
        let param = unsafe { nikaia_std::proven::read(&walk.return_params, (k) as usize) };
        if param.is_empty() { continue; }
        let mut held = true;
        for name in walk.return_names.iter() {
            let ends = match walk.assumed_ends.get(name) { Some(__nikaia_value) => __nikaia_value, None => {
                held = false;
                break;
            } };
            if !ends.contains(param) || !bounding_end_list(walk, param, name) {
                held = false;
                break;
            }
        }
        if held { out.insert(k); }
    }
    Some(out)
}

pub(crate) fn bounding_returned_below(walk: &mut BoundsWalk, value: &Expr, each: bool, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> collections::BTreeMap<String, bool> {
    let mut out: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    let callee = match bounding_found_key(&walk, value, context, words) { Some(__nikaia_value) => __nikaia_value, None => return out };
    walk.found_asked.insert(nikaia_std::block::Text::from(callee.to_string()));
    walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
    let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return out };
    if found.each != each { return out; }
    for k in found.below.iter() {
        let k = nikaia_std::num::value(k);
        let path = match bounding_found_path(value, found, k, words) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !walk.pinned.contains(&path_root(&path)) { out.insert(path, found.sized.contains(&k)); }
    }
    out
}

pub(crate) fn bounding_found_key(walk: &BoundsWalk, value: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Option<String> {
    let callee = match bounding_found_callee(walk, value, context, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !walk.found_field.is_empty() && node_key(value) == walk.found_at { return Some(bounding_projected_key(&callee, &walk.found_field)); }
    Some(callee)
}

pub(crate) fn bounding_found_callee(walk: &BoundsWalk, value: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Option<String> {
    match value {
        Expr::Call { func, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = match bounding_callee(func, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if walk.shape.bound.contains(&callee) { return None; }
            Some(callee)
        },
        Expr::MethodCall { method, .. } => {
            let method = *method;
            let owner = match context.std_receivers.get(&node_key(value)) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(format!("{}.{}", owner, words.resolve(method)))
        },
        _ => None,
    }
}

pub(crate) fn bounding_found_options(value: &Expr) -> bool {
    match value {
        Expr::Call { config, .. } => !config.is_empty(),
        Expr::MethodCall { config, .. } => !config.is_empty(),
        _ => false,
    }
}

pub(crate) fn bounding_found_path(value: &Expr, found: &BoundsReturns, k: i64, words: &winnow_grammar::InternerContext) -> Option<String> {
    match value {
        Expr::Call { args, .. } => {
            if k < 0 || k >= args.len() as i64 { return None; }
            bounding_argument_path(unsafe { nikaia_std::proven::read(&args, (k) as usize) }, words)
        },
        Expr::MethodCall { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            if k >= 0 && k < args.len() as i64 { return bounding_argument_path(unsafe { nikaia_std::proven::read(&args, (k) as usize) }, words); }
            let j = k - args.len() as i64;
            if j < 0 || j >= found.fields.len() as i64 { return None; }
            let on = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(format!("{}.{}", on, *unsafe { nikaia_std::proven::read(&found.fields, (j) as usize) }))
        },
        _ => None,
    }
}

pub(crate) fn bounding_found_term(walk: &mut BoundsWalk, value: &Expr, k: i64, facts: &BoundsFacts, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext) -> Option<i64> {
    match value {
        Expr::Call { args, .. } => {
            if k < 0 || k >= args.len() as i64 { return None; }
            bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, facts, context, program, words)
        },
        Expr::MethodCall { args, .. } => {
            if k < 0 || k >= args.len() as i64 { return None; }
            bounding_lin(walk, unsafe { nikaia_std::proven::read(&args, (k) as usize) }, facts, context, program, words)
        },
        _ => None,
    }
}

pub(crate) fn bounding_returned_values(walk: &mut BoundsWalk, value: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) -> Option<Range> {
    match value {
        Expr::Call { func, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = match bounding_callee(func, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if walk.shape.bound.contains(&callee) { return None; }
            walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
            let found = match context.returns.get(&callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if !found.each || found.pending { return None; }
            match found.range.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }
        },
        _ => None,
    }
}

pub(crate) fn bounding_call_root(walk: &mut BoundsWalk, key: &str, value: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let callee = match value {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); nikaia_std::index::or(bounding_callee(func, words), || "".into()) },
        _ => String::from(""),
    };
    walk.found_read.insert(nikaia_std::block::Text::from(callee.to_string()));
    let found = context.returns.get(&callee);
    if found.is_none() || !nikaia_std::index::or(found.as_ref().map(|__nikaia_it| __nikaia_it.each), || false) || nikaia_std::index::or(found.as_ref().map(|__nikaia_it| __nikaia_it.pending), || false) { return; }
    let range = bounding_returned_values(walk, value, context, words);
    if range.is_some() { bounding_join(walk, key, nikaia_std::index::or(range, || Range::open())); } else { walk.poisoned.insert(nikaia_std::block::Text::from(key.to_string())); }
    let mut below: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (list, _sized) in bounding_returned_below(walk, value, true, context, words) { if bounding_end_list(&walk, &list, key) { below.insert(nikaia_std::block::Text::from(list.to_string())); } }
    let was = match walk.written_ends.get(key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if was.is_some() {
        let mut kept: collections::BTreeSet<String> = collections::BTreeSet::new();
        for list in nikaia_std::index::or(was, || collections::BTreeSet::new().into()) { if below.contains(&list) { kept.insert(nikaia_std::block::Text::from(list.to_string())); } }
        below = kept;
    }
    walk.written_ends.insert(nikaia_std::block::Text::from(key.to_string()), below);
}

pub(crate) fn bounding_argument_path(arg: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match arg {
        Expr::Unary { op: UnaryOp::Ref, expr, .. } => { let expr = nikaia_std::boxed::open(expr); path_of(expr, words) },
        _ => path_of(arg, words),
    }
}

pub(crate) fn bounding_returned_facts(walk: &mut BoundsWalk, facts: &mut BoundsFacts, name: &str, value: &Expr, context: &BoundsContext, words: &winnow_grammar::InternerContext) {
    let lists = bounding_returned_below(walk, value, false, context, words);
    if lists.is_empty() { return; }
    let n = walk.arena.var(name);
    let zero = walk.arena.int(0);
    let low = walk.arena.ge(n, zero);
    bounding_push(&walk, facts, low);
    for (list, sized) in lists.iter() {
        let sized = nikaia_std::num::value(sized);
        let len = bounding_length_named(walk, list, sized);
        let high = walk.arena.lt(n, len);
        bounding_push(&walk, facts, high);
    }
}

pub(crate) fn bounding_projected_key(callee: &str, field: &str) -> String {
    if field.is_empty() { return nikaia_std::block::Text::from(callee.to_string()); }
    format!("{}#{}", callee, field)
}

pub(crate) fn bounding_struct_wholes(ty: &Type, whole_fields: &collections::BTreeMap<String, Vec<String>>, words: &winnow_grammar::InternerContext) -> Vec<String> {
    if ty.is_nullable || ty.is_tuple || !ty.generics.is_empty() { return vec![]; }
    nikaia_std::index::or(match whole_fields.get(words.resolve(ty.name)) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into())
}

pub(crate) fn bounding_field_built(built: &Expr, field: &str, words: &winnow_grammar::InternerContext) -> Option<Expr> {
    match built {
        Expr::StructLit { fields, .. } => {
            for each in fields.iter() {
                if words.resolve(each.name) != field { continue; }
                return Some(match &each.value {
                    None => Expr::Variable(each.name, node_id::NodeId::fresh()),
                    Some(written) => written.clone(),
                });
            }
            None
        },
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn bounding_fields_found(walk: &mut BoundsWalk, facts: &BoundsFacts, name: &str, value: &Expr, paths: &mut Vec<String>, context: &BoundsContext, program: &Program, words: &winnow_grammar::InternerContext, ask: &mut impl FnMut(&logic::TermArena, &[i64], i64) -> bool) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    let call = matches!(value, Expr::Call { .. } | Expr::MethodCall { .. });
    if !call || bounding_found_options(value) { return out; }
    let callee = match bounding_found_key(&walk, value, context, words) { Some(__nikaia_value) => __nikaia_value, None => return out };
    let prefix = format!("{}#", callee);
    walk.found_read.insert(nikaia_std::block::Text::from(prefix.to_string()));
    let mut projected: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for (key, found) in context.returns.iter() { if key.starts_with(&*prefix) && !found.each && !found.pending { projected.push(nikaia_std::block::Text::from(found.projected.to_string())); } }
    paths.reserve(projected.iter().size_hint().0); for field in projected.iter() {
        let path = format!("{}.{}", name, field);
        walk.found_at = node_key(value);
        walk.found_field = nikaia_std::block::Text::from(field.to_string());
        let relations = bounding_relations_of(walk, facts, &path, value, context, program, words, &mut *ask);
        let mut given = facts.clone();
        given.facts = vec![];
        bounding_returned_facts(walk, &mut given, &path, value, context, words);
        bounding_relations_push(walk, &mut given, &path, &relations);
        let range = nikaia_std::index::or(bounding_range(walk, value, facts, context, program, words, &mut *ask), || Range::open());
        walk.found_at = -1;
        walk.found_field = String::from("");
        let n = walk.arena.var(&path);
        if range.lo.is_some() {
            let least = walk.arena.int(nikaia_std::index::or(range.lo, || 0));
            let low = walk.arena.ge(n, least);
            bounding_push(&walk, &mut given, low);
        }
        if range.hi.is_some() {
            let most = walk.arena.int(nikaia_std::index::or(range.hi, || 0));
            let high = walk.arena.le(n, most);
            bounding_push(&walk, &mut given, high);
        }
        for fact in given.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            walk.arena.variables(fact, &mut read);
            let mut stale = false;
            for v in read.iter() { if *v != path && path_within(v, name) { stale = true; } }
            if !stale { out.push(fact); }
        }
        paths.push(path);
    }
    out
}

